import { useEffect, useState, useCallback, useMemo, useRef } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import {
  LayoutGrid,
  Download,
  RefreshCw,
  CalendarDays,
  AlertTriangle,
  UserCheck,
  HelpCircle,
  Clock,
  Activity,
  Crown,
  Plus,
  Minus,
  Sparkles,
  History,
  ChevronUp,
  Pencil,
  Trash2,
  X,
  BarChart3,
  ChevronRight,
  MapPin,
  Users,
  Radio,
  Search,
  ChevronLeft,
  ChevronDown,
  Phone,
  Briefcase,
  Globe2,
  BadgeCheck,
  StickyNote,
  Bell,
  Ban,
  LocateFixed,
  Siren,
  BedDouble,
} from "lucide-react";
import { apiGet, apiPost, apiPatch, apiDelete, getPermissions } from "../../lib/api.js";
import { getCurrentLocationString, geolocationErrorMessage } from "../../lib/geolocation.js";
import { useVisiblePolling } from "../../lib/useVisiblePolling.js";
import StatusBadge from "../../components/StatusBadge.jsx";
import AnalyticsPanel from "../../components/AnalyticsPanel.jsx";
import DelegateAvatar, { statusTone } from "../../components/DelegateAvatar.jsx";
import DelegateLocationMap from "../../components/DelegateLocationMap.jsx";
import DelegateTimeline from "../../components/DelegateTimeline.jsx";
import ExportModal from "../../components/ExportModal.jsx";
import PhotoCropModal from "../../components/PhotoCropModal.jsx";
import { useLang } from "../../lib/i18n.jsx";

/**
 * Screen 2 — Admin Dashboard & Analytics (Jun Qi).
 *
 * Use Case 5 — Real-Time "Missing Person" Identification & Analytics.
 *
 * CRUD build: the delegate list starts empty. Create / edit / delete delegates
 * from the "All delegates" card and every read view above it (KPI tiles, coach
 * bars, live activity, reverse-headcount missing list) recomputes live.
 *
 * Endpoints:
 *   GET    /api/trips/:id/dashboard    → KPIs + coach status + activity
 *   GET    /api/trips/:id/missing      → reverse-headcount list
 *   GET    /api/trips/:id/delegates    → all delegates (read)
 *   POST   /api/trips/:id/delegates    → create
 *   PATCH  /api/delegates/:id          → update
 *   DELETE /api/delegates/:id          → delete
 *   GET    /api/trips/:id/export       → Excel download
 */

const TRIP_ID = "t-1";
// Persists the trip switcher's choice across navigating away and back —
// DashboardPage fully unmounts on route change (it's not kept alive), so a
// plain useState(TRIP_ID) silently reset to Beijing every time you left the
// page and returned. localStorage survives the unmount; falls back to
// TRIP_ID if nothing's stored yet, or storage is unavailable.
const DASHBOARD_TRIP_KEY = "mg_dashboard_trip";
function loadSelectedTripId() {
  try { return localStorage.getItem(DASHBOARD_TRIP_KEY) || TRIP_ID; } catch { return TRIP_ID; }
}
function saveSelectedTripId(id) {
  try { localStorage.setItem(DASHBOARD_TRIP_KEY, id); } catch { /* ignore */ }
}

const EMPTY_FORM = {
  // status defaults to UNASSIGNED, not ARRIVED (2026-07-27 — "remove the
  // assigned to coach, cause that my teammate feature") — coach assignment
  // now happens on the Trips board (Desmond's drag-and-drop), not this
  // Dashboard modal; a NEW delegate created here starts Unassigned so it
  // never hits the backend's "coach required unless Unassigned" rule with
  // no coach picker left to satisfy it.
  name: "", coachId: "", status: "UNASSIGNED", vip: false, cancelled: false, cancelReason: "", lastSeen: "", lastLocation: "",
  company: "", role: "", industry: "", email: "", phone: "", website: "",
  passportNumber: "", nationality: "", passportExpiry: "", accessibilityNotes: "", notes: "",
  hotelName: "", roomNumber: "",
};

export default function DashboardPage() {
  const perms = getPermissions();
  // Two-role RBAC (simplified 2026-07-27 — "staff can view delegate +
  // checkpoint, admin views all, regardless of account control"): Staff sees
  // only the Delegate and Checkpoint history tabs; Room Management, Analytics
  // and Staff operations are admin-only, keyed off manageAccounts (which only
  // admins ever carry — see permissions.js's adminOnly doc). The old
  // per-account viewAnalytics toggle was removed from permissions.js the same
  // day, so Analytics is back to role-based, not grantable.
  const isAdmin = !!perms.manageAccounts;
  const { t, lang } = useLang();
  const navigate = useNavigate();
  const location = useLocation();
  // Arrived via EscalationBanner's "View" jump (2026-07-25 — "if I'm on a
  // different trip I don't know which trip to [go to]") — ?tripId= picks the
  // right trip below (overriding whatever was last persisted), and
  // ?escalationDelegate= is consumed once that trip's roster loads (see the
  // effect near the delegates state) to auto-open that delegate's profile.
  // Read once for the FIRST render only (a fresh page load already lands with
  // the right query string) — the reactive case (clicking "View" while
  // already ON /dashboard, so this component never remounts) is handled by
  // the separate `location.search`-watching effect further down; without
  // that second effect, a `useState(() => ...)` initializer like this one
  // never re-fires on a same-route navigation (2026-07-25 bugfix — "I click
  // View but it doesn't show, only works after I refresh").
  const initialEscalationParams = new URLSearchParams(location.search);
  const [pendingEscalationDelegateId, setPendingEscalationDelegateId] = useState(
    () => initialEscalationParams.get("escalationDelegate")
  );
  // Shared by every modal overlay below (only one is ever open at a time) —
  // only dismiss if the WHOLE click gesture started on the backdrop itself,
  // not wherever the mouse was released after a drag-select that began in a
  // field inside the modal.
  const downOnBackdrop = useRef(false);

  // The page is tall (KPIs, coach status, history, the full delegate table),
  // and browsers restore the previous scroll position on SPA route re-entry
  // by default — landing back on Dashboard scrolled to the bottom instead of
  // showing a fresh top-of-page view. Reset once on mount only (not on every
  // 2s poll re-render, which doesn't remount this component).
  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  // Lands on the tab this account actually works in; every content block is
  // independently gated, so an account with no visible tab renders nothing
  // rather than erroring — the same "no visible tabs" edge case App.jsx's
  // route fallbacks already accept.
  // Restructured 2026-07-28 ("move the all delegate to another tab called
  // delegate management, rename the delegate tab to overview, move the
  // checkpoint history / room management under the new delegate tab, so
  // overview for admin, delegate tab is for staff"):
  //   overview  — the at-a-glance read: KPI tiles, coach status, history
  //               tracker. Admin's landing view.
  //   delegates — the working area, with its own sub-tabs (All delegates /
  //               Checkpoint history / Room Management). Staff's landing view.
  //   analytics / staffops — unchanged, admin-only.
  // Each feature KEPT its original permission gate, so nothing became more or
  // less visible than before — only where it lives changed.
  const [tab, setTab] = useState(() => {
    if (!isAdmin && (perms.viewDelegates || perms.viewHistory)) return "delegates";
    if (perms.viewDashboard) return "overview";
    if (perms.viewDelegates || perms.viewHistory) return "delegates";
    return "overview";
  }); // "overview" | "delegates" | "analytics" | "staffops"
  // Sub-tab inside "delegates".
  const [delegateSubTab, setDelegateSubTab] = useState(() => {
    if (perms.viewDelegates) return "list";
    if (perms.viewHistory) return "checkpointHistory";
    return "rooms";
  }); // "list" | "checkpointHistory" | "rooms"
  const [data, setData] = useState(null);
  const [missing, setMissing] = useState([]);
  const [delegates, setDelegates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  // Live wall clock for the header chip (2026-07-29). Ticks every 15s rather
  // than every second: the display is HH:MM, so a per-second interval would
  // re-render the whole Dashboard 60x a minute to change nothing. 15s bounds
  // the visible lag to a quarter-minute, which nobody notices on a clock with
  // no seconds. `hour12: true` forced explicitly (2026-07-30 — "fix to 12 hr
  // format") rather than left to the viewer's locale: leaving it locale-driven
  // read as 24h here, which is what prompted the request.
  const [nowClock, setNowClock] = useState(() =>
    new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", hour12: true })
  );
  useEffect(() => {
    const id = setInterval(
      () => setNowClock(new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", hour12: true })),
      15000
    );
    return () => clearInterval(id);
  }, []);
  // Countdown to the next auto-refresh tick (2026-07-27 — "update this will
  // see how long it refresh") — the poll itself is a fixed 10s interval (see
  // the comment on that useEffect below); this is purely a visual "time
  // until next sync" next to the Live badge. 8 -> 10 (2026-07-30 — "can you
  // put sync to 10 sec").
  const REFRESH_SECONDS = 10;

  // Trip switcher — the whole dashboard re-points to the selected trip.
  // "t-1" = the default Beijing trip (unfiltered); anything else is a trip uuid.
  const [selectedTripId, setSelectedTripId] = useState(() => initialEscalationParams.get("tripId") || loadSelectedTripId());
  const [trips, setTrips] = useState([]);            // all trips (for the dropdown)
  const [mainTrip, setMainTrip] = useState(null);    // { uuid, name } of the base trip
  const [currentCheckpoint, setCurrentCheckpoint] = useState(null); // the itinerary stop that's "current" right now, or null
  const [nextCheckpoint, setNextCheckpoint] = useState(null); // whatever stop immediately follows it, or null (2026-07-25)
  // Every stop on TODAY's day, for the "Now:" chip's click-to-expand popover
  // (2026-07-30 — "the now:...8:00am is like telling me it's happening now
  // which is not" — "current" here means "the active leg of the schedule",
  // not literally this second; letting staff open the whole day at a glance
  // resolves that ambiguity better than any one-line label would).
  const [todayCheckpoints, setTodayCheckpoints] = useState([]);
  const [showTodayItinerary, setShowTodayItinerary] = useState(false);

  // "All delegates" table filter + sort
  const [delegateQuery, setDelegateQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("ALL");
  const [coachFilter, setCoachFilter] = useState("ALL"); // ALL | <coachId> — "Unassigned" lives on statusFilter only now
  const [sortMode, setSortMode] = useState("name"); // name | recent | status | coach
  // Pagination (2026-07-24 — replaced a "Show all" toggle that dumped every
  // matching delegate into the DOM at once; unusable once a trip had 100+).
  const [delegatePage, setDelegatePage] = useState(0);
  const [delegatePageSize, setDelegatePageSize] = useState(10);
  const [showAllCoaches, setShowAllCoaches] = useState(false);

  // Batch selection for "All delegates" — replaces the old blanket "Delete
  // all" button with per-row checkboxes + a "Delete selected" action.
  const [selectedDelegateIds, setSelectedDelegateIds] = useState(new Set());
  const [deletingSelectedDelegates, setDeletingSelectedDelegates] = useState(false);
  const [history, setHistory] = useState([]);

  // "Staff operations" tab — admin-only (manageAccounts), lives on this same
  // page rather than a separate route so admins don't have to leave the
  // Dashboard to see who's currently signed in.
  const [staffOps, setStaffOps] = useState(null); // { totalStaff, activeCount, active }
  const [staffOpsError, setStaffOpsError] = useState(null);
  // Search/filter for the Active sessions list — with 40+ people signed in
  // at once (a real SCCCI event) the plain unbroken list read as messy
  // (2026-07-24). Options are derived from whatever's actually in the
  // response, same "no separate lookup" approach used by other filters here.
  const [staffOpsSearch, setStaffOpsSearch] = useState("");
  const [staffOpsRoleFilter, setStaffOpsRoleFilter] = useState("ALL"); // ALL | admin | staff

  // Reverse headcount — opened on demand from a button on the "Coach status"
  // card, not a persistent tab (was one; the user liked the content but not
  // that UX, so it moved to an on-demand modal instead).
  const [headcountOpen, setHeadcountOpen] = useState(false);
  // Search/filter/sort for the Reverse headcount modal — with a large
  // roster, each coach's "still missing" list can run long enough to need
  // narrowing down instead of scanning the whole thing (2026-07-24).
  const [hcSearch, setHcSearch] = useState("");
  const [hcFilter, setHcFilter] = useState("all"); // all | missing | late | vip
  const [hcSort, setHcSort] = useState("name"); // name | status
  // Which coach cards are expanded (showing their missing-delegate list) —
  // with 20 coaches, showing every list open at once is exactly the "messy"
  // problem reported; collapse-by-default once there are more than a
  // handful, click a card's header to reveal just that one.
  const [expandedCoaches, setExpandedCoaches] = useState(new Set());
  const toggleCoachExpanded = (id) => setExpandedCoaches((prev) => {
    const next = new Set(prev);
    if (next.has(id)) next.delete(id); else next.add(id);
    return next;
  });
  // History tracker scope — "trip" (default) shows only the currently
  // selected trip's own activity; "all" is the old global mixed feed
  // (2026-07-24 — multiple trips' add/edit/remove events were piling into
  // one unreadable list together).
  const [historyScope, setHistoryScope] = useState("trip");
  // Default the compact History tracker card to TODAY's entries only
  // (2026-07-27 — "the history tracker section should display only today
  // stuff, then click to view more like ytd, 2 days before etc") — a click
  // reveals everything else already loaded (yesterday and earlier); the
  // full History Log page (`/history`) still has real per-day grouping and
  // filters for anything beyond what's already fetched here.
  const [historyShowAll, setHistoryShowAll] = useState(false);
  useEffect(() => { setHistoryShowAll(false); }, [selectedTripId, historyScope]);
  const [exportOpen, setExportOpen] = useState(false);
  const delegateTableRef = useRef(null);
  // Set by showDelegatesFiltered() when a KPI drill-down needs to scroll to the
  // roster table AFTER the tab switch has mounted it (2026-07-28).
  const pendingTableScroll = useRef(false);
  useEffect(() => {
    if (!pendingTableScroll.current) return;
    if (tab !== "delegates" || delegateSubTab !== "list") return;
    if (!delegateTableRef.current) return; // table still loading — retry next render
    pendingTableScroll.current = false;
    delegateTableRef.current.scrollIntoView({ behavior: "smooth", block: "start" });
  });


  // modal state
  const [modalOpen, setModalOpen] = useState(false);
  const [editingId, setEditingId] = useState(null); // null = creating
  const [form, setForm] = useState(EMPTY_FORM);
  const [showMoreFields, setShowMoreFields] = useState(false);
  const [saving, setSaving] = useState(false);
  const [formErr, setFormErr] = useState("");
  const [editingPhotoUrl, setEditingPhotoUrl] = useState(null);
  const [photoBusy, setPhotoBusy] = useState(false);
  const [photoErr, setPhotoErr] = useState("");
  // "Use my current location" for the Missing lastLocation field (2026-07-24)
  // — see lib/geolocation.js for what this actually reads (the STAFF
  // device's own GPS, not the delegate's).
  const [locating, setLocating] = useState(false);
  const [locateError, setLocateError] = useState(null);
  async function useMyLocation() {
    setLocating(true);
    setLocateError(null);
    try {
      const loc = await getCurrentLocationString();
      setForm((f) => ({ ...f, lastLocation: loc }));
    } catch (err) {
      setLocateError(geolocationErrorMessage(err));
    } finally {
      setLocating(false);
    }
  }
  const [mapDelegate, setMapDelegate] = useState(null); // delegate whose location map is open, or null (Reverse headcount's quick popup)
  // Delegate profile view — combines what used to be 3 separate popups
  // (edit modal's read-only fields, checkpoint timeline modal, location map
  // modal) into one scrollable panel opened by clicking a delegate row in
  // the main table (2026-07-24). Editing still opens the existing Create/
  // Edit modal via the profile's own "Edit" button.
  const [profileDelegate, setProfileDelegate] = useState(null);
  // Gate for actually OPENING the profile (2026-07-25, new
  // viewDelegateDetails permission) — every "open" call site below goes
  // through this instead of setProfileDelegate directly, so the gate lives
  // in one place rather than being repeated (and possibly missed) at each
  // of the several places a row/name can be clicked to open it.
  function openProfile(d) {
    if (perms.viewDelegateDetails) setProfileDelegate(d);
  }
  // Full-size photo lightbox — the profile panel's thumbnail is too small to
  // make out a face clearly; click it to view full-size (2026-07-24).
  const [enlargedPhoto, setEnlargedPhoto] = useState(null);
  // { delegate, reason } while the "Mark as cancelled" reason prompt is
  // open, else null — see toggleCancelled()/confirmCancel() below.
  const [cancelPrompt, setCancelPrompt] = useState(null);
  // Alerts moved out of the page flow entirely into a small icon-button +
  // modal beside Export (2026-07-24 feedback, second round — the collapsed
  // inline card still took a permanent row at the top of every visit; "move
  // the alert to a small icon button beside the export").
  const [alertsOpen, setAlertsOpen] = useState(false);
  // "Emergency" section inside this same Alerts modal (2026-07-25) —
  // acknowledging an escalation used to make it vanish entirely, which
  // doesn't scale once there are many open at once (e.g. 50 delegates
  // escalated at busy period). Open OR acknowledged (not yet resolved)
  // escalations stay listed here so staff can work through them at their
  // own pace instead of the top banner being the only place to see them.
  const [activeEscalations, setActiveEscalations] = useState([]);
  const [escalationBusyId, setEscalationBusyId] = useState(null);
  // Search + cap-at-5 for the Emergency section (2026-07-26 — "50 mock
  // escalations... abit hard to navigate") — Missing/Late/Cancelled below it
  // already cap at 5 with a "View all"/"Show more", Emergency was the one
  // section that dumped every row into one small scrollbox unfiltered.
  // Emergency has no equivalent delegate-status filter to route to (it's not
  // a delegate field), so "show more" expands in place instead of navigating.
  const [escalationQuery, setEscalationQuery] = useState("");
  const [showAllEscalations, setShowAllEscalations] = useState(false);
  // NOTE: the effect that fetches /escalations/active lives further down,
  // right after `currentTripUuid` is declared — it depends on that value,
  // which isn't available yet at this point in the component (2026-07-25,
  // fixing a "Cannot access 'currentTripUuid' before initialization" crash).
  async function acknowledgeEscalationRow(id) {
    setEscalationBusyId(id);
    try {
      await apiPost(`/escalations/${id}/acknowledge`, {});
      setActiveEscalations((prev) => prev.map((e) => (e.id === id ? { ...e, status: "acknowledged" } : e)));
    } catch { /* leave as-is — next open of the modal will reconcile */ }
    finally { setEscalationBusyId(null); }
  }
  async function resolveEscalationRow(id, delegateName) {
    // Resolve auto-sets the delegate to Arrived (2026-07-27 — "should notify
    // the user if click resolve will go to arrived, make sure to click once
    // found the delegate") — a confirm so this can't happen by an accidental
    // click, since it's a real status change, not just clearing the alert.
    const msg = lang === "zh"
      ? `解决此紧急情况会将${delegateName ? `"${delegateName}"` : "该代表"}的状态设为"已抵达"。请确认已经找到本人后再点击。`
      : `Resolving this will set ${delegateName ? `"${delegateName}"` : "this delegate"}'s status to Arrived. Only confirm once you've actually found them.`;
    if (!window.confirm(msg)) return;
    setEscalationBusyId(id);
    try {
      await apiPost(`/escalations/${id}/resolve`, {});
      setActiveEscalations((prev) => prev.filter((e) => e.id !== id));
      // Resolving flips the delegate's global status to ARRIVED server-side
      // (see db/escalations.js's resolveEscalation) — without this refresh,
      // `delegates`/`missing` stayed stale until the next 8s poll, so the
      // Alerts modal's Missing section kept showing them even though they'd
      // just been un-escalated (2026-07-27 — "if i click resolve, it should
      // not display in missing section"). Since missingNotEscalated only
      // hides a delegate WHILE they're in activeEscalations, removing them
      // from that list above would otherwise make them reappear in Missing
      // with stale (pre-resolve) data for one poll cycle.
      load();
    } catch { /* leave as-is */ }
    finally { setEscalationBusyId(null); }
  }

  // "Escalate to office" (2026-07-24) — a DELIBERATE, staff-clicked action
  // for when a Missing delegate isn't answering their phone; never automatic.
  // See EscalationBanner.jsx for how office/admin staff actually get alerted
  // once this fires (in-app banner + tab-flash/chime + email/SMS/WhatsApp).
  const [escalatingDelegate, setEscalatingDelegate] = useState(null);
  const [escalateMessage, setEscalateMessage] = useState("");
  const [escalateSaving, setEscalateSaving] = useState(false);
  const [escalateErr, setEscalateErr] = useState(null);
  // Who to alert (2026-07-24, "on frontend I can choose who to alert to") —
  // fetched fresh each time the modal opens (admin accounts with an email on
  // file), all pre-checked by default so not touching anything still alerts
  // everyone, same as before this was pickable.
  const [escalateRecipients, setEscalateRecipients] = useState([]);
  const [escalateSelected, setEscalateSelected] = useState(new Set());
  function openEscalate(d) {
    setEscalatingDelegate(d);
    setEscalateMessage(t("Not answering phone calls"));
    setEscalateErr(null);
    // tripId passed so the backend can float the trip's own lead to the top
    // of the list (2026-07-25) — a smarter default, not a hard restriction;
    // every admin still appears and stays pre-checked.
    const qs = currentTripUuid ? `?tripId=${encodeURIComponent(currentTripUuid)}` : "";
    apiGet(`/escalations/recipients${qs}`).then((r) => {
      const list = r.recipients || [];
      setEscalateRecipients(list);
      setEscalateSelected(new Set(list.map((p) => p.email)));
    }).catch(() => { setEscalateRecipients([]); setEscalateSelected(new Set()); });
  }
  function toggleEscalateRecipient(email) {
    setEscalateSelected((prev) => {
      const next = new Set(prev);
      next.has(email) ? next.delete(email) : next.add(email);
      return next;
    });
  }
  async function submitEscalation() {
    setEscalateSaving(true);
    setEscalateErr(null);
    try {
      const r = await apiPost("/escalations", {
        tripId: currentTripUuid || null,
        delegateId: escalatingDelegate.id,
        message: escalateMessage.trim(),
        recipientEmails: [...escalateSelected],
      });
      // Dedupe guard (2026-07-25) — this delegate already had an open
      // escalation, so nothing new was sent; say so rather than implying a
      // fresh alert just went out.
      if (r.alreadyOpen) {
        setEscalateErr(t("This delegate already has an open escalation — no new alert was sent."));
        setEscalateSaving(false);
        return;
      }
      setEscalatingDelegate(null);
    } catch (e) {
      setEscalateErr(e.message || t("Couldn't send the escalation. Please try again."));
    } finally {
      setEscalateSaving(false);
    }
  }

  // Guards against overlapping polls (e.g. a slow response still in flight
  // when the next 2s tick fires) — same pattern as useSessionGuard's
  // checkingRef, so a late response can't stomp a more recent one.
  const loadingRef = useRef(false);
  const load = useCallback(async () => {
    if (loadingRef.current) return;
    loadingRef.current = true;
    setLoading(true);
    setError(null);
    try {
      const [dash, miss, dels, hist, checkpoints] = await Promise.all([
        apiGet(`/trips/${selectedTripId}/dashboard`),
        apiGet(`/trips/${selectedTripId}/missing`),
        apiGet(`/trips/${selectedTripId}/delegates`),
        // This is the small inline "History tracker" card (360px scroll box on
        // the dashboard, not the full audit log — that's HistoryLogPage.jsx,
        // fetched separately at limit=1000 only when you open /history).
        // Was limit=200 every 8s poll tick; cut to 30 (2026-07-24, Neon
        // egress reduction) since nobody scrolls through 200 rows in a
        // 360px box anyway — "View full log" is one click away for that.
        apiGet(`/activity?limit=30${historyScope === "trip" ? `&tripId=${selectedTripId}` : ""}`),
        apiGet(`/trips/${selectedTripId}/checkpoints`).catch(() => null), // never blocks the rest of the dashboard
      ]);
      setData(dash);
      setMissing(miss.missing || []);
      setDelegates(dels.delegates || []);
      setHistory(hist.activity || []);
      // "Which checkpoint matters right now" — you didn't have any way to see
      // this from the Dashboard before (only the Trip page's day tabs did).
      // Same "current"/"past"/"upcoming" tagging as the scanner pages.
      if (checkpoints) {
        const all = (checkpoints.days || []).flatMap((day) => day.checkpoints);
        const currentIdx = all.findIndex((c) => c.timeState === "current");
        setCurrentCheckpoint(currentIdx >= 0 ? all[currentIdx] : null);
        // Whatever stop immediately follows "current" chronologically — the
        // list is already ordered by day/sort_order/start_time, so the very
        // next entry IS the next event (2026-07-25 — "then show the next
        // trip event" once the current one passes).
        setNextCheckpoint(currentIdx >= 0 ? all[currentIdx + 1] || null : null);
        const today = (checkpoints.days || []).find((day) => day.dayNumber === dash.trip?.dayOf);
        setTodayCheckpoints(today?.checkpoints || []);
      } else {
        setCurrentCheckpoint(null);
        setNextCheckpoint(null);
        setTodayCheckpoints([]);
      }
      // Remember the base trip's uuid the first time we load it, so the trip
      // dropdown can list the OTHER trips without duplicating it.
      if (selectedTripId === TRIP_ID && dash.trip?.uuid_id) {
        setMainTrip({ uuid: dash.trip.uuid_id, name: dash.trip.name });
      }
    } catch (e) {
      setError(e.message || "Could not reach the backend.");
    } finally {
      setLoading(false);
      loadingRef.current = false;
    }
  }, [selectedTripId, historyScope]);

  // Auto-refresh so a change made by another signed-in staff member (a
  // status edit, a new upload, a coach reassignment, etc.) shows up here
  // without anyone having to hit the manual Refresh button. Safe against the
  // create/edit delegate modal's own form state, which is a separate local
  // copy seeded once when the modal opens — a background refresh of the
  // underlying `delegates` list doesn't touch it. Was 2s — slowed to 8s
  // (2026-07-24) after this poll (5 parallel queries, including a 200-row
  // activity dump and the full delegate list) was found to be the single
  // biggest contributor to the Neon project's monthly egress quota with
  // several tabs left open all day; 10s (2026-07-30, was 8s — "put sync to
  // 10 sec") is still fast enough to feel live.
  // 2026-07-29: now also PAUSES entirely while the tab is hidden (and catches
  // up on re-show) — see useVisiblePolling. The 8s slowdown above only reduced
  // the tick rate; this stops the ticks nobody is looking at, which is where
  // most of that egress was actually going. Five calls per tick makes this the
  // single biggest beneficiary in the app.
  useVisiblePolling(load, 10000, [load]);

  // Reactively re-reads ?tripId=/?escalationDelegate= on every URL change
  // (2026-07-25 bugfix) — clicking EscalationBanner's "View" while ALREADY on
  // /dashboard doesn't remount this component, just re-renders it with a new
  // location; the useState initializers above only ever read the query
  // string ONCE (at first mount), so a same-route click silently did
  // nothing until a full page reload force-remounted everything fresh.
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const tripId = params.get("tripId");
    const delegateId = params.get("escalationDelegate");
    const openAlerts = params.get("openAlerts");
    if (tripId) setSelectedTripId(tripId);
    if (delegateId) setPendingEscalationDelegateId(delegateId);
    // ?openAlerts= (2026-07-26 — "the view button link to alert page instead,
    // cause i can only see 1 delegate only") — EscalationBanner's "View" now
    // opens the FULL Emergency list in the Alerts modal instead of deep-
    // linking to just the first escalated delegate's profile, since a busy
    // trip can have several open at once. No roster wait needed (unlike
    // escalationDelegate above), so strip the param immediately here.
    if (openAlerts) {
      setAlertsOpen(true);
      navigate("/dashboard", { replace: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.search]);

  // Consumes ?escalationDelegate= once this trip's roster has actually
  // loaded (2026-07-25, EscalationBanner's "View" jump) — opens that
  // delegate's real profile, persists the trip switch so it sticks after
  // this, and strips the query params so refreshing/revisiting doesn't
  // re-trigger it.
  //
  // Gated on `!loading` (2026-07-25 bugfix): navigating here from a
  // different trip re-renders this SAME component (no unmount), so
  // `delegates` still held the PREVIOUS trip's roster for one render before
  // `load()` refetched — this effect ran immediately against that stale
  // data, never found a match, and gave up (cleared the pending id) before
  // the new trip's real delegates ever arrived. `load()` sets `loading:true`
  // synchronously the instant selectedTripId changes (in the effect just
  // above, which runs first) — so this only ever evaluates once against
  // data that's actually settled for the current trip.
  useEffect(() => {
    if (!pendingEscalationDelegateId || loading || delegates.length === 0) return;
    const found = delegates.find((d) => d.id === pendingEscalationDelegateId);
    if (found) {
      openProfile(found);
      saveSelectedTripId(selectedTripId);
    }
    setPendingEscalationDelegateId(null);
    navigate("/dashboard", { replace: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [delegates, loading, pendingEscalationDelegateId]);

  // Trip list for the switcher (Desmond's all-trips), fetched once. If the
  // persisted selectedTripId (see loadSelectedTripId above) no longer exists
  // — the trip was deleted since it was last picked — fall back to the
  // default Beijing view instead of leaving the dashboard stuck fetching a
  // trip that 404s forever.
  useEffect(() => {
    apiGet("/all-trips").then((r) => {
      const list = r.trips || [];
      setTrips(list);
      if (selectedTripId !== TRIP_ID && !list.some((tr) => tr.id === selectedTripId)) {
        setSelectedTripId(TRIP_ID);
        saveSelectedTripId(TRIP_ID);
      }
    }).catch(() => {});
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // "Staff operations" tab data — only polled while that tab is open (no
  // point hitting the endpoint for admins looking at Delegate/Analytics),
  // and only for accounts that can actually see the tab. Pulled out of the
  // effect (rather than defined inline) so the top "Refresh" button can also
  // call it directly instead of only refreshing dashboard/missing/delegates.
  const loadStaffOps = useCallback(() => {
    if (!perms.manageAccounts) return;
    apiGet("/staff/active-sessions")
      .then((r) => { setStaffOps(r); setStaffOpsError(null); })
      .catch((e) => setStaffOpsError(e.message || "Could not reach the backend."));
  }, [perms.manageAccounts]);

  // Scoped to only fire while an admin actually has this tab open, so it
  // doesn't add load for anyone else. Was 2s, slowed to 8s (2026-07-24, Neon
  // egress reduction) — still shows a login/logout elsewhere within one tick.
  // The old `if (...) return` guard is now expressed as a 0 interval, which
  // useVisiblePolling treats as "don't poll and don't fetch" — same behaviour
  // (no request at all unless an admin is on Staff operations), and it gains
  // the hidden-tab pause on top.
  const staffOpsPollMs = tab === "staffops" && perms.manageAccounts ? 8000 : 0;
  useVisiblePolling(loadStaffOps, staffOpsPollMs, [staffOpsPollMs, loadStaffOps]);

  // Excel export now runs through the ExportModal (opened by the Export
  // button), which lets the user pick status/coach/VIP/columns + an AI filter
  // before downloading — see components/ExportModal.jsx.

  // KPI tile drill-down → jump to the delegate table filtered to that status
  // and scroll it into view. Shared by all 4 primary tiles (Missing/Present/
  // Unassigned/Late) so every one of them behaves the same way.
  function showDelegatesFiltered(status) {
    // The roster table moved under the "Delegate management" tab (2026-07-28),
    // so a KPI drill-down (the tiles live on Overview) has to switch tab AND
    // sub-tab first. The table therefore isn't mounted yet when this runs, so
    // the scroll can't happen here — a single requestAnimationFrame raced the
    // re-render and silently did nothing. Flag it instead and let the effect
    // below scroll once the table actually exists.
    setTab("delegates");
    setDelegateSubTab("list");
    setStatusFilter(status);
    pendingTableScroll.current = true;
  }

  /* ---- CRUD handlers ---------------------------------------------------- */
  function openCreate() {
    setEditingId(null);
    setForm(EMPTY_FORM);
    setFormErr("");
    setEditingPhotoUrl(null);
    setPhotoErr("");
    setShowMoreFields(false);
    setModalOpen(true);
  }

  function openEdit(d) {
    setEditingId(d.id);
    setForm({
      name: d.name || "",
      coachId: d.coachId || "",
      // Legacy rows may still say "PRESENT" (some check-in routes haven't
      // migrated to writing "ARRIVED" yet) — alias it here so the status
      // <select> (which only lists the 5 current values) always has a
      // matching option instead of silently showing blank.
      status: d.status === "PRESENT" ? "ARRIVED" : (d.status || "UNASSIGNED"),
      vip: !!d.vip,
      cancelled: !!d.cancelled,
      // GET returns the raw DB column name (snake_case) for this one, same
      // convention as passport_no/passport_expiry above.
      cancelReason: d.cancel_reason || "",
      lastSeen: d.lastSeen || "",
      lastLocation: d.lastLocation || "",
      company: d.company || "", role: d.role || "", industry: d.industry || "",
      email: d.email || "", phone: d.phone || "", website: d.website || "",
      // GET returns raw DB column names (snake_case) for these three — the
      // rest are already single-word/camelCase-compatible either way.
      passportNumber: d.passport_no || "", nationality: d.nationality || "", passportExpiry: d.passport_expiry || "",
      accessibilityNotes: d.accessibility_notes || "", notes: d.notes || "",
      hotelName: d.hotel_name || "", roomNumber: d.room_number || "",
    });
    setEditingPhotoUrl(d.photoUrl || null);
    setFormErr("");
    setShowMoreFields(false);
    setModalOpen(true);
  }

  // `file` is either the original File (unused now — always goes through the
  // crop modal first) or the cropped JPEG Blob it produces; FormData accepts
  // either. Renamed the param mentally but kept the signature so nothing
  // else calling this needs to change.
  async function handlePhotoChange(file) {
    if (!file || !editingId) return;
    setPhotoErr("");
    setPhotoBusy(true);
    try {
      const fd = new FormData();
      fd.append("photo", file, "photo.jpg");
      const { photoUrl } = await apiPost(`/delegates/${editingId}/photo`, fd, true);
      setEditingPhotoUrl(photoUrl);
      await load();
    } catch (e) {
      setPhotoErr(e.message || "Upload failed.");
    } finally {
      setPhotoBusy(false);
    }
  }

  // Raw file the user just picked, before cropping — opens the crop modal;
  // set to null once cropping is confirmed/cancelled (2026-07-24, "let me
  // resize and choose how my pic gonna be like — common stuff in other
  // websites"). Kept as the File itself (not yet an object URL) so the crop
  // modal can create/revoke its own URL and this component doesn't have to
  // track that lifecycle.
  const [cropFile, setCropFile] = useState(null);

  async function handleCropSave(blob) {
    setCropFile(null);
    await handlePhotoChange(blob);
  }

  async function handleRemovePhoto() {
    if (!editingId) return;
    setPhotoErr("");
    setPhotoBusy(true);
    try {
      await apiDelete(`/delegates/${editingId}/photo`);
      setEditingPhotoUrl(null);
      await load();
    } catch (e) {
      setPhotoErr(e.message || "Remove failed.");
    } finally {
      setPhotoBusy(false);
    }
  }

  async function saveForm() {
    if (!form.name.trim()) return;
    // Phone is required (2026-07-24) — the Reverse headcount's Call button
    // is only useful if every delegate actually has one on file.
    if (!form.phone.trim()) {
      setFormErr("Please enter a phone number.");
      return;
    }
    // A coach is required unless the delegate is explicitly Unassigned —
    // Cancelled always forces UNASSIGNED server-side regardless of whatever
    // status is still selected, so skip this check when cancelled is on.
    if (!form.cancelled && form.status !== "UNASSIGNED" && !form.coachId) {
      setFormErr("Please select a coach, or set status to Unassigned.");
      return;
    }
    // A last known location is required once a delegate is marked Missing —
    // it's the whole point of the field (finding them), so it can't be left
    // blank the way "Last seen" (a free-text note) can.
    if (form.status === "MISSING" && !form.lastLocation.trim()) {
      setFormErr("Please enter a last known location for a missing delegate.");
      return;
    }
    setFormErr("");
    setSaving(true);
    const payload = {
      name: form.name.trim(),
      coachId: form.status === "UNASSIGNED" ? null : form.coachId || null,
      status: form.status,
      vip: form.vip,
      cancelled: form.cancelled,
      cancelReason: form.cancelled ? form.cancelReason.trim() : "",
      // Last seen / location only ever apply while a delegate is missing —
      // cleared on save otherwise so switching status away from Missing
      // doesn't silently carry stale data forward into a later Missing spell.
      lastSeen: form.status === "MISSING" ? form.lastSeen.trim() : "",
      lastLocation: form.status === "MISSING" ? form.lastLocation.trim() : "",
      company: form.company.trim(), role: form.role.trim(), industry: form.industry.trim(),
      email: form.email.trim(), phone: form.phone.trim(), website: form.website.trim(),
      passportNumber: form.passportNumber.trim(), nationality: form.nationality.trim(),
      passportExpiry: form.passportExpiry.trim(),
      accessibilityNotes: form.accessibilityNotes.trim(), notes: form.notes.trim(),
      hotelName: form.hotelName.trim(), roomNumber: form.roomNumber.trim(),
    };
    try {
      if (editingId) {
        await apiPatch(`/delegates/${editingId}`, payload);
      } else {
        await apiPost(`/trips/${selectedTripId}/delegates`, payload);
      }
      setModalOpen(false);
      await load();
    } catch (e) {
      setFormErr(e.message || "Save failed.");
    } finally {
      setSaving(false);
    }
  }

  async function remove(d) {
    const msg = lang === "zh"
      ? `确定删除 ${d.name}？此操作无法撤销。`
      : `Delete ${d.name}? This cannot be undone.`;
    if (!window.confirm(msg)) return;
    try {
      await apiDelete(`/delegates/${d.id}`);
      await load();
    } catch (e) {
      setError(e.message || "Delete failed.");
    }
  }

  // Mark/unmark a delegate as Cancelled (2026-07-24) — for an Assigned
  // delegate who won't make it after all, usually found out day-of. The
  // backend always forces status back to UNASSIGNED and clears coachId when
  // cancelled=true (see normalize() in db/delegates.js), freeing their seat.
  // Cancelling opens `cancelPrompt` (a small reason-textfield modal, see its
  // render further down) rather than a plain window.confirm — "add a
  // textfield that let staff put what happen" — since the whole point is
  // capturing WHY, not just a yes/no. Un-cancelling needs no reason, so it
  // goes straight to the PATCH.
  async function toggleCancelled(d) {
    if (!d.cancelled) { setCancelPrompt({ delegate: d, reason: "" }); return; }
    try {
      const updated = await apiPatch(`/delegates/${d.id}`, { cancelled: false });
      setProfileDelegate((p) => (p && p.id === d.id ? { ...p, ...updated } : p));
      await load();
    } catch (e) {
      setError(e.message || "Could not update this delegate.");
    }
  }

  async function confirmCancel() {
    if (!cancelPrompt) return;
    const { delegate, reason } = cancelPrompt;
    try {
      const updated = await apiPatch(`/delegates/${delegate.id}`, { cancelled: true, cancelReason: reason.trim() });
      setProfileDelegate((p) => (p && p.id === delegate.id ? { ...p, ...updated } : p));
      setCancelPrompt(null);
      await load();
    } catch (e) {
      setError(e.message || "Could not update this delegate.");
    }
  }

  function toggleDelegateSelected(id) {
    setSelectedDelegateIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }

  async function deleteSelectedDelegates() {
    const count = selectedDelegateIds.size;
    if (count === 0) return;
    const msg = lang === "zh"
      ? `确定删除选中的 ${count} 位代表？此操作无法撤销。`
      : `Delete ${count} selected delegate${count === 1 ? "" : "s"}? This cannot be undone.`;
    if (!window.confirm(msg)) return;

    setDeletingSelectedDelegates(true);
    setError(null);
    const ids = [...selectedDelegateIds];
    const results = await Promise.allSettled(ids.map((id) => apiDelete(`/delegates/${id}`)));
    const failed = results.filter((r) => r.status === "rejected");
    if (failed.length > 0) {
      setError(failed[0].reason?.message || "Delete failed.");
    }
    setSelectedDelegateIds(new Set());
    setDeletingSelectedDelegates(false);
    await load();
  }

  async function deleteAll() {
    const msg = lang === "zh"
      ? `确定删除全部 ${delegates.length} 位代表？此操作无法撤销。`
      : `Delete ALL ${delegates.length} delegates? This cannot be undone.`;
    if (!window.confirm(msg)) return;
    try {
      await apiDelete(`/trips/${selectedTripId}/delegates`);
      setSelectedDelegateIds(new Set());
      await load();
    } catch (e) {
      setError(e.message || "Delete all failed.");
    }
  }

  async function removeHistoryEntry(id) {
    try {
      await apiDelete(`/activity/${id}`);
      setHistory((h) => h.filter((a) => a.id !== id));
    } catch (e) {
      setError(e.message || "Delete failed.");
    }
  }

  async function clearHistory() {
    const scopedMsg = lang === "zh"
      ? `确定清空当前行程的全部 ${history.length} 条历史记录？此操作无法撤销。`
      : `Clear ALL ${history.length} history entries for this trip? This cannot be undone.`;
    const allMsg = lang === "zh"
      ? `确定清空全部行程共 ${history.length} 条历史记录？此操作无法撤销。`
      : `Clear ALL ${history.length} history entries across every trip? This cannot be undone.`;
    if (!window.confirm(historyScope === "trip" ? scopedMsg : allMsg)) return;
    try {
      await apiDelete(`/activity${historyScope === "trip" ? `?tripId=${selectedTripId}` : ""}`);
      setHistory([]);
    } catch (e) {
      setError(e.message || "Delete all failed.");
    }
  }

  const trip = data?.trip;
  const k = data?.kpis;
  const coaches = data?.coaches || [];
  const coachName = (id) => {
    const c = coaches.find((x) => x.id === id);
    return c ? coachDisplayName(c) : t("Unassigned");
  };

  // Legacy rows may still hold "PRESENT" (routes that haven't migrated to
  // writing "ARRIVED" yet) — alias for filtering/sorting so those rows show
  // up under "Arrived" instead of silently vanishing from that filter.
  const effectiveStatus = (d) => (d.status === "PRESENT" ? "ARRIVED" : d.status);

  // Feeds the new Alerts card (2026-07-24) — "if it's missing, it will
  // mention, late will be brief and show who's late... those who are
  // cancel status also display". `missing` (state) is already the
  // trip-scoped Missing list with lastSeen/lastLocation/phone; Late and
  // Cancelled are derived here from the full delegates list since there's
  // no separate endpoint for either.
  const lateDelegates = useMemo(() => delegates.filter((d) => effectiveStatus(d) === "LATE"), [delegates]);
  const cancelledDelegates = useMemo(() => delegates.filter((d) => d.cancelled), [delegates]);
  // Alerts modal (2026-07-26 — "if i escalated, i think the missing can hide
  // it, cause showing double stuff can be very confusing") — a delegate
  // already showing in the Emergency section shouldn't ALSO show in Missing
  // right below it; the Emergency card already covers them (with
  // Acknowledge/Resolve), so Missing here only needs whoever ISN'T already
  // being handled as an emergency.
  const escalatedDelegateIds = useMemo(() => new Set(activeEscalations.map((e) => e.delegateId).filter(Boolean)), [activeEscalations]);
  const missingNotEscalated = useMemo(() => missing.filter((m) => !escalatedDelegateIds.has(m.id)), [missing, escalatedDelegateIds]);

  // The "All delegates" table, after the search box, status filter and sort.
  const visibleDelegates = useMemo(() => {
    const query = delegateQuery.trim().toLowerCase();
    let list = delegates.filter((d) => {
      // "CANCELLED" isn't a real status value (see backend/db/schema.js's
      // comment) — it's a boolean layered on top of UNASSIGNED, so it's
      // filtered separately here rather than through effectiveStatus().
      if (statusFilter === "CANCELLED") { if (!d.cancelled) return false; }
      else if (statusFilter !== "ALL" && effectiveStatus(d) !== statusFilter) return false;
      // Coach filter is real-coaches-only now (2026-07-27 — "currently both
      // filter have unassigned, combine both in one filter") — Status
      // already has its own "Unassigned" option, and status===UNASSIGNED is
      // always exactly equivalent to coachId being empty (the backend
      // requires a coach for every OTHER status), so the two dropdowns were
      // offering the same filter twice. Picking Status: Unassigned still
      // shows exactly the same delegates a coach-side "Unassigned" option
      // used to.
      if (coachFilter !== "ALL" && d.coachId !== coachFilter) return false;
      if (query) {
        const hay = `${d.name || ""} ${d.company || ""}`.toLowerCase();
        if (!hay.includes(query)) return false;
      }
      return true;
    });
    const byName = (a, b) => (a.name || "").localeCompare(b.name || "");
    list = [...list].sort((a, b) => {
      if (sortMode === "recent") return new Date(b.createdAt || 0) - new Date(a.createdAt || 0);
      if (sortMode === "status") return (a.status || "").localeCompare(b.status || "") || byName(a, b);
      if (sortMode === "coach") return coachName(a.coachId).localeCompare(coachName(b.coachId)) || byName(a, b);
      return byName(a, b); // name
    });
    return list;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [delegates, delegateQuery, statusFilter, coachFilter, sortMode, coaches]);

  /* ---- Trip switcher derived state -------------------------------------- */
  // The uuid of the trip currently shown (for the "open in Trips board" links).
  const currentTripUuid = selectedTripId === TRIP_ID ? (trip?.uuid_id || mainTrip?.uuid) : selectedTripId;

  // Fetches the Alerts modal's "Emergency" list — declared here (not up by
  // activeEscalations' own useState above) because it depends on
  // currentTripUuid, which isn't defined until this point in the component.
  // Scoped to the currently viewed trip (2026-07-25 bugfix) — this used to
  // fetch EVERY trip's active escalations unfiltered, so a delegate escalated
  // on a completely different trip showed up here too, and clicking them
  // opened an incomplete synthetic profile (no status badge) since they were
  // never in this trip's own `delegates` array.
  useEffect(() => {
    if (!alertsOpen) return;
    setEscalationQuery("");
    setShowAllEscalations(false);
    let alive = true;
    const qs = currentTripUuid ? `?tripId=${encodeURIComponent(currentTripUuid)}` : "";
    apiGet(`/escalations/active${qs}`).then((r) => { if (alive) setActiveEscalations(r.escalations || []); }).catch(() => {});
    return () => { alive = false; };
  }, [alertsOpen, currentTripUuid]);

  // Dropdown: the base trip (as "t-1", unfiltered) + every other trip by uuid
  // — restricted to trips actually "In progress" (2026-07-24): a
  // Planning/Completed trip has nothing live to switch to and view here,
  // same restriction MobileHomePage.jsx already applies to its own picker.
  // The currently-selected trip is always kept in the list even if its own
  // status isn't "In progress", so switching away from it never disappears
  // the option you're already on mid-selection.
  const tripOptions = useMemo(() => {
    const opts = [];
    if (selectedTripId === TRIP_ID || trip?.status === "In progress") {
      opts.push({ id: TRIP_ID, name: mainTrip?.name || trip?.name || "Beijing study mission" });
    }
    for (const tr of trips) {
      if (mainTrip && tr.id === mainTrip.uuid) continue; // skip the base (it's the t-1 option)
      if (tr.status !== "In progress" && tr.id !== selectedTripId) continue;
      opts.push({ id: tr.id, name: tr.name });
    }
    /* Second dedup pass, because the uuid check above isn't always able to fire
     * (2026-07-29 bugfix — the switcher listed "Beijing study mission" TWICE).
     * `mainTrip` is only ever set while `selectedTripId === TRIP_ID` (see
     * load()), so when the persisted selection is the base trip's UUID rather
     * than the "t-1" alias, `mainTrip` is null, the skip never runs, and the
     * same trip appears as both the alias option AND its own uuid row.
     *
     * "t-1" is an ALIAS for a real trip row, so a same-named pair here is the
     * same trip twice, not two trips. Scoped deliberately to pairs INVOLVING
     * the alias: two genuinely distinct trips are allowed to share a name, and
     * a blanket name-dedup would silently hide one of them. The kept entry is
     * whichever matches the current selection, so the <select>'s value always
     * corresponds to a real option (otherwise it renders blank). */
    const aliasIdx = opts.findIndex((o) => o.id === TRIP_ID);
    if (aliasIdx >= 0) {
      const aliasName = (opts[aliasIdx].name || "").trim().toLowerCase();
      const twinIdx = opts.findIndex(
        (o, i) => i !== aliasIdx && (o.name || "").trim().toLowerCase() === aliasName
      );
      if (twinIdx >= 0) {
        const dropIdx = opts[twinIdx].id === selectedTripId ? aliasIdx : twinIdx;
        opts.splice(dropIdx, 1);
      }
    }
    return opts;
  }, [trips, mainTrip, trip, selectedTripId]);

  const COACH_TOP_N = 4;
  const openCoachBoard = () => { if (currentTripUuid) navigate(`/trips?tripId=${currentTripUuid}`); };

  const pageCount = Math.max(1, Math.ceil(visibleDelegates.length / delegatePageSize));
  // Filters/search/sort changing can leave delegatePage pointing past the
  // new (shorter) result set — clamp it back into range rather than showing
  // an empty page.
  const clampedPage = Math.min(delegatePage, pageCount - 1);
  useEffect(() => { if (clampedPage !== delegatePage) setDelegatePage(clampedPage); }, [clampedPage, delegatePage]);
  // Jump back to page 1 whenever the result set changes shape, rather than
  // silently staying on whatever page number happened to be selected before.
  useEffect(() => { setDelegatePage(0); }, [delegateQuery, statusFilter, coachFilter, sortMode, delegatePageSize]);

  const clearDelegateFilters = () => { setDelegateQuery(""); setStatusFilter("ALL"); setCoachFilter("ALL"); };
  const delegateFiltersActive = delegateQuery.trim() !== "" || statusFilter !== "ALL" || coachFilter !== "ALL";

  // The delegate rows actually rendered in the table right now (respects
  // pagination) — the "select all" checkbox scopes to exactly this set,
  // matching the same convention as the Trips/Onboarding pages.
  const rowsShown = visibleDelegates.slice(clampedPage * delegatePageSize, (clampedPage + 1) * delegatePageSize);
  // Auto-hide Created-by when it's empty across every row on THIS page —
  // almost always "—" once a trip has real volume. Last-seen column removed
  // entirely (2026-07-27 — "i think no need last seen section, look a lot
  // of stuff") — the same info is still visible on the delegate's own
  // profile panel, just not duplicated as a table column.
  const showCreatedByCol = rowsShown.some((d) => d.createdBy);

  // Staff operations' Active sessions list — search + role filter, applied
  // on top of whatever the backend already sorted (most-recently-active
  // first, see accounts.js's listActiveAccounts).
  const visibleActiveStaff = useMemo(() => {
    if (!staffOps) return [];
    const q = staffOpsSearch.trim().toLowerCase();
    return staffOps.active.filter((acc) => {
      if (staffOpsRoleFilter !== "ALL" && (acc.role === "admin" ? "admin" : "staff") !== staffOpsRoleFilter) return false;
      if (q) {
        const hay = `${acc.username || ""} ${acc.name || ""}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });
  }, [staffOps, staffOpsSearch, staffOpsRoleFilter]);
  const staffOpsFiltersActive = staffOpsSearch.trim() !== "" || staffOpsRoleFilter !== "ALL";

  return (
    <div className="page">
      {/* ---- Header ------------------------------------------------------- */}
      <div className="row between" style={{ alignItems: "flex-start", flexWrap: "wrap", gap: 16 }}>
        {/* Header restyled 2026-07-29 ("can you improve this uiux, it look
            outdate"). What was dated about it wasn't the styling so much as the
            information architecture: FOUR stacked rows — eyebrow, "Dashboard",
            a run-on metadata sentence, a "Now:" chip, then a whole separate
            "Viewing trip" row below — pushed the actual content ~200px down the
            page, and the biggest text on screen said "Dashboard", which is the
            one thing you already know from the nav.
            Now: the TRIP is the title (that's the thing that changes and that
            you care about), its facts are discrete chips instead of a
            "·"-joined sentence, and the trip switcher is folded into the title
            row as a compact control rather than owning a row of its own. */}
        {/* flex "1 1 auto" -> "1 1 0%" (2026-07-30 — "currently the beijing
            study mission show this, it should look like how the manila
            innovation summit trip [looks]"). Beijing has a live itinerary stop
            (the "Now: Hotel breakfast · 08:00" chip); Manila doesn't. With
            "auto" as the flex-basis, a flex item's PREFERRED width is its
            unwrapped max-content width — even though the chips row wraps
            internally, the browser still measured how wide it'd be if nothing
            wrapped, and that measurement (with the extra "Now:/Next:" chip) was
            wide enough that the whole row ran out of space, so the Live/
            Refresh/Bell/Export block got pushed onto a SECOND line entirely.
            Manila's shorter, chip-free row never triggered that, so the two
            trips rendered with genuinely different layouts, not just different
            content. Basis 0% makes this item's width purely proportional
            (flex-grow/shrink), ignoring its own content's natural width — so it
            actually uses only the room it's given, its internal chip row wraps
            within THAT space instead of demanding more, and the actions block
            (flex-shrink:0 below) stays pinned on the same line as the title
            for every trip, regardless of how many chips it's showing. */}
        <div style={{ minWidth: 0, flex: "1 1 0%" }}>
          <div className="page-eyebrow">{t("Dashboard")}</div>
          {/* The trip name and the switcher are now ONE control (2026-07-29 —
              "can you kinda merge the drop with the text cause got 2 same
              text"): the heading previously printed the trip name and the
              dropdown beside it printed the SAME name again. The <select> is
              styled as the heading itself and sits inside the <h1>, so the
              title you read is the thing you click to change — one piece of
              text, no duplication. A single-trip account still gets plain
              heading text, since a dropdown with one option is just noise. */}
          <div className="row" style={{ gap: 10, flexWrap: "wrap", alignItems: "center" }}>
            {/* marginTop 0 -> 7 (2026-07-29 — "add more space between dashboard
                and beijing study mission text"). `.page-title`'s own 4px top
                margin was overridden to 0 when the switcher moved in here, so
                the uppercase DASHBOARD eyebrow ended up almost touching the
                28px title. Bottom stays 0 — the chips below own that gap. */}
            <h1 className="page-title" style={{ margin: "7px 0 0", minWidth: 0, display: "flex", alignItems: "center" }}>
              {tripOptions.length > 1 ? (
                /* The trip name is rendered as plain TEXT with the chevron
                   right after it, and the <select> is laid invisibly OVER the
                   pair (2026-07-29 — "put the dropdown icon next to the text
                   instead, so whenever i have long name trip it should stick
                   beside it").
                   WHY not just style the <select> itself: a <select> sizes to
                   its WIDEST option, never the selected one — so with "Manila
                   Innovation Summit" in the list, the control stayed that wide
                   while displaying the shorter "Beijing study mission", and the
                   chevron sat stranded a few characters to the right. Sizing
                   from real text fixes it for any name length, short or long.
                   The overlaid select keeps the NATIVE dropdown (and its
                   keyboard handling) and covers the text + chevron, so the
                   whole title is the click target. */
                <TripSwitcher
                  trip={trip}
                  tripOptions={tripOptions}
                  selectedTripId={selectedTripId}
                  t={t}
                  onPick={(id) => {
                    setSelectedTripId(id); saveSelectedTripId(id);
                    setShowAllDelegates(false); setShowAllCoaches(false); setSelectedDelegateIds(new Set());
                  }}
                />
              ) : (
                trip ? trip.name : t("Dashboard")
              )}
            </h1>
          </div>

          {trip ? (
            /* marginTop 9 -> 14 (2026-07-29 — "add some gap between the day and
               the title") — the chips sat tight under a 30px heading, reading
               as part of it rather than as a separate band of facts. */
            <div className="row" style={{ gap: 7, flexWrap: "wrap", marginTop: 14, alignItems: "center" }}>
              <span style={S.metaChip}>
                <CalendarDays size={12} style={{ flexShrink: 0, color: "var(--ink-3)" }} />
                {lang === "zh" ? `第 ${trip.dayOf}/${trip.totalDays} 天` : `${t("Day")} ${trip.dayOf} / ${trip.totalDays}`}
              </span>
              {/* Shows the REAL clock, ticking (2026-07-29 — "what the time
                  icon for? if it showing actual time, pls fix it accordingly").
                  It previously rendered `trip.localTime`, which is a HARDCODED
                  SEED STRING ("14:26" in db/constants.js) written once at seed
                  time and never updated by anything — so this chip had been
                  frozen at 14:26 since the database was created, and was
                  correct for exactly one minute a day by coincidence.
                  This is the viewer's own device clock. It is NOT necessarily
                  the destination's local time: `trips` has no timezone column,
                  so there is nothing to convert against. Labelled plainly as
                  the time instead of claiming "local", because overstating it
                  is how the old value misled in the first place. Proper
                  trip-local time needs a timezone on the trip — see AI Log. */}
              <span style={S.metaChip} title={t("Your device's current time — the trip has no timezone set")}>
                <Clock size={12} style={{ flexShrink: 0, color: "var(--ink-3)" }} />
                {nowClock}
              </span>
              <span style={S.metaChip}>
                <Users size={12} style={{ flexShrink: 0, color: "var(--ink-3)" }} />
                {k?.total ?? "—"} <span className="muted">{t("delegates")}</span>
              </span>
              {/* Which checkpoint matters right now — same "current" tag the
                  scanner pages auto-focus on, so the Dashboard doesn't leave
                  you guessing which event is live without switching to /trips.
                  Clickable (2026-07-30 — "the now:...8:00am is like telling
                  me it's happening now which is not"): "current" means "the
                  active leg of today's schedule", not literally this second —
                  a delegate can be marked at the 8am breakfast checkpoint at
                  1am if nothing since has superseded it. Rather than word that
                  distinction into an already-tight chip, tapping it opens
                  today's full schedule so the actual timing is never in
                  question. The trailing muted "Next:" line this used to pair
                  with is gone — the popover already covers that, and better. */}
              {currentCheckpoint && (
                <span style={{ position: "relative" }}>
                  <button
                    type="button"
                    onClick={() => setShowTodayItinerary((v) => !v)}
                    style={{
                      ...S.metaChip, borderColor: "var(--st-assigned)", color: "var(--st-assigned)",
                      background: "var(--st-assigned-bg)", fontWeight: 600, maxWidth: "min(100%, 420px)",
                      cursor: "pointer", fontFamily: "inherit",
                    }}
                    title={t("View today's full itinerary")}
                    aria-expanded={showTodayItinerary}
                  >
                    <span style={{ width: 6, height: 6, borderRadius: 999, background: "currentColor", flexShrink: 0 }} />
                    <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                      {t("Now")}: {currentCheckpoint.label}{currentCheckpoint.scheduledTime ? ` · ${fmt12h(currentCheckpoint.scheduledTime)}` : ""}
                    </span>
                    <ChevronDown size={13} style={{ flexShrink: 0, transform: showTodayItinerary ? "rotate(180deg)" : "none", transition: "transform .15s" }} />
                  </button>
                  {showTodayItinerary && (
                    <>
                      <div style={{ position: "fixed", inset: 0, zIndex: 39 }} onClick={() => setShowTodayItinerary(false)} />
                      <div
                        className="card"
                        style={{
                          position: "absolute", top: "calc(100% + 6px)", left: 0, zIndex: 40,
                          width: 280, maxHeight: 320, overflowY: "auto", padding: 8,
                        }}
                      >
                        <div className="muted" style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.05em", textTransform: "uppercase", padding: "4px 8px" }}>
                          {t("Today's itinerary")} · {t("Day")} {trip.dayOf}
                        </div>
                        {todayCheckpoints.length === 0 ? (
                          <div className="muted" style={{ fontSize: 12.5, padding: "6px 8px" }}>{t("Nothing scheduled today.")}</div>
                        ) : (
                          todayCheckpoints.map((c) => (
                            <div
                              key={c.id}
                              className="row"
                              style={{
                                gap: 8, padding: "7px 8px", borderRadius: "var(--r-sm)",
                                background: c.timeState === "current" ? "var(--st-assigned-bg)" : "transparent",
                              }}
                            >
                              <span style={{
                                width: 6, height: 6, borderRadius: 999, flexShrink: 0,
                                background: c.timeState === "current" ? "var(--st-assigned)" : c.timeState === "past" ? "var(--ink-3)" : "var(--line)",
                              }} />
                              <span className="mono" style={{ fontSize: 12, fontWeight: 700, color: "var(--ink-3)", flexShrink: 0, minWidth: 60 }}>
                                {fmt12h(c.scheduledTime)}
                              </span>
                              <span style={{ fontSize: 13, fontWeight: c.timeState === "current" ? 700 : 400 }}>{c.label}</span>
                            </div>
                          ))
                        )}
                      </div>
                    </>
                  )}
                </span>
              )}
            </div>
          ) : (
            <p className="page-sub" style={{ marginTop: 6 }}>{t("Live present / missing / unassigned visibility.")}</p>
          )}
        </div>

        {/* flexShrink:0 (2026-07-30, paired with the flex-basis fix above) —
            pins this block to a fixed width so it can never be squeezed or
            wrapped by the title block's own content; it either sits inline on
            the title's row (the normal case at any trip) or, only at a
            genuinely too-narrow viewport, wraps as a whole unit — never split
            mid-cluster. */}
        <div className="row" style={{ gap: 10, flexWrap: "wrap", flexShrink: 0 }}>
          {data && <LiveSyncBadge seconds={REFRESH_SECONDS} t={t} dotStyle={S.dot} />}
          <button
            className="btn btn-ghost"
            onClick={() => { load(); if (tab === "staffops") loadStaffOps(); }}
            title={t("Refresh")}
          >
            <RefreshCw size={16} className={loading ? "spin" : ""} /> {t("Refresh")}
          </button>
          {data && (missing.length > 0 || lateDelegates.length > 0 || cancelledDelegates.length > 0) && (
            <button
              className="btn btn-ghost"
              onClick={() => setAlertsOpen(true)}
              title={t("Alerts")}
              aria-label={t("Alerts")}
              style={{ position: "relative" }}
            >
              <Bell size={16} />
              <span
                style={{
                  position: "absolute", top: -4, right: -4, minWidth: 16, height: 16, padding: "0 3px",
                  borderRadius: 999, background: "var(--st-missing)", color: "#fff",
                  fontSize: 10, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center",
                }}
              >
                {missing.length + lateDelegates.length + cancelledDelegates.length}
              </span>
            </button>
          )}
          <button className="btn btn-primary" onClick={() => setExportOpen(true)} disabled={!data} style={{ display: perms.exportData ? undefined : "none" }}>
            <Download size={16} /> {t("Export")}
          </button>
        </div>
      </div>

      {/* The standalone "Viewing trip" row that used to sit here is gone
          (2026-07-29) — the switcher now lives beside the trip title above,
          which is where the trip name it changes actually appears. Its old
          comment claimed a separate row kept its position stable; in practice
          it just added a whole row of chrome above the tabs. */}

      {/* ---- Tabs ----------------------------------------------------------- */}
      <div className="row" style={{ gap: 8, marginTop: 20 }}>
        {perms.viewDashboard && (
          <button
            className="btn"
            onClick={() => setTab("overview")}
            style={{
              background: tab === "overview" ? "var(--scc-red-tint)" : "transparent",
              color: tab === "overview" ? "var(--scc-red)" : "var(--ink-2)",
              border: `1px solid ${tab === "overview" ? "var(--scc-red-tint-2)" : "var(--line)"}`,
            }}
          >
            <LayoutGrid size={16} /> {t("Overview")}
          </button>
        )}
        {(perms.viewDelegates || perms.viewHistory || isAdmin) && (
          <button
            className="btn"
            onClick={() => setTab("delegates")}
            style={{
              background: tab === "delegates" ? "var(--scc-red-tint)" : "transparent",
              color: tab === "delegates" ? "var(--scc-red)" : "var(--ink-2)",
              border: `1px solid ${tab === "delegates" ? "var(--scc-red-tint-2)" : "var(--line)"}`,
            }}
          >
            <Users size={16} /> {t("Delegate management")}
          </button>
        )}
        {isAdmin && (
          <button
            className="btn"
            onClick={() => setTab("analytics")}
            style={{
              background: tab === "analytics" ? "var(--scc-red-tint)" : "transparent",
              color: tab === "analytics" ? "var(--scc-red)" : "var(--ink-2)",
              border: `1px solid ${tab === "analytics" ? "var(--scc-red-tint-2)" : "var(--line)"}`,
            }}
          >
            <BarChart3 size={16} /> {t("Analytics")}
          </button>
        )}
        {isAdmin && (
          <button
            className="btn"
            onClick={() => setTab("staffops")}
            style={{
              background: tab === "staffops" ? "var(--scc-red-tint)" : "transparent",
              color: tab === "staffops" ? "var(--scc-red)" : "var(--ink-2)",
              border: `1px solid ${tab === "staffops" ? "var(--scc-red-tint-2)" : "var(--line)"}`,
            }}
          >
            <Radio size={16} /> {t("Staff operations")}
          </button>
        )}
      </div>

      {/* ---- Error banner (shared by both tabs) --------------------------- */}
      {error && (
        <div
          className="card"
          style={{ marginTop: 20, padding: 16, borderColor: "var(--st-missing)", background: "var(--st-missing-bg)" }}
        >
          <div className="row" style={{ gap: 10, color: "var(--st-missing)", fontWeight: 600 }}>
            <AlertTriangle size={18} /> {t("Couldn't reach the backend")}
          </div>
          <p className="muted" style={{ fontSize: 13, marginTop: 6 }}>
            {t(error)} — {t("make sure it’s running (")}<code>cd backend &amp;&amp; npm run dev</code>{t("), then hit Refresh.")}
          </p>
        </div>
      )}

      {loading && !data && (
        <div className="muted" style={{ marginTop: 24 }}>{t("Loading…")}</div>
      )}

      {tab === "analytics" && isAdmin && (
        <div style={{ marginTop: 20 }}>
          <AnalyticsPanel data={data} missing={missing} delegates={delegates} tripId={selectedTripId} />
        </div>
      )}

      {exportOpen && <ExportModal tripId={selectedTripId} onClose={() => setExportOpen(false)} />}

      {headcountOpen && (
        <div style={S.overlay}
          onMouseDown={(e) => { downOnBackdrop.current = e.target === e.currentTarget; }}
          onClick={(e) => { if (downOnBackdrop.current && e.target === e.currentTarget) setHeadcountOpen(false); }}>
          <div className="card" style={{ ...S.modal, width: "min(1000px, 100%)" }} onClick={(e) => e.stopPropagation()}>
            <div className="row between" style={{ marginBottom: 4 }}>
              <h2 style={{ fontSize: 17 }}>{t("Reverse headcount")}</h2>
              <button onClick={() => setHeadcountOpen(false)} style={S.iconBtn} aria-label={t("Close")}>
                <X size={18} />
              </button>
            </div>
            <p className="page-sub" style={{ margin: 0 }}>
              {t("Who's still missing, per coach — the same view staff see on the Check-in screen.")}
            </p>

            {/* Search / filter / sort — a long "still missing" list per coach
                gets hard to scan once the roster is large (2026-07-24). */}
            <div className="row" style={{ gap: 10, marginTop: 14, flexWrap: "wrap", alignItems: "center" }}>
              <div style={{ position: "relative", flex: 1, minWidth: 200 }}>
                <Search size={15} style={{ position: "absolute", left: 10, top: 10, color: "var(--ink-3)" }} />
                <input className="input" placeholder={t("Search name…")} value={hcSearch}
                  onChange={(e) => setHcSearch(e.target.value)} style={{ paddingLeft: 32 }} />
              </div>
              <select className="select" style={{ width: 150 }} value={hcFilter} onChange={(e) => setHcFilter(e.target.value)}>
                <option value="all">{t("All statuses")}</option>
                <option value="missing">{t("Missing only")}</option>
                <option value="late">{t("Late only")}</option>
                <option value="vip">{t("VIP only")}</option>
              </select>
              <select className="select" style={{ width: 150 }} value={hcSort} onChange={(e) => setHcSort(e.target.value)}>
                <option value="name">{t("Sort: Name")}</option>
                <option value="status">{t("Sort: Status")}</option>
              </select>
            </div>

          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))", gap: 16, marginTop: 16 }}>
            {coaches.map((c) => {
              // Everyone on this coach NOT yet boarded — matches the Coach
              // status card's own "N to board" figure (coach.total -
              // coach.boarded, below). Used to filter on MISSING/LATE only
              // (2026-07-30 — "it show green arrived which should not show
              // until every delegate is arrived... it should still show the
              // assigned delegate not there yet"): a coach with 5 people
              // simply ASSIGNED but not yet scanned — not late enough to be
              // flagged LATE, not past checkpoint-reset to be flagged
              // MISSING — showed 0 "missing" and a green "Arrived" badge,
              // directly contradicting the "5 to board" already visible one
              // card over. `effectiveStatus(d)` (not raw `d.status`) is the
              // correct "still needs to board" check — it already naturally
              // includes ASSIGNED, LATE, and MISSING together.
              // 2026-07-30 ("why is it arrived delegate are there?") — this
              // used to check raw `d.status !== "ARRIVED"` on the (incorrect)
              // assumption that PRESENT gets normalised to ARRIVED before it
              // ever reaches this list; it doesn't (that normalisation only
              // happens inside openEdit()'s form initializer, for a single
              // delegate at a time) — so anyone whose real stored status was
              // the legacy "PRESENT" value stayed stuck in "not boarded"
              // forever despite having genuinely checked in. effectiveStatus()
              // is the one helper in this file that actually does that
              // PRESENT->ARRIVED aliasing, and mobile's own status checks
              // already rely on it — this just brings Reverse headcount in
              // line with the same rule instead of re-deriving its own.
              // Search/filter/sort applied on top (all client-side — the list
              // per coach is small enough not to need a server round-trip).
              const search = hcSearch.trim().toLowerCase();
              const coachMissing = delegates
                .filter((d) => d.coachId === c.id && effectiveStatus(d) !== "ARRIVED")
                .filter((d) => {
                  if (hcFilter === "missing") return d.status === "MISSING";
                  if (hcFilter === "late") return d.status === "LATE";
                  if (hcFilter === "vip") return !!d.vip;
                  return true;
                })
                .filter((d) => !search || d.name.toLowerCase().includes(search))
                .sort((a, b) => {
                  if (hcSort === "status") {
                    if (a.status !== b.status) return a.status === "MISSING" ? -1 : 1; // Missing before Late
                    return a.name.localeCompare(b.name);
                  }
                  return a.name.localeCompare(b.name);
                });
              const segs = coachBarSegments(c, { includeBoarded: false });
              // Collapsed by default once there are more than a handful of
              // coaches (2026-07-24) — with e.g. 20 coaches, every list open
              // at once is exactly the reported "messy" problem. A coach
              // with nothing missing has nothing to expand anyway.
              const collapsible = coaches.length > 4 && coachMissing.length > 0;
              const expanded = !collapsible || expandedCoaches.has(c.id);
              return (
                <div key={c.id} className="card" style={{ padding: 20 }}>
                  <div className="row between" style={{ alignItems: "flex-start", cursor: collapsible ? "pointer" : undefined }}
                    onClick={collapsible ? () => toggleCoachExpanded(c.id) : undefined}
                    role={collapsible ? "button" : undefined}>
                    <div className="row" style={{ gap: 8, alignItems: "center" }}>
                      {collapsible && <ChevronDown size={15} className="muted" style={{ transform: expanded ? "none" : "rotate(-90deg)", transition: "transform 0.15s", flexShrink: 0 }} />}
                      <div>
                        <div style={{ fontWeight: 600, fontSize: 15 }}>{coachDisplayName(c)}</div>
                        <div className="muted" style={{ fontSize: 12 }}>{c.boarded}/{c.capacity} {t("boarded")}</div>
                      </div>
                    </div>
                    {c.total === 0 ? (
                      // "Arrived" means the whole bar is green — every
                      // delegate assigned to this coach has boarded. A coach
                      // with NO delegates at all yet isn't "arrived", it's
                      // just empty — those are two different states (bug
                      // report: 0/40 with nobody assigned was showing green
                      // "Arrived" as if the coach were fully checked in).
                      <span className="badge badge-neutral">{t("No delegates yet")}</span>
                    ) : coachMissing.length === 0 ? (
                      <span className="badge badge-present">{t("Arrived")}</span>
                    ) : (
                      // Severity-toned rather than always red (2026-07-30 —
                      // "i like the mobile blue color, do the same for
                      // desktop"): a coach that's simply not fully SCANNED
                      // yet (nobody late or missing, just not-yet-boarded)
                      // reads as blue/"assigned", the same tone the mobile
                      // Coach status card already uses for that case —
                      // red is reserved for when someone's genuinely MISSING.
                      <span className={`badge badge-${(c.missing || 0) > 0 ? "missing" : (c.late || 0) > 0 ? "late" : "assigned"}`}>
                        {coachMissing.length} {t("not boarded")}
                      </span>
                    )}
                  </div>
                  <div className="roster-bar" style={{ height: 8 }}>
                    {segs.map((s, i) => <span key={i} style={{ width: `${s.pct}%`, background: `var(--st-${s.tone})` }} />)}
                  </div>

                  {c.total === 0 ? (
                    <div className="muted" style={{ fontSize: 13, marginTop: 14 }}>{t("No delegates assigned to this coach yet.")}</div>
                  ) : coachMissing.length === 0 ? (
                    <div className="muted" style={{ fontSize: 13, marginTop: 14 }}>{t("Everyone on this coach is accounted for.")}</div>
                  ) : !expanded ? (
                    <button className="btn btn-ghost" style={{ marginTop: 14, width: "100%", justifyContent: "center" }} onClick={() => toggleCoachExpanded(c.id)}>
                      {t("Show")} {coachMissing.length} {t("missing/late")}
                    </button>
                  ) : (
                    // Fixed-height scroll area (2026-07-24) — with a large
                    // roster, one coach's "still missing" list could run to
                    // 15+ names, ballooning that card far taller than its
                    // neighbours and making the whole grid look messy. A
                    // capped, independently-scrollable list keeps every
                    // coach card the same height regardless of count.
                    <div style={{ display: "flex", flexDirection: "column", gap: 10, marginTop: 14, maxHeight: 340, overflowY: "auto", paddingRight: 4 }}>
                      {coachMissing.map((m) => (
                        <div
                          key={m.id}
                          className="row between"
                          style={{ gap: 10, cursor: "pointer" }}
                          onClick={() => openProfile(m)}
                          role="button"
                          tabIndex={0}
                          aria-label={`${t("View profile")} — ${m.name}`}
                          onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") openProfile(m); }}
                        >
                          <div className="row" style={{ gap: 10, minWidth: 0 }}>
                            <DelegateAvatar delegate={m} style={{ flexShrink: 0 }} />
                            <div style={{ minWidth: 0 }}>
                              <div className="row" style={{ gap: 6 }}>
                                <span style={{ fontWeight: 500, fontSize: 13.5, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{m.name}</span>
                                {m.vip && <Crown size={13} color="var(--st-review)" style={{ flexShrink: 0 }} />}
                              </div>
                              {/* Everyone here is missing or late, so the subtitle is their
                                  last known location rather than a generic status label. */}
                              <div className="muted" style={{ fontSize: 12 }}>{m.lastLocation || t("Last known location")}</div>
                            </div>
                          </div>
                          <div className="row" style={{ gap: 4, flexShrink: 0 }}>
                            {m.phone && (
                              <a
                                href={`tel:${m.phone}`}
                                onClick={(e) => e.stopPropagation()}
                                aria-label={`${t("Call")} — ${m.name}`}
                                title={`${t("Call")} ${m.phone}`}
                                style={{ ...S.iconBtn, color: "var(--st-present)", textDecoration: "none" }}
                              >
                                <Phone size={16} />
                              </a>
                            )}
                            {m.lastLocation && (
                              <button
                                onClick={(e) => { e.stopPropagation(); setMapDelegate(m); }}
                                aria-label={`${t("View location")} — ${m.name}`}
                                title={t("View location")}
                                style={{ ...S.iconBtn, color: "var(--st-missing)", flexShrink: 0 }}
                              >
                                <MapPin size={16} />
                              </button>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
            {coaches.length === 0 && (
              <div className="muted" style={{ fontSize: 14 }}>{t("No coaches for this trip yet.")}</div>
            )}
          </div>
          </div>
        </div>
      )}

      {/* Room Management and Checkpoint history are now SUB-tabs of "Delegate
          management" (2026-07-28) — see the sub-tab bar further down. */}

      {tab === "staffops" && perms.manageAccounts && (
        <div style={{ marginTop: 20 }}>
          <p className="page-sub" style={{ margin: 0 }}>
            {t("Who's signed in right now, across the whole team.")}
          </p>

          {staffOpsError && (
            <div className="card" style={{ marginTop: 16, padding: 16, borderColor: "var(--st-missing)", background: "var(--st-missing-bg)" }}>
              <p style={{ fontSize: 13, color: "var(--st-missing)", fontWeight: 600 }}>{t(staffOpsError)}</p>
            </div>
          )}

          {!staffOps && !staffOpsError && (
            <div className="muted" style={{ marginTop: 24 }}>{t("Loading…")}</div>
          )}

          {staffOps && (
            <>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 16, marginTop: 16 }}>
                <div className="card" style={{ padding: 20, display: "flex", flexDirection: "column", gap: 10 }}>
                  <div className="row" style={{ gap: 8 }}>
                    <span style={{ ...S.iconBadge, background: "var(--st-present-bg)", color: "var(--st-present)" }}>
                      <Radio size={16} />
                    </span>
                    <span className="muted" style={{ fontSize: 13, fontWeight: 600 }}>{t("Active now")}</span>
                  </div>
                  <div style={{ fontSize: 30, fontWeight: 700 }}>{staffOps.activeCount}</div>
                </div>
                <div className="card" style={{ padding: 20, display: "flex", flexDirection: "column", gap: 10 }}>
                  <div className="row" style={{ gap: 8 }}>
                    <span style={{ ...S.iconBadge, background: "var(--scc-red-tint)", color: "var(--scc-red)" }}>
                      <Users size={16} />
                    </span>
                    <span className="muted" style={{ fontSize: 13, fontWeight: 600 }}>{t("Total staff accounts")}</span>
                  </div>
                  <div style={{ fontSize: 30, fontWeight: 700 }}>{staffOps.totalStaff}</div>
                  {(staffOps.adminCount != null && staffOps.staffCount != null) && (
                    <div className="muted" style={{ fontSize: 13 }}>
                      {staffOps.adminCount} {t("Admin")} · {staffOps.staffCount} {t("Staff")}
                    </div>
                  )}
                </div>
              </div>

              <div className="card" style={{ marginTop: 16, padding: 20 }}>
                <div className="row between" style={{ flexWrap: "wrap", gap: 10 }}>
                  <h2 style={{ fontSize: 15, margin: 0 }}>{t("Active sessions")}</h2>
                  {staffOps.active.length > 0 && (
                    <span className="muted" style={{ fontSize: 12.5 }}>
                      {visibleActiveStaff.length} {t("of")} {staffOps.active.length}
                    </span>
                  )}
                </div>

                {staffOps.active.length === 0 ? (
                  <div className="muted" style={{ fontSize: 13, marginTop: 14 }}>{t("No one is currently active.")}</div>
                ) : (
                  <>
                    {/* Search + role filter — 40+ people signed in at once
                        made this an unbroken wall of names (2026-07-24). */}
                    <div className="row" style={{ gap: 10, marginTop: 14, flexWrap: "wrap" }}>
                      <div style={{ position: "relative", maxWidth: 240, flex: "1 1 180px" }}>
                        <Search size={15} style={{ position: "absolute", left: 10, top: "50%", transform: "translateY(-50%)", color: "var(--ink-3)" }} />
                        <input
                          className="input"
                          style={{ paddingLeft: 32 }}
                          placeholder={t("Search name…")}
                          value={staffOpsSearch}
                          onChange={(e) => setStaffOpsSearch(e.target.value)}
                        />
                      </div>
                      <select className="select" style={{ maxWidth: 160 }} value={staffOpsRoleFilter} onChange={(e) => setStaffOpsRoleFilter(e.target.value)}>
                        <option value="ALL">{t("All roles")}</option>
                        <option value="admin">{t("Admin")}</option>
                        <option value="staff">{t("Staff")}</option>
                      </select>
                      {staffOpsFiltersActive && (
                        <button className="btn btn-ghost" style={{ padding: "6px 10px", fontSize: 12.5 }} onClick={() => { setStaffOpsSearch(""); setStaffOpsRoleFilter("ALL"); }}>
                          {t("Clear filters")}
                        </button>
                      )}
                    </div>

                    {/* Fixed-height scroll area, 4-up grid instead of one
                        name per row (2026-07-24) — a single column left a
                        lot of empty horizontal space once there were 40+
                        people signed in at once. auto-fill (not auto-fit) —
                        auto-fit COLLAPSES unused tracks and lets the real
                        ones stretch to fill the row, so with just 1 result
                        that one card stretched across the entire width;
                        auto-fill keeps the empty tracks in place instead, so
                        a card never grows past its own column. */}
                    <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 10, marginTop: 16, maxHeight: 420, overflowY: "auto", alignContent: "start", paddingRight: 4 }}>
                      {visibleActiveStaff.length === 0 && (
                        <div className="muted" style={{ fontSize: 13, textAlign: "center", padding: "16px 0", gridColumn: "1 / -1" }}>
                          {t("No one matches your filters.")}
                        </div>
                      )}
                      {visibleActiveStaff.map((acc) => (
                        <div key={acc.id} className="row" style={{ gap: 10, padding: "8px 10px", borderRadius: "var(--r-sm)", minWidth: 0 }}>
                          <span className="avatar" style={{ background: "var(--st-present-bg)", color: "var(--st-present)", flexShrink: 0 }}>
                            {(acc.name || acc.username).trim().split(/\s+/).map((w) => w[0]).slice(0, 2).join("").toUpperCase()}
                          </span>
                          <div style={{ minWidth: 0, flex: 1 }}>
                            <div style={{ fontSize: 13.5, fontWeight: 500, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{acc.name || acc.username}</div>
                            <div className="row" style={{ gap: 5, marginTop: 1 }}>
                              <span style={{ width: 6, height: 6, borderRadius: "50%", background: "var(--st-present)", flexShrink: 0 }} />
                              <span className="muted" style={{ fontSize: 11.5 }}>{staffOpsTimeAgo(acc.last_seen_at, t)}</span>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </>
                )}
              </div>
            </>
          )}
        </div>
      )}

      {/* Both tabs share this one fragment because the Add/Edit delegate modal
          at the bottom of it has to stay mounted for the roster table, and the
          KPI/coach/history widgets and the table are just two sections of it
          (2026-07-28 restructure). Each section is gated individually below. */}
      {(tab === "overview" || tab === "delegates") && (
      <>

      {/* ---- Sub-tabs, only inside "Delegate management" ------------------ */}
      {tab === "delegates" && (
        <div className="row" style={{ gap: 6, marginTop: 20, flexWrap: "wrap" }}>
          {[
            ...(perms.viewDelegates ? [["list", t("All delegates"), Users]] : []),
            ...(perms.viewHistory ? [["checkpointHistory", t("Checkpoint history"), History]] : []),
            ...(isAdmin ? [["rooms", t("Room Management"), BedDouble]] : []),
          ].map(([key, label, Icon]) => (
            <button key={key} type="button" onClick={() => setDelegateSubTab(key)}
              style={{
                display: "inline-flex", alignItems: "center", gap: 6, cursor: "pointer",
                fontSize: 12.5, fontWeight: 600, padding: "6px 12px", borderRadius: 999,
                background: delegateSubTab === key ? "var(--scc-red-tint)" : "var(--surface-2)",
                color: delegateSubTab === key ? "var(--scc-red)" : "var(--ink-2)",
                border: `1px solid ${delegateSubTab === key ? "var(--scc-red)" : "var(--line)"}`,
              }}>
              <Icon size={14} /> {label}
            </button>
          ))}
        </div>
      )}

      {tab === "delegates" && delegateSubTab === "rooms" && isAdmin && (
        <RoomManagementTab delegates={delegates} coaches={coaches} coachName={coachName} onSaved={load} t={t} lang={lang} tripId={selectedTripId} />
      )}

      {tab === "delegates" && delegateSubTab === "checkpointHistory" && perms.viewHistory && (
        <CheckpointHistoryTab coaches={coaches} t={t} tripId={selectedTripId} />
      )}

      {tab === "overview" && perms.viewDashboard && (
      <>
      {/* ---- KPI tiles ------------------------------------------------------
       * Missing + Late keep the full attention-grabbing tile treatment — they're
       * the two statuses that need someone to actually DO something. Arrived /
       * Assigned / Unassigned are calmer "where is everyone" counts, so they're
       * folded into one compact Roster breakdown card (a proportional bar +
       * 3 small stats) instead of 3 more full-size tiles — 5 equal-weight
       * cards in a row was reads as visual noise when only 2 of them are
       * actually urgent (2026-07-22 redesign, was a flat 5-tile kpi-grid).
       * ---------------------------------------------------------------------- */}
      {k && (
        <div className="kpi-row">
          {/* "of N" and the ring's denominator use trackable (assigned/
              arrived/late/missing), not total — an Unassigned delegate
              (including a Cancelled one, always forced to Unassigned) was
              never on a coach's roster and can't meaningfully be "missing",
              so counting them here overstated N (2026-07-24). */}
          <Kpi tone="missing" icon={AlertTriangle} label={t("Missing right now")} value={`${k.missing}`}
            suffix={`${t("of")} ${k.trackable ?? k.total}`}
            foot={(() => {
              const live = liveDepartsIn(trip?.departureAt);
              const d = live ?? (trip?.departsIn ? fmtDepartsIn(trip.departsIn) : null);
              // 2026-07-30 — "can you say departure back to [country] in [x]
              // hour" / "add the country from and to": names WHERE the
              // delegation is heading back to (trip.countryFrom — editable
              // per trip on the Edit Trip form, defaults to Singapore since
              // that's SCCCI's real usage today) instead of a bare duration
              // with no destination context.
              return d ? `${t("Departure back to")} ${trip?.countryFrom || "Singapore"} ${t("in")} ${d}` : null;
            })()} big
            ringValue={k.missing} ringTotal={k.trackable ?? k.total}
            onClick={() => showDelegatesFiltered("MISSING")} />
          <Kpi tone="late" icon={Clock} label={t("Late")} value={`${k.late ?? 0}`}
            foot={t("Past cut-off, not checked in")}
            ringValue={k.late ?? 0} ringTotal={k.trackable ?? k.total}
            onClick={() => showDelegatesFiltered("LATE")} />
          <RosterCard t={t} k={k} onFilter={showDelegatesFiltered} />
        </div>
      )}

      {/* ---- Coach status + Live activity -------------------------------- */}
      {data && (
        <div className="dash-two-col" style={S.twoCol}>
          <div className="card" style={{ padding: 22, display: "flex", flexDirection: "column" }}>
            <div className="row between" style={{ marginBottom: 16 }}>
              <h2 style={{ fontSize: 16 }}>{t("Coach status")}</h2>
              <div className="row" style={{ gap: 10 }}>
                <span className="muted" style={{ fontSize: 13 }}>{coaches.length} {t("coaches")}</span>
                <button
                  className="btn btn-ghost"
                  style={{ padding: "4px 10px", fontSize: 12.5 }}
                  onClick={() => setHeadcountOpen(true)}
                  title={t("Who's still missing, per coach — the same view staff see on the Check-in screen.")}
                >
                  <Users size={13} /> {t("More details")}
                </button>
              </div>
            </div>
            {coaches.length === 0 ? (
              <div className="muted" style={{ fontSize: 13 }}>{t("No coaches for this trip yet.")}</div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
                {(showAllCoaches ? coaches : coaches.slice(0, COACH_TOP_N)).map((c) => (
                  <CoachBar key={c.id} coach={c} onOpen={currentTripUuid ? openCoachBoard : undefined} />
                ))}
              </div>
            )}
            {coaches.length > COACH_TOP_N && (
              <div style={{ marginTop: "auto", paddingTop: 16, textAlign: "center" }}>
                <button className="btn btn-ghost" onClick={() => setShowAllCoaches((v) => !v)}>
                  {showAllCoaches ? t("Show less") : `${t("Show all")} ${coaches.length}`}
                </button>
              </div>
            )}
          </div>

          <div className="card" style={{ padding: 22, display: "flex", flexDirection: "column" }}>
            <div className="row between" style={{ marginBottom: 10 }}>
              <div className="row" style={{ gap: 8 }}>
                <Activity size={18} color="var(--ink-3)" />
                <h2 style={{ fontSize: 16 }}>{t("History tracker")}</h2>
              </div>
              <div className="row" style={{ gap: 8 }}>
                <button
                  className="btn btn-ghost"
                  style={{ padding: "4px 10px", fontSize: 12.5 }}
                  onClick={() => navigate("/history")}
                  title={t("Open the full date-stamped audit log")}
                >
                  <ChevronRight size={13} /> {t("View full log")}
                </button>
                {perms.manageDelegates && history.length > 0 && (
                  <button className="btn btn-ghost" style={{ padding: "4px 10px", fontSize: 12.5 }} onClick={clearHistory}>
                    <Trash2 size={13} /> {t("Clear all")}
                  </button>
                )}
              </div>
            </div>
            <div className="row" style={{ gap: 2, background: "var(--surface-2)", borderRadius: 999, padding: 2, width: "fit-content", marginBottom: 14 }}>
              {[["trip", t("This trip")], ["all", t("All trips")]].map(([k, label]) => (
                <button key={k} onClick={() => setHistoryScope(k)}
                  style={{
                    fontSize: 12, fontWeight: 600, padding: "4px 10px", borderRadius: 999, border: "none", cursor: "pointer",
                    background: historyScope === k ? "var(--surface)" : "transparent",
                    color: historyScope === k ? "var(--ink)" : "var(--ink-3)",
                  }}>
                  {label}
                </button>
              ))}
            </div>
            {history.length === 0 ? (
              <div className="muted" style={{ fontSize: 13 }}>
                {t("No activity yet. Add or update a delegate to see events here.")}
              </div>
            ) : (() => {
              const todayStr = new Date().toDateString();
              const todayEntries = history.filter((a) => a.createdAt && new Date(a.createdAt).toDateString() === todayStr);
              const shown = historyShowAll ? history : todayEntries;
              const earlierCount = history.length - todayEntries.length;
              return (
              <div style={{ display: "flex", flexDirection: "column", gap: 14, maxHeight: 360, overflowY: "auto", paddingRight: 4 }}>
                {shown.length === 0 && (
                  <div className="muted" style={{ fontSize: 13 }}>{t("Nothing today yet.")}</div>
                )}
                {shown.map((a) => (
                  <div key={a.id} className="row between" style={{ gap: 12, alignItems: "flex-start", flexShrink: 0 }}>
                    <div className="row" style={{ gap: 12, alignItems: "flex-start" }}>
                      <span style={{ ...S.dot, background: activityColor(a.kind), marginTop: 6 }} />
                      <div>
                        <div style={{ fontSize: 14 }}>{translateActivityText(a.text, t)}</div>
                        <div className="muted" style={{ fontSize: 12 }}>{a.time} · {a.via === "you" ? t("you") : a.via}</div>
                      </div>
                    </div>
                    {perms.manageDelegates && (
                      <button onClick={() => removeHistoryEntry(a.id)} aria-label="Delete" style={{ ...S.iconBtn, color: "var(--st-missing)" }}>
                        <Trash2 size={14} />
                      </button>
                    )}
                  </div>
                ))}
                {!historyShowAll && earlierCount > 0 && (
                  <button className="btn btn-ghost" style={{ fontSize: 12.5, alignSelf: "flex-start", flexShrink: 0 }} onClick={() => setHistoryShowAll(true)}>
                    {t("Show")} {earlierCount} {t("earlier")}
                  </button>
                )}
                {historyShowAll && earlierCount > 0 && (
                  <button className="btn btn-ghost" style={{ fontSize: 12.5, alignSelf: "flex-start", flexShrink: 0 }} onClick={() => setHistoryShowAll(false)}>
                    {t("Show today only")}
                  </button>
                )}
              </div>
              );
            })()}
          </div>
        </div>
      )}

      </>
      )}

      {/* ---- All delegates (CRUD surface) — now the "list" sub-tab of
              Delegate management (2026-07-28) ------------------------------- */}
      {tab === "delegates" && delegateSubTab === "list" && perms.viewDelegates && data && (
        <div ref={delegateTableRef} className="card" style={{ marginTop: 20, overflow: "hidden" }}>
          <div className="row between" style={{ padding: "18px 20px", borderBottom: "1px solid var(--line)" }}>
            <div>
              <h2 style={{ fontSize: 16 }}>{t("All delegates")}</h2>
              <p className="muted" style={{ fontSize: 13, marginTop: 2 }}>
                {t("Create, edit, and remove attendance records")}
              </p>
            </div>
            <div className="row" style={{ gap: 10 }}>
              {perms.manageDelegates && selectedDelegateIds.size > 0 && (
                <button
                  className="btn btn-ghost"
                  style={{ color: "var(--st-missing)", borderColor: "var(--st-missing-bg)" }}
                  onClick={deleteSelectedDelegates}
                  disabled={deletingSelectedDelegates}
                >
                  <Trash2 size={16} /> {deletingSelectedDelegates ? t("Deleting…") : `${t("Delete selected")} (${selectedDelegateIds.size})`}
                </button>
              )}
              {perms.manageDelegates && delegates.length > 0 && (
                <button className="btn btn-ghost" style={{ color: "var(--st-missing)", borderColor: "var(--st-missing-bg)" }} onClick={deleteAll}>
                  <Trash2 size={16} /> {t("Delete all")}
                </button>
              )}
              {perms.manageDelegates && (
                <button className="btn btn-primary" onClick={openCreate}>
                  <Plus size={16} /> {t("Add delegate")}
                </button>
              )}
            </div>
          </div>

          {delegates.length > 0 && (
            <div className="row" style={{ gap: 10, padding: "12px 20px", borderBottom: "1px solid var(--line)", flexWrap: "wrap" }}>
              <input
                className="input"
                style={{ maxWidth: 240, flex: "1 1 180px" }}
                placeholder={t("Search delegates…")}
                value={delegateQuery}
                onChange={(e) => setDelegateQuery(e.target.value)}
              />
              <select className="select" style={{ maxWidth: 170 }} value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
                <option value="ALL">{t("All statuses")}</option>
                <optgroup label={t("Status")}>
                  <option value="UNASSIGNED">{t("Unassigned")}</option>
                  <option value="ASSIGNED">{t("Assigned")}</option>
                  <option value="ARRIVED">{t("Arrived")}</option>
                  <option value="LATE">{t("Late")}</option>
                  <option value="MISSING">{t("Missing")}</option>
                </optgroup>
                {/* Not a real status (see schema.js's comment on the
                    `cancelled` column) — grouped apart so it doesn't read as
                    a 6th value in the same enum as the 5 above. */}
                <optgroup label={t("Other")}>
                  <option value="CANCELLED">{t("Cancelled")}</option>
                </optgroup>
              </select>
              {/* Coach-assignment filter — matches the mobile Attendance
                  page's coach filter. Options come from the live coach list
                  plus an explicit "Unassigned" (delegates with no coach). */}
              <select className="select" style={{ maxWidth: 190 }} value={coachFilter} onChange={(e) => setCoachFilter(e.target.value)}>
                <option value="ALL">{t("All coaches")}</option>
                <optgroup label={t("Coaches")}>
                  {coaches.map((c) => (
                    <option key={c.id} value={c.id}>{coachDisplayName(c)}</option>
                  ))}
                </optgroup>
              </select>
              <select className="select" style={{ maxWidth: 190 }} value={sortMode} onChange={(e) => setSortMode(e.target.value)}>
                <option value="name">{t("Sort: Name")}</option>
                <option value="recent">{t("Sort: Recently added")}</option>
                <option value="status">{t("Sort: Status")}</option>
                <option value="coach">{t("Sort: Coach")}</option>
              </select>
              <span className="muted" style={{ fontSize: 13, marginLeft: "auto" }}>
                {visibleDelegates.length} {t("delegates match")}
              </span>
              {delegateFiltersActive && (
                <button className="btn btn-ghost" style={{ padding: "6px 10px", fontSize: 12.5 }} onClick={clearDelegateFilters}>
                  {t("Clear filters")}
                </button>
              )}
            </div>
          )}

          {delegates.length === 0 ? (
            <div className="muted" style={{ padding: 24, fontSize: 14 }}>
              {t("No delegates yet. Click")} <strong>{t("Add delegate")}</strong> {t("to create your first record.")}
            </div>
          ) : (
            // overflowX added (2026-07-24, mobile responsiveness pass) so
            // this many-column table scrolls horizontally on a narrow
            // screen instead of clipping/squishing columns.
            <div style={{ maxHeight: 640, overflowY: "auto", overflowX: "auto" }}>
            <table className="table" style={{ minWidth: 720 }}>
              <thead style={{ position: "sticky", top: 0, zIndex: 1, background: "var(--surface)" }}>
                <tr>
                  {perms.manageDelegates && (
                    <th style={{ width: 36 }}>
                      <input
                        type="checkbox"
                        checked={rowsShown.length > 0 && rowsShown.every((d) => selectedDelegateIds.has(d.id))}
                        onChange={() => setSelectedDelegateIds((prev) => {
                          const allChecked = rowsShown.length > 0 && rowsShown.every((d) => prev.has(d.id));
                          return allChecked ? new Set() : new Set(rowsShown.map((d) => d.id));
                        })}
                        disabled={rowsShown.length === 0}
                        aria-label={t("Select all")}
                      />
                    </th>
                  )}
                  <th>{t("Delegate")}</th><th>{t("Coach")}</th><th>{t("Status")}</th>
                  <th>{t("Uploaded")}</th>
                  {showCreatedByCol && <th>{t("Created by")}</th>}
                  <th style={{ width: 90 }} />
                </tr>
              </thead>
              <tbody>
                {rowsShown.map((d) => (
                  <tr key={d.id}>
                    {perms.manageDelegates && (
                      <td>
                        <input
                          type="checkbox"
                          checked={selectedDelegateIds.has(d.id)}
                          onChange={() => toggleDelegateSelected(d.id)}
                          aria-label={`${t("Select")} ${d.name}`}
                        />
                      </td>
                    )}
                    <td>
                      <button
                        onClick={() => openProfile(d)}
                        className="row"
                        style={{ gap: 10, background: "none", border: "none", padding: 0, cursor: "pointer", textAlign: "left" }}
                        aria-label={`${t("View profile")} — ${d.name}`}
                      >
                        <DelegateAvatar delegate={d} />
                        <span style={{ fontWeight: 500, color: "var(--ink-1)" }}>{d.name}</span>
                        {d.vip && (
                          <span className="badge badge-review" style={{ padding: "2px 8px" }}>
                            <Crown size={12} /> {t("VIP")}
                          </span>
                        )}
                      </button>
                    </td>
                    <td>{coachName(d.coachId)}</td>
                    <td>
                      <div className="row" style={{ gap: 6 }}>
                        <StatusBadge state={d.status} />
                        {d.cancelled && <span className="badge badge-neutral" style={{ padding: "2px 8px" }}>{t("Cancelled")}</span>}
                        {d.escalated && (
                          <span className="badge badge-missing" style={{ padding: "2px 8px" }}>
                            <Siren size={11} /> {t("Escalated")}
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="muted">{fmtUploadDate(d.createdAt)}</td>
                    {showCreatedByCol && <td className="muted">{d.createdBy || "—"}</td>}
                    <td>
                      <div className="row" style={{ gap: 6 }}>
                        {/* Standalone "View profile" (Eye) button removed
                            (2026-07-27, advised) — clicking the delegate's
                            NAME cell already calls the exact same
                            openProfile(d), so the icon button was a fully
                            redundant second control for the same action;
                            Edit has no other entry point in this row, so it
                            stays. */}
                        {perms.manageDelegates && (
                          <>
                            <button onClick={() => openEdit(d)} aria-label={`${t("Edit")} ${d.name}`}
                              style={S.iconBtn}>
                              <Pencil size={16} />
                            </button>
                            <button onClick={() => remove(d)} aria-label={`${t("Delete")} ${d.name}`}
                              style={{ ...S.iconBtn, color: "var(--st-missing)" }}>
                              <Trash2 size={16} />
                            </button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
                {visibleDelegates.length === 0 && (
                  <tr>
                    <td colSpan={(perms.manageDelegates ? 1 : 0) + 4 + (showCreatedByCol ? 1 : 0) + 1} className="muted" style={{ padding: 24, fontSize: 14, textAlign: "center" }}>
                      {t("No delegates match your filters.")}
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
            </div>
          )}
          {visibleDelegates.length > 0 && (
            <div className="row between" style={{ padding: "12px 20px", borderTop: "1px solid var(--line)", flexWrap: "wrap", gap: 10 }}>
              <span className="muted" style={{ fontSize: 12.5 }}>
                {t("Showing")} {clampedPage * delegatePageSize + 1}–{Math.min((clampedPage + 1) * delegatePageSize, visibleDelegates.length)} {t("of")} {visibleDelegates.length}
              </span>
              <div className="row" style={{ gap: 8, alignItems: "center" }}>
                <span className="muted" style={{ fontSize: 12.5 }}>{t("Rows per page")}</span>
                <select className="select" style={{ width: 76, padding: "4px 8px" }} value={delegatePageSize}
                  onChange={(e) => setDelegatePageSize(Number(e.target.value))}>
                  {[10, 25, 50, 100].map((n) => <option key={n} value={n}>{n}</option>)}
                </select>
              </div>
              <div className="row" style={{ gap: 8, alignItems: "center" }}>
                <button className="btn btn-ghost" style={{ padding: "4px 10px" }} disabled={clampedPage === 0}
                  onClick={() => setDelegatePage((p) => Math.max(0, p - 1))}>
                  <ChevronLeft size={14} /> {t("Prev")}
                </button>
                <span className="muted" style={{ fontSize: 12.5 }}>{t("Page")} {clampedPage + 1} {t("of")} {pageCount}</span>
                <button className="btn btn-ghost" style={{ padding: "4px 10px" }} disabled={clampedPage >= pageCount - 1}
                  onClick={() => setDelegatePage((p) => Math.min(pageCount - 1, p + 1))}>
                  {t("Next")} <ChevronRight size={14} />
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ---- Create / Edit modal ----------------------------------------- */}
      {modalOpen && (
        <div style={S.overlay}
          onMouseDown={(e) => { downOnBackdrop.current = e.target === e.currentTarget; }}
          onClick={(e) => { if (!saving && downOnBackdrop.current && e.target === e.currentTarget) setModalOpen(false); }}>
          <div className="card" style={S.modal} onClick={(e) => e.stopPropagation()}>
            <div className="row between" style={{ marginBottom: 18 }}>
              <h2 style={{ fontSize: 18 }}>{editingId ? t("Edit delegate") : t("Add delegate")}</h2>
              <button onClick={() => setModalOpen(false)} style={S.iconBtn} aria-label={t("Close")}>
                <X size={18} />
              </button>
            </div>

            {editingId && (
              <div className="row" style={{ gap: 14, marginBottom: 18 }}>
                {/* Status-toned across all 5 states via the shared statusTone()
                    helper (DelegateAvatar.jsx) — was MISSING-vs-everyone-else
                    binary, so an Unassigned/Assigned/Late delegate's header
                    all showed the same green as Arrived. */}
                {editingPhotoUrl ? (
                  <img src={editingPhotoUrl} alt="" style={{ width: 56, height: 56, borderRadius: "50%", objectFit: "cover", flexShrink: 0, boxShadow: `0 0 0 2px ${statusTone(form.status).fg}` }} />
                ) : (
                  <span
                    className="avatar"
                    style={{
                      width: 56, height: 56, fontSize: 20,
                      background: statusTone(form.status).bg,
                      color: statusTone(form.status).fg,
                      boxShadow: `inset 0 0 0 1.5px ${statusTone(form.status).fg}`,
                    }}
                  >
                    {form.name.trim().split(/\s+/).map((w) => w[0]).slice(0, 2).join("").toUpperCase() || "?"}
                  </span>
                )}
                <div>
                  <label className="btn btn-ghost" style={{ cursor: "pointer", display: "inline-flex" }}>
                    {photoBusy ? t("Saving…") : t("Upload photo")}
                    <input
                      type="file"
                      accept="image/*"
                      disabled={photoBusy}
                      style={{ display: "none" }}
                      onChange={(e) => { const f = e.target.files?.[0]; if (f) setCropFile(f); e.target.value = ""; }}
                    />
                  </label>
                  {editingPhotoUrl && (
                    <button className="btn btn-ghost" style={{ marginLeft: 8, color: "var(--st-missing)" }} disabled={photoBusy} onClick={handleRemovePhoto}>
                      {t("Remove")}
                    </button>
                  )}
                  {photoErr && <div style={{ fontSize: 12, color: "var(--st-missing)", marginTop: 6 }}>{t(photoErr)}</div>}
                </div>
              </div>
            )}

            <label className="field-label">{t("Full name")}</label>
            <input className="input" autoFocus value={form.name}
              placeholder={t("e.g. Lim Wei Jie")}
              onChange={(e) => setForm({ ...form, name: e.target.value })} />

            <label className="field-label" style={{ marginTop: 14 }}>{t("Phone")} <span style={{ color: "var(--st-missing)" }}>*</span></label>
            <input className="input" type="tel" value={form.phone}
              placeholder={t("e.g. +65 9123 4567")}
              onChange={(e) => setForm({ ...form, phone: e.target.value })} />

            <label className="field-label" style={{ marginTop: 14 }}>{t("Status")}</label>
            <select className="select" value={form.status}
              onChange={(e) => {
                const status = e.target.value;
                // Cancelled only ever applies to an Unassigned delegate (see
                // the checkbox below) — moving away from Unassigned clears
                // it rather than leaving a stale, now-hidden flag set.
                setForm((f) => ({ ...f, status, cancelled: status === "UNASSIGNED" ? f.cancelled : false }));
              }}>
              <option value="UNASSIGNED">{t("Unassigned")}</option>
              <option value="ASSIGNED">{t("Assigned")}</option>
              <option value="ARRIVED">{t("Arrived")}</option>
              <option value="LATE">{t("Late")}</option>
              <option value="MISSING">{t("Missing")}</option>
            </select>

            {/* Coach field removed from this modal (2026-07-27 — "remove the
                assigned to coach, cause that my teammate feature") — coach
                assignment is Desmond's Trips board (drag-and-drop), not this
                Dashboard form. An existing delegate's coachId is still
                preserved untouched via openEdit()/form state above; this
                modal just no longer offers a control to change it. Setting
                Status to "Unassigned" still correctly clears it (see the
                submit payload below), so releasing someone from their coach
                is still possible here — assigning one just isn't. */}

            {form.status === "MISSING" && (
              <>
                <label className="field-label" style={{ marginTop: 14 }}>{t("Last seen (optional)")}</label>
                <input className="input" value={form.lastSeen}
                  placeholder={t("e.g. Lobby · 14:08")}
                  onChange={(e) => setForm({ ...form, lastSeen: e.target.value })} />

                <label className="field-label" style={{ marginTop: 14 }}>
                  {t("Last known location")} <span className="muted">({t("required")})</span>
                </label>
                <input className="input" value={form.lastLocation}
                  placeholder={t("e.g. Novotel Beijing Sanyuan, Lobby")}
                  onChange={(e) => setForm({ ...form, lastLocation: e.target.value })} />
                <button
                  type="button"
                  className="btn btn-ghost"
                  style={{ marginTop: 8 }}
                  onClick={useMyLocation}
                  disabled={locating}
                >
                  <LocateFixed size={15} /> {locating ? t("Locating…") : t("Use my current location")}
                </button>
                {locateError && (
                  <div className="muted" style={{ fontSize: 12, color: "var(--st-missing)", marginTop: 6 }}>{t(locateError)}</div>
                )}
                {form.lastLocation.trim() && (
                  <div style={{ marginTop: 8 }}>
                    <DelegateLocationMap location={form.lastLocation.trim()} height={160} />
                  </div>
                )}
              </>
            )}

            <label className="row" style={{ gap: 8, marginTop: 16, fontSize: 14, cursor: "pointer" }}>
              <input type="checkbox" checked={form.vip}
                onChange={(e) => setForm({ ...form, vip: e.target.checked })} />
              {t("Mark as VIP")}
            </label>

            {/* Only meaningful once a delegate is already Unassigned — a
                cancellation IS an unassignment, not a separate action that
                triggers one, so the checkbox only appears here rather than
                alongside every status (2026-07-24 feedback). */}
            {editingId && form.status === "UNASSIGNED" && (
              <label style={{ display: "block", marginTop: 10, fontSize: 14, cursor: "pointer" }}>
                <span className="row" style={{ gap: 8 }}>
                  <input type="checkbox" checked={form.cancelled}
                    onChange={(e) => setForm({ ...form, cancelled: e.target.checked })} />
                  {t("Cancelled")}
                </span>
                <span className="muted" style={{ display: "block", fontSize: 12, marginTop: 2, marginLeft: 24 }}>
                  {t("Optional — records that this delegate specifically dropped out, rather than never having been assigned.")}
                </span>
              </label>
            )}

            {editingId && form.cancelled && (
              <div style={{ marginTop: 10, marginLeft: 24 }}>
                <label className="field-label">{t("What happened?")}</label>
                <textarea className="input" rows={2} style={{ resize: "vertical", fontFamily: "inherit" }}
                  placeholder={t("e.g. Flight cancelled, called in sick, no longer travelling with the group…")}
                  value={form.cancelReason}
                  onChange={(e) => setForm({ ...form, cancelReason: e.target.value })} />
              </div>
            )}

            <button
              type="button"
              onClick={() => setShowMoreFields((v) => !v)}
              className="row"
              style={{ gap: 6, marginTop: 16, background: "none", border: "none", padding: 0, cursor: "pointer", color: "var(--scc-red)", fontSize: 13, fontWeight: 600 }}
            >
              <ChevronRight size={15} style={{ transform: showMoreFields ? "rotate(90deg)" : "none", transition: "transform 0.15s" }} />
              {t("More details")}
            </button>

            {showMoreFields && (
              <div style={{ marginTop: 12, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                <div>
                  <label className="field-label">{t("Role")}</label>
                  <input className="input" value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })} />
                </div>
                <div>
                  <label className="field-label">{t("Company")}</label>
                  <input className="input" value={form.company} onChange={(e) => setForm({ ...form, company: e.target.value })} />
                </div>
                <div>
                  <label className="field-label">{t("Industry")}</label>
                  <input className="input" value={form.industry} onChange={(e) => setForm({ ...form, industry: e.target.value })} />
                </div>
                <div>
                  <label className="field-label">{t("Nationality")}</label>
                  <input className="input" value={form.nationality} onChange={(e) => setForm({ ...form, nationality: e.target.value })} />
                </div>
                <div>
                  <label className="field-label">{t("Email")}</label>
                  <input className="input" type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
                </div>
                <div>
                  <label className="field-label">{t("Website")}</label>
                  <input className="input" value={form.website} onChange={(e) => setForm({ ...form, website: e.target.value })} />
                </div>
                <div>
                  <label className="field-label">{t("Passport number")}</label>
                  <input className="input mono" value={form.passportNumber} onChange={(e) => setForm({ ...form, passportNumber: e.target.value })} />
                </div>
                <div>
                  <label className="field-label">{t("Passport expiry")}</label>
                  <input className="input" type="date" value={form.passportExpiry} onChange={(e) => setForm({ ...form, passportExpiry: e.target.value })} />
                </div>
                <div>
                  <label className="field-label">{t("Hotel")}</label>
                  <input className="input" value={form.hotelName} onChange={(e) => setForm({ ...form, hotelName: e.target.value })} />
                </div>
                <div>
                  <label className="field-label">{t("Room number")}</label>
                  <input className="input" value={form.roomNumber} onChange={(e) => setForm({ ...form, roomNumber: e.target.value })} />
                </div>
                <div style={{ gridColumn: "1 / -1" }}>
                  <label className="field-label">{t("Accessibility notes")}</label>
                  <input className="input" value={form.accessibilityNotes} onChange={(e) => setForm({ ...form, accessibilityNotes: e.target.value })} />
                </div>
                <div style={{ gridColumn: "1 / -1" }}>
                  <label className="field-label">{t("Notes")}</label>
                  <textarea className="input" rows={2} style={{ resize: "vertical", fontFamily: "inherit" }}
                    value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} />
                </div>
              </div>
            )}

            {formErr && (
              <div style={{
                display: "flex", alignItems: "center", gap: 8, marginTop: 16, padding: "10px 12px",
                background: "var(--st-missing-bg)", color: "var(--st-missing)", borderRadius: "var(--r-sm)",
                fontSize: 13, fontWeight: 600,
              }}>
                {t(formErr)}
              </div>
            )}

            <div className="row" style={{ gap: 10, marginTop: 24, justifyContent: "flex-end" }}>
              <button className="btn btn-ghost" onClick={() => setModalOpen(false)} disabled={saving}>
                {t("Cancel")}
              </button>
              <button className="btn btn-primary" onClick={saveForm} disabled={saving || !form.name.trim() || !form.phone.trim()}>
                {saving ? t("Saving…") : editingId ? t("Save changes") : t("Add delegate")}
              </button>
            </div>
          </div>
        </div>
      )}
      </>
      )}

      {/* ---- Delegate profile view --------------------------------------
          Combines what used to be 3 separate popups (edit modal's
          read-only info, checkpoint timeline modal, location map modal)
          into one scrollable panel (2026-07-24). Read-only — the "Edit"
          button switches to the existing Create/Edit modal for changes. */}
      {profileDelegate && (
        <div style={S.overlay}
          onMouseDown={(e) => { downOnBackdrop.current = e.target === e.currentTarget; }}
          onClick={(e) => { if (downOnBackdrop.current && e.target === e.currentTarget) setProfileDelegate(null); }}>
          <div className="card" style={{ ...S.modal, width: "min(640px, 100%)", maxHeight: "88vh", overflowY: "auto" }} onClick={(e) => e.stopPropagation()}>
            <div className="row between" style={{ marginBottom: 18, alignItems: "flex-start" }}>
              <div className="row" style={{ gap: 14 }}>
                {profileDelegate.photoUrl ? (
                  <button
                    type="button"
                    onClick={() => setEnlargedPhoto(profileDelegate.photoUrl)}
                    aria-label={t("Enlarge photo")}
                    title={t("Enlarge photo")}
                    style={{ padding: 0, border: "none", background: "none", cursor: "zoom-in", flexShrink: 0, borderRadius: "50%" }}
                  >
                    <img src={profileDelegate.photoUrl} alt="" style={{ width: 64, height: 64, borderRadius: "50%", objectFit: "cover", boxShadow: `0 0 0 2px ${statusTone(profileDelegate.status).fg}` }} />
                  </button>
                ) : (
                  <span
                    className="avatar"
                    style={{
                      width: 64, height: 64, fontSize: 21, flexShrink: 0,
                      background: statusTone(profileDelegate.status).bg,
                      color: statusTone(profileDelegate.status).fg,
                      boxShadow: `inset 0 0 0 1.5px ${statusTone(profileDelegate.status).fg}`,
                    }}
                  >
                    {profileDelegate.name.trim().split(/\s+/).map((w) => w[0]).slice(0, 2).join("").toUpperCase() || "?"}
                  </span>
                )}
                <div>
                  <h2 style={{ fontSize: 18 }}>{profileDelegate.name}</h2>
                  <div className="row" style={{ gap: 6, marginTop: 4, flexWrap: "wrap" }}>
                    <StatusBadge state={profileDelegate.status} />
                    {profileDelegate.cancelled && (
                      <span className="badge badge-neutral" style={{ padding: "2px 8px" }}>{t("Cancelled")}</span>
                    )}
                    {profileDelegate.escalated && (
                      <span className="badge badge-missing" style={{ padding: "2px 8px" }}>
                        <Siren size={11} /> {t("Escalated")}
                      </span>
                    )}
                    {profileDelegate.vip && (
                      <span className="badge badge-review" style={{ padding: "2px 8px" }}>
                        <Crown size={12} /> {t("VIP")}
                      </span>
                    )}
                  </div>
                </div>
              </div>
              <div className="row" style={{ gap: 6, flexShrink: 0 }}>
                {/* Only offered once already Unassigned — cancelling IS an
                    unassignment, not a separate action that triggers one
                    (2026-07-24 feedback); an Assigned/Arrived/Late/Missing
                    delegate needs Edit → Unassigned first. */}
                {perms.manageDelegates && profileDelegate.status === "UNASSIGNED" && (
                  <button
                    className="btn btn-ghost"
                    style={{ fontSize: 13, padding: "6px 12px" }}
                    onClick={() => toggleCancelled(profileDelegate)}
                  >
                    {profileDelegate.cancelled ? t("Undo cancellation") : t("Mark as cancelled")}
                  </button>
                )}
                {/* Both hidden while already escalated (2026-07-25) — no
                    point offering to escalate someone again mid-escalation,
                    and Edit is hidden so this becomes a focused "what's the
                    emergency, who raised it" view rather than a normal
                    editable profile until the escalation is resolved. */}
                {perms.manageDelegates && profileDelegate.status === "MISSING" && !profileDelegate.escalated && (
                  <button
                    className="btn btn-ghost"
                    style={{ fontSize: 13, padding: "6px 12px", color: "var(--st-missing)" }}
                    onClick={() => { const d = profileDelegate; setProfileDelegate(null); openEscalate(d); }}
                  >
                    <Siren size={14} /> {t("Escalate to office")}
                  </button>
                )}
                {perms.manageDelegates && !profileDelegate.escalated && (
                  <button
                    className="btn btn-ghost"
                    style={{ fontSize: 13, padding: "6px 12px" }}
                    onClick={() => { const d = profileDelegate; setProfileDelegate(null); openEdit(d); }}
                  >
                    <Pencil size={14} /> {t("Edit")}
                  </button>
                )}
                <button onClick={() => setProfileDelegate(null)} style={S.iconBtn} aria-label={t("Close")}>
                  <X size={18} />
                </button>
              </div>
            </div>

            {/* Auto-filling columns instead of a hardcoded "1fr 1fr"
                (2026-07-28 — "desktop detail need better uiux, too much
                space"). ProfileField renders nothing when a value is empty, so
                a fixed 2-column grid left big holes and stranded single fields
                on their own row; this packs 3-4 short fields per row on a wide
                modal and still collapses to one column when narrow. */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(190px, 1fr))", gap: "12px 18px" }}>
              <ProfileField
                icon={Phone}
                label={t("Phone")}
                value={profileDelegate.phone}
                action={profileDelegate.phone && (
                  <a href={`tel:${profileDelegate.phone}`} aria-label={`${t("Call")} ${profileDelegate.phone}`} title={t("Call")}
                    style={{ ...S.iconBtn, color: "var(--st-present)", textDecoration: "none" }}>
                    <Phone size={14} />
                  </a>
                )}
              />
              <ProfileField
                icon={Globe2}
                label={t("Email")}
                value={profileDelegate.email}
                action={profileDelegate.email && (
                  <a href={`mailto:${profileDelegate.email}`} aria-label={`${t("Email")} ${profileDelegate.email}`} title={t("Email")}
                    style={{ ...S.iconBtn, color: "var(--ink-2)", textDecoration: "none" }}>
                    <Globe2 size={14} />
                  </a>
                )}
              />
              <ProfileField label={t("Coach")} value={coachName(profileDelegate.coachId)} />
              {/* While escalated, swap the profile/travel-document fields
                  (Company/Industry/Nationality/Passport) for which TRIP this
                  is under (2026-07-25) — you can land on this profile from a
                  different trip's context via the escalation banner's "View"
                  jump, and those document fields aren't what matters for an
                  active emergency. */}
              {profileDelegate.escalated ? (
                <ProfileField icon={MapPin} label={t("Trip")} value={trip?.name} />
              ) : (
                <>
                  <ProfileField icon={Briefcase} label={t("Company")} value={[profileDelegate.role, profileDelegate.company].filter(Boolean).join(" · ")} />
                  <ProfileField label={t("Industry")} value={profileDelegate.industry} />
                  <ProfileField label={t("Nationality")} value={profileDelegate.nationality} />
                  <ProfileField icon={BadgeCheck} label={t("Passport number")} value={profileDelegate.passport_no} mono />
                  <ProfileField label={t("Passport expiry")} value={profileDelegate.passport_expiry} />
                  {/* Room moved INTO this grid (2026-07-28) — it was a
                      full-width bordered card of its own for one short value
                      like "t · Room 2", which ate a whole row for almost no
                      content. Same escalated-hiding rule as the fields above. */}
                  <ProfileField
                    icon={BedDouble}
                    label={t("Room")}
                    value={
                      profileDelegate.hotel_name || profileDelegate.room_number
                        ? [profileDelegate.hotel_name, profileDelegate.room_number ? `${t("Room")} ${profileDelegate.room_number}` : null].filter(Boolean).join(" · ")
                        : <span className="muted" style={{ fontWeight: 400 }}>{t("Not assigned yet")}</span>
                    }
                  />
                </>
              )}
            </div>

            {profileDelegate.cancelled && (
              <div style={{ marginTop: 18, padding: "10px 12px", background: "var(--st-neutral-bg)", borderRadius: "var(--r-sm)" }}>
                <div className="field-label" style={{ margin: 0 }}>{t("Cancellation reason")}</div>
                <p style={{ fontSize: 13.5, marginTop: 4 }}>
                  {profileDelegate.cancel_reason || t("No reason given.")}
                </p>
              </div>
            )}

            {/* Room allocation (2026-07-26) now lives inside the field grid
                above rather than in its own bordered card — see the
                ProfileField for it there. */}

            {/* Replaces the Checkpoint timeline while an escalation is active
                (2026-07-25) — the point of opening this profile right now is
                the emergency itself, not routine scan history. */}
            {profileDelegate.escalated && (
              <div style={{
                marginTop: 18, padding: 14, borderRadius: "var(--r-md)",
                background: "var(--st-missing-bg)", border: "1px solid var(--st-missing)",
              }}>
                <div className="row" style={{ gap: 8, alignItems: "center" }}>
                  <span style={{
                    width: 26, height: 26, borderRadius: "50%", flexShrink: 0,
                    background: "var(--st-missing)", color: "#fff", display: "grid", placeItems: "center",
                  }}>
                    <Siren size={13} />
                  </span>
                  <span style={{ fontWeight: 700, fontSize: 13.5, color: "var(--st-missing)" }}>
                    {t("Escalated by")} {profileDelegate.escalatedBy || t("Staff")}
                  </span>
                </div>
                <p style={{ fontSize: 14, lineHeight: 1.45, margin: "8px 0 0 34px" }}>
                  {profileDelegate.escalationMessage || t("No message given.")}
                </p>
              </div>
            )}

            {(profileDelegate.notes || profileDelegate.accessibility_notes) && (
              <div style={{ marginTop: 18 }}>
                {profileDelegate.accessibility_notes && (
                  <div style={{ marginBottom: 10 }}>
                    <div className="field-label" style={{ display: "flex", alignItems: "center", gap: 6 }}>
                      <AlertTriangle size={13} /> {t("Accessibility notes")}
                    </div>
                    <p style={{ fontSize: 13.5, marginTop: 4 }}>{profileDelegate.accessibility_notes}</p>
                  </div>
                )}
                {profileDelegate.notes && (
                  <div>
                    <div className="field-label" style={{ display: "flex", alignItems: "center", gap: 6 }}>
                      <StickyNote size={13} /> {t("Notes")}
                    </div>
                    <p style={{ fontSize: 13.5, marginTop: 4, whiteSpace: "pre-wrap" }}>{profileDelegate.notes}</p>
                  </div>
                )}
              </div>
            )}

            {(profileDelegate.lastSeen || profileDelegate.lastLocation) && (
              <div style={{ marginTop: 18 }}>
                <div className="field-label" style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <MapPin size={13} /> {t("Last known location")}
                </div>
                <p style={{ fontSize: 13.5, marginTop: 4 }}>
                  {[profileDelegate.lastLocation, profileDelegate.lastSeen].filter(Boolean).join(" · ") || "—"}
                </p>
                {profileDelegate.lastLocation && (
                  <div style={{ marginTop: 8 }}>
                    <DelegateLocationMap location={profileDelegate.lastLocation} height={340} />
                  </div>
                )}
              </div>
            )}

            {!profileDelegate.escalated && (
              <div style={{ marginTop: 20 }}>
                <div className="field-label" style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <Clock size={13} /> {t("Checkpoint timeline")}
                </div>
                <div style={{ marginTop: 8 }}>
                  <DelegateTimeline delegateId={profileDelegate.id} defaultVisible={2} />
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Full-size photo lightbox — a separate, higher-stacked overlay so it
          layers on top of the profile panel rather than replacing it
          (2026-07-24). Click anywhere, or X, to close. */}
      {cropFile && (
        <PhotoCropModal file={cropFile} onCancel={() => setCropFile(null)} onSave={handleCropSave} t={t} />
      )}

      {/* "Mark as cancelled" reason prompt — a dedicated textfield instead
          of a plain window.confirm, since the whole point of cancelling is
          capturing WHY (2026-07-24). */}
      {/* ---- Alerts modal (2026-07-24) --------------------------------------
       * "if it missing, it will mention, late will be brief and show who
       * late... those who are cancel status also display" — then moved from
       * an inline collapsed card to this small icon-button + modal beside
       * Export, so it doesn't take a permanent row on every visit. Missing
       * gets full detail rows (last-known-location + Call, matching Reverse
       * Headcount's own treatment); Late/Cancelled are deliberately brief —
       * just wrapped name chips. Each section caps how many it shows and
       * links to the full filtered list via showDelegatesFiltered(). */}
      {alertsOpen && (
        <div style={S.overlay}
          onMouseDown={(e) => { downOnBackdrop.current = e.target === e.currentTarget; }}
          onClick={(e) => { if (downOnBackdrop.current && e.target === e.currentTarget) setAlertsOpen(false); }}>
          <div className="card" style={{ ...S.modal, width: "min(480px, 100%)", maxHeight: "85vh", overflowY: "auto" }} onClick={(e) => e.stopPropagation()}>
            <div className="row between" style={{ marginBottom: 16 }}>
              <div className="row" style={{ gap: 8 }}>
                <Bell size={18} color="var(--ink-3)" />
                <h2 style={{ fontSize: 16 }}>{t("Alerts")}</h2>
              </div>
              <button onClick={() => setAlertsOpen(false)} style={S.iconBtn} aria-label={t("Close")}><X size={18} /></button>
            </div>

            {missingNotEscalated.length === 0 && lateDelegates.length === 0 && cancelledDelegates.length === 0 && activeEscalations.length === 0 && (
              <div className="muted" style={{ fontSize: 13 }}>{t("Nothing needs your attention right now.")}</div>
            )}

            {activeEscalations.length > 0 && (() => {
              const q = escalationQuery.trim().toLowerCase();
              const filtered = q
                ? activeEscalations.filter((e) =>
                    (e.delegateName || "").toLowerCase().includes(q) ||
                    (e.message || "").toLowerCase().includes(q) ||
                    (e.createdBy || "").toLowerCase().includes(q))
                : activeEscalations;
              const visible = showAllEscalations ? filtered : filtered.slice(0, 5);
              return (
              <div style={{ marginBottom: 18 }}>
                <div className="row between" style={{ marginBottom: 8, gap: 8 }}>
                  <div className="row" style={{ gap: 6, color: "var(--st-missing)", fontWeight: 700, fontSize: 13.5 }}>
                    <Siren size={15} /> {activeEscalations.length} {t("Emergency")}
                  </div>
                  {activeEscalations.length > 5 && (
                    <input
                      className="input" style={{ fontSize: 12, padding: "4px 8px", maxWidth: 140 }}
                      placeholder={t("Search…")} value={escalationQuery}
                      onChange={(e) => { setEscalationQuery(e.target.value); setShowAllEscalations(false); }}
                    />
                  )}
                </div>
                {filtered.length === 0 ? (
                  <div className="muted" style={{ fontSize: 12.5 }}>{t("No matches.")}</div>
                ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: 8, maxHeight: 260, overflowY: "auto" }}>
                  {visible.map((e) => (
                    <div key={e.id} style={{ padding: "10px 12px", background: "var(--st-missing-bg)", borderRadius: "var(--r-sm)" }}>
                      <div className="row between" style={{ gap: 8 }}>
                        <div style={{ minWidth: 0, cursor: e.delegateId ? "pointer" : "default" }}
                          onClick={() => {
                            if (!e.delegateId) return;
                            // Look up the REAL delegate record instead of building a
                            // fake partial one from the escalation row (2026-07-25 bug
                            // fix) — the synthetic {id,name,phone,lastLocation} object
                            // was missing status/coachId/vip, so the profile panel
                            // rendered incomplete (no status badge, no Escalate button,
                            // "Unassigned" coach) instead of the real full profile.
                            const real = delegates.find((d) => d.id === e.delegateId);
                            setAlertsOpen(false);
                            openProfile(real || { id: e.delegateId, name: e.delegateName, phone: e.delegatePhone, lastLocation: e.delegateLocation });
                          }}
                        >
                          <div style={{ fontWeight: 600, fontSize: 13.5 }}>
                            {e.delegateName || t("General")}
                            {e.status === "acknowledged" && (
                              <span className="muted" style={{ fontWeight: 400, fontSize: 11.5 }}> · {t("Acknowledged")}</span>
                            )}
                          </div>
                          <div className="muted" style={{ fontSize: 11.5 }}>
                            {e.message} {e.createdBy ? `(${t("by")} ${e.createdBy})` : ""}
                          </div>
                          {e.delegatePhone && <div className="muted" style={{ fontSize: 11.5 }}>{e.delegatePhone}</div>}
                          {e.delegateLocation && <div className="muted" style={{ fontSize: 11.5 }}>{e.delegateLocation}</div>}
                        </div>
                        <div className="row" style={{ gap: 6, flexShrink: 0 }}>
                          {e.status === "open" && (
                            <button className="btn btn-ghost" style={{ fontSize: 11.5, padding: "4px 8px" }}
                              disabled={escalationBusyId === e.id} onClick={() => acknowledgeEscalationRow(e.id)}>
                              {t("Acknowledge")}
                            </button>
                          )}
                          <button className="btn btn-ghost" style={{ fontSize: 11.5, padding: "4px 8px" }}
                            disabled={escalationBusyId === e.id} onClick={() => resolveEscalationRow(e.id, e.delegateName)}>
                            {t("Resolve")}
                          </button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
                )}
                {!showAllEscalations && filtered.length > 5 && (
                  <button className="btn btn-ghost" style={{ fontSize: 12.5, marginTop: 8 }} onClick={() => setShowAllEscalations(true)}>
                    {t("Show")} {filtered.length - 5} {t("more")}
                  </button>
                )}
              </div>
              );
            })()}

            {missingNotEscalated.length > 0 && (
              <div style={{ marginBottom: (lateDelegates.length || cancelledDelegates.length) ? 18 : 0 }}>
                <div className="row between" style={{ marginBottom: 8 }}>
                  <div className="row" style={{ gap: 6, color: "var(--st-missing)", fontWeight: 700, fontSize: 13.5 }}>
                    <AlertTriangle size={15} /> {missingNotEscalated.length} {t("Missing")}
                  </div>
                  <button className="btn btn-ghost" style={{ fontSize: 12, padding: "3px 8px" }} onClick={() => { setAlertsOpen(false); showDelegatesFiltered("MISSING"); }}>
                    {t("View all")}
                  </button>
                </div>
                <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                  {missingNotEscalated.slice(0, 5).map((m) => (
                    <div
                      key={m.id}
                      className="row between"
                      style={{ padding: "8px 10px", background: "var(--st-missing-bg)", borderRadius: "var(--r-sm)", cursor: "pointer" }}
                      onClick={() => { setAlertsOpen(false); openProfile(m); }}
                    >
                      <div className="row" style={{ gap: 8, minWidth: 0 }}>
                        <DelegateAvatar delegate={m} />
                        <div style={{ minWidth: 0 }}>
                          <div style={{ fontWeight: 600, fontSize: 13.5, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{m.name}</div>
                          <div className="muted" style={{ fontSize: 11.5, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                            {m.lastLocation || t("Last known location")}
                          </div>
                        </div>
                      </div>
                      <div className="row" style={{ gap: 4, flexShrink: 0 }}>
                        {m.phone && (
                          <a
                            href={`tel:${m.phone}`}
                            onClick={(e) => e.stopPropagation()}
                            aria-label={`${t("Call")} — ${m.name}`}
                            style={{ ...S.iconBtn, color: "var(--st-missing)", textDecoration: "none" }}
                          >
                            <Phone size={15} />
                          </a>
                        )}
                        <button
                          onClick={(e) => { e.stopPropagation(); openEscalate(m); }}
                          aria-label={`${t("Escalate to office")} — ${m.name}`}
                          title={t("Escalate to office")}
                          style={{ ...S.iconBtn, color: "var(--st-missing)" }}
                        >
                          <Siren size={15} />
                        </button>
                      </div>
                    </div>
                  ))}
                  {missingNotEscalated.length > 5 && (
                    <button className="btn btn-ghost" style={{ fontSize: 12.5, alignSelf: "flex-start" }} onClick={() => { setAlertsOpen(false); showDelegatesFiltered("MISSING"); }}>
                      {t("Show")} {missingNotEscalated.length - 5} {t("more")}
                    </button>
                  )}
                </div>
              </div>
            )}

            {lateDelegates.length > 0 && (
              <div style={{ marginBottom: cancelledDelegates.length ? 18 : 0 }}>
                <div className="row between" style={{ marginBottom: 8 }}>
                  <div className="row" style={{ gap: 6, color: "var(--st-late)", fontWeight: 700, fontSize: 13.5 }}>
                    <Clock size={15} /> {lateDelegates.length} {t("Late")}
                  </div>
                  <button className="btn btn-ghost" style={{ fontSize: 12, padding: "3px 8px" }} onClick={() => { setAlertsOpen(false); showDelegatesFiltered("LATE"); }}>
                    {t("View all")}
                  </button>
                </div>
                <div className="row" style={{ gap: 6, flexWrap: "wrap" }}>
                  {lateDelegates.slice(0, 12).map((d) => (
                    <span key={d.id} className="badge badge-late" style={{ cursor: "pointer" }} onClick={() => { setAlertsOpen(false); openProfile(d); }}>
                      {d.name}
                    </span>
                  ))}
                  {lateDelegates.length > 12 && (
                    <span className="muted" style={{ fontSize: 12, alignSelf: "center" }}>+{lateDelegates.length - 12} {t("more")}</span>
                  )}
                </div>
              </div>
            )}

            {cancelledDelegates.length > 0 && (
              <div>
                <div className="row between" style={{ marginBottom: 8 }}>
                  <div className="row" style={{ gap: 6, color: "var(--ink-2)", fontWeight: 700, fontSize: 13.5 }}>
                    <Ban size={15} /> {cancelledDelegates.length} {t("Cancelled")}
                  </div>
                  <button className="btn btn-ghost" style={{ fontSize: 12, padding: "3px 8px" }} onClick={() => { setAlertsOpen(false); showDelegatesFiltered("CANCELLED"); }}>
                    {t("View all")}
                  </button>
                </div>
                <div className="row" style={{ gap: 6, flexWrap: "wrap" }}>
                  {cancelledDelegates.slice(0, 12).map((d) => (
                    <span
                      key={d.id}
                      className="badge badge-neutral"
                      style={{ cursor: "pointer" }}
                      title={d.cancel_reason || undefined}
                      onClick={() => { setAlertsOpen(false); openProfile(d); }}
                    >
                      {d.name}
                    </span>
                  ))}
                  {cancelledDelegates.length > 12 && (
                    <span className="muted" style={{ fontSize: 12, alignSelf: "center" }}>+{cancelledDelegates.length - 12} {t("more")}</span>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {escalatingDelegate && (
        <div style={{ ...S.overlay, zIndex: 60 }}
          onMouseDown={(e) => { downOnBackdrop.current = e.target === e.currentTarget; }}
          onClick={(e) => { if (downOnBackdrop.current && e.target === e.currentTarget) setEscalatingDelegate(null); }}>
          <div className="card" style={{ ...S.modal, width: "min(420px, 100%)" }} onClick={(e) => e.stopPropagation()}>
            <div className="row between" style={{ marginBottom: 4 }}>
              <div className="row" style={{ gap: 8, color: "var(--st-missing)" }}>
                <Siren size={18} />
                <h2 style={{ fontSize: 16 }}>{t("Escalate to office")}</h2>
              </div>
              <button onClick={() => setEscalatingDelegate(null)} style={S.iconBtn} aria-label={t("Close")}><X size={18} /></button>
            </div>
            <p className="muted" style={{ fontSize: 13, marginTop: 6, marginBottom: 14 }}>
              {t("This alerts offsite admin/office staff right away — for when a Missing delegate isn't answering their phone.")} <strong>{escalatingDelegate.name}</strong>
            </p>
            <label className="field-label">{t("What's happening?")}</label>
            <textarea
              className="input"
              rows={3}
              style={{ marginTop: 4, resize: "vertical" }}
              value={escalateMessage}
              onChange={(e) => setEscalateMessage(e.target.value)}
            />

            <label className="field-label" style={{ marginTop: 14 }}>{t("Alert who?")}</label>
            {escalateRecipients.length === 0 ? (
              <div className="muted" style={{ fontSize: 12.5, marginTop: 4 }}>
                {t("No admin accounts have an email on file yet — add one in Account Control to alert someone by email.")}
              </div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 6, maxHeight: 150, overflowY: "auto" }}>
                {escalateRecipients.map((p) => (
                  <label key={p.email} className="row" style={{ gap: 8, fontSize: 13, cursor: "pointer" }}>
                    <input
                      type="checkbox"
                      checked={escalateSelected.has(p.email)}
                      onChange={() => toggleEscalateRecipient(p.email)}
                    />
                    <span style={{ fontWeight: 600 }}>{p.name || p.username}</span>
                    <span className="muted">{p.email}</span>
                    {p.isTripLead && <span className="badge badge-review" style={{ padding: "1px 7px", fontSize: 10.5 }}>{t("Trip lead")}</span>}
                  </label>
                ))}
              </div>
            )}

            <p className="muted" style={{ fontSize: 11.5, marginTop: 10 }}>
              {t("Emails can sometimes land in the recipient's Spam folder — ask them to check there and mark it \"Not spam\" the first time.")}
            </p>

            {escalateErr && <div style={{ color: "var(--st-missing)", fontSize: 12.5, marginTop: 10 }}>{escalateErr}</div>}
            <div className="row" style={{ gap: 10, marginTop: 16, justifyContent: "flex-end" }}>
              <button className="btn btn-ghost" onClick={() => setEscalatingDelegate(null)} disabled={escalateSaving}>{t("Cancel")}</button>
              <button
                className="btn btn-primary"
                style={{ background: "var(--st-missing)", borderColor: "var(--st-missing)" }}
                onClick={submitEscalation}
                disabled={escalateSaving}
              >
                <Siren size={15} /> {escalateSaving ? t("Sending…") : t("Escalate now")}
              </button>
            </div>
          </div>
        </div>
      )}

      {cancelPrompt && (
        <div style={{ ...S.overlay, zIndex: 60 }}
          onMouseDown={(e) => { downOnBackdrop.current = e.target === e.currentTarget; }}
          onClick={(e) => { if (downOnBackdrop.current && e.target === e.currentTarget) setCancelPrompt(null); }}>
          <div className="card" style={{ ...S.modal, width: "min(420px, 100%)" }} onClick={(e) => e.stopPropagation()}>
            <div className="row between" style={{ marginBottom: 14 }}>
              <h2 style={{ fontSize: 16 }}>{t("Mark as cancelled")}</h2>
              <button onClick={() => setCancelPrompt(null)} style={S.iconBtn} aria-label={t("Close")}><X size={18} /></button>
            </div>
            <p className="muted" style={{ fontSize: 13, marginTop: 0 }}>
              {lang === "zh"
                ? `将 ${cancelPrompt.delegate.name} 标记为已取消？`
                : `Mark ${cancelPrompt.delegate.name} as cancelled?`}
            </p>
            <label className="field-label">{t("What happened?")}</label>
            <textarea className="input" rows={3} style={{ resize: "vertical", fontFamily: "inherit" }}
              autoFocus
              placeholder={t("e.g. Flight cancelled, called in sick, no longer travelling with the group…")}
              value={cancelPrompt.reason}
              onChange={(e) => setCancelPrompt((p) => ({ ...p, reason: e.target.value }))} />
            <div className="row" style={{ gap: 10, marginTop: 18, justifyContent: "flex-end" }}>
              <button className="btn btn-ghost" onClick={() => setCancelPrompt(null)}>{t("Cancel")}</button>
              <button className="btn btn-primary" onClick={confirmCancel}>{t("Mark as cancelled")}</button>
            </div>
          </div>
        </div>
      )}

      {enlargedPhoto && (
        <div
          style={{ ...S.overlay, zIndex: 60, background: "rgba(0,0,0,0.75)" }}
          onClick={() => setEnlargedPhoto(null)}
        >
          <button
            onClick={() => setEnlargedPhoto(null)}
            aria-label={t("Close")}
            style={{ position: "absolute", top: 20, right: 20, background: "rgba(255,255,255,0.1)", border: "none", borderRadius: "50%", padding: 8, color: "#fff", cursor: "pointer", display: "flex" }}
          >
            <X size={22} />
          </button>
          <img
            src={enlargedPhoto}
            alt=""
            style={{ maxWidth: "min(90vw, 640px)", maxHeight: "85vh", borderRadius: 12, objectFit: "contain", boxShadow: "0 12px 40px rgba(0,0,0,0.5)" }}
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}

      {mapDelegate && (
        <div style={S.overlay}
          onMouseDown={(e) => { downOnBackdrop.current = e.target === e.currentTarget; }}
          onClick={(e) => { if (downOnBackdrop.current && e.target === e.currentTarget) setMapDelegate(null); }}>
          <div className="card" style={{ ...S.modal, width: "min(480px, 100%)" }} onClick={(e) => e.stopPropagation()}>
            <div className="row between" style={{ marginBottom: 14 }}>
              <div>
                <h2 style={{ fontSize: 16 }}>{mapDelegate.name}</h2>
                <p className="muted" style={{ fontSize: 12, marginTop: 2 }}>{mapDelegate.lastLocation}</p>
              </div>
              <button onClick={() => setMapDelegate(null)} style={S.iconBtn} aria-label={t("Close")}>
                <X size={18} />
              </button>
            </div>
            {mapDelegate.lastLocation ? (
              <DelegateLocationMap location={mapDelegate.lastLocation} height={280} />
            ) : (
              <div className="muted" style={{ fontSize: 13, padding: "12px 0" }}>
                {t("No location has been recorded for this delegate yet.")}
              </div>
            )}
          </div>
        </div>
      )}

      <style>{`.spin{animation:mg-spin 0.9s linear infinite}@keyframes mg-spin{to{transform:rotate(360deg)}}
        /* 4 equal columns at a fixed width, not auto-fit — auto-fit's minmax
           boundaries produce an uneven trailing gap/card width depending on
           exactly how many columns fit, which is what read as "unaligned".
           Explicit breakpoints instead of a fluid track keep every card the
           same size as its row-mates at every width. */
        .kpi-row{display:grid;grid-template-columns:1fr 1fr 2fr;gap:16px;margin-top:22px;align-items:stretch}
        .kpi-row > *{min-height:132px}
        @media (max-width:960px){.kpi-row{grid-template-columns:1fr 1fr;}.kpi-row > :last-child{grid-column:1 / -1}}
        @media (max-width:560px){.kpi-row{grid-template-columns:1fr}.kpi-row > :last-child{grid-column:auto}}
        .roster-bar{display:flex;height:8px;border-radius:999px;overflow:hidden;background:var(--surface-2);border:1px solid var(--line);box-sizing:border-box}
        .roster-bar > span{height:100%}
        .roster-stats{display:flex;gap:8px;margin-top:14px;flex:1}
        .roster-stat{flex:1;display:flex;flex-direction:column;gap:2px;padding:10px 14px;border:1px solid var(--line);border-radius:var(--r-sm);background:none;cursor:pointer;text-align:left;transition:box-shadow .15s ease,border-color .15s ease,transform .15s ease}
        .roster-stat:hover{box-shadow:var(--shadow-md);border-color:var(--roster-tone);transform:translateY(-1px)}
        .roster-stat:focus-visible{outline:2px solid var(--roster-tone);outline-offset:2px}
        .kpi-clickable{transition:box-shadow .15s ease,border-color .15s ease,transform .15s ease}
        /* Hover/focus color now matches each card's OWN status tone (--kpi-tone,
           set inline per card) instead of a hardcoded var(--st-normal) — that
           hardcode was a leftover from when this hover style was written for
           the old single purple "Open exceptions" tile, so every OTHER card
           (including Late) inherited that same purple on hover regardless of
           its actual color. */
        .kpi-clickable:hover{box-shadow:var(--shadow-md);border-color:var(--kpi-tone);transform:translateY(-1px)}
        .kpi-clickable:focus-visible{outline:2px solid var(--kpi-tone);outline-offset:2px}`}</style>
    </div>
  );
}

/* ---- "Synced" badge (2026-07-30 — "why is it moving up and down?", then
 * "the sec is affecting the itinerary placement, remove it"). This used to
 * tick a live "Ns" countdown once a second, which was first isolated into
 * its own component so only the badge (not the whole Dashboard) re-rendered
 * each tick — but the countdown text's changing width ("10s" -> "9s" -> ...)
 * still reflowed the itinerary chip sitting right below it in the header
 * row. The countdown wasn't load-bearing information, so it's gone entirely
 * now: a plain static badge, no interval, no per-second re-render, no
 * reflow. */
function LiveSyncBadge({ seconds, t, dotStyle }) {
  return (
    <span className="badge badge-present" title={t(`Auto-refreshes every ${seconds} seconds`)}>
      <span style={dotStyle} /> {t("Synced")}
    </span>
  );
}

/* ---- Trip switcher (2026-07-30 — "fix the button color for dark theme
 * mode" / "i don't like the hover effect, color"). This USED to be a native
 * <select> laid invisibly over the styled title text (kept for its built-in
 * keyboard handling and native dropdown) — but a native <option> list's
 * hover/highlight colors are drawn by the OS, not by our CSS, and in dark
 * theme that OS highlight came out dark-on-dark — genuinely unreadable, not
 * something author CSS can reliably fix cross-browser. Rebuilt as a real,
 * fully-styled dropdown (a button + our own absolutely-positioned menu) so
 * every pixel — including the hover state — uses this app's own theme
 * tokens (`--surface-2`, the same hover fill every other menu/nav item in
 * the app already uses) instead of the browser's native option styling. */
function TripSwitcher({ trip, tripOptions, selectedTripId, t, onPick }) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef(null);

  useEffect(() => {
    if (!open) return;
    function onDocClick(e) { if (rootRef.current && !rootRef.current.contains(e.target)) setOpen(false); }
    function onKeyDown(e) { if (e.key === "Escape") setOpen(false); }
    document.addEventListener("mousedown", onDocClick);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("mousedown", onDocClick);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [open]);

  return (
    <span className="mg-title-switch" ref={rootRef}>
      <button
        type="button"
        className="mg-title-switch-btn"
        onClick={() => setOpen((v) => !v)}
        title={t("Switch trip")}
        aria-label={t("Switch trip")}
        aria-expanded={open}
      >
        <span className="mg-title-name">
          {trip ? `${trip.name}${trip.countryTo ? ` (${trip.countryTo})` : ""}` : t("Dashboard")}
        </span>
        <ChevronDown size={20} strokeWidth={2.5} aria-hidden="true" />
      </button>
      {open && (
        <div className="mg-title-menu" role="listbox">
          {tripOptions.map((tr) => (
            <button
              key={tr.id}
              type="button"
              role="option"
              aria-selected={tr.id === selectedTripId}
              className={"mg-title-menu-item" + (tr.id === selectedTripId ? " active" : "")}
              onClick={() => { onPick(tr.id); setOpen(false); }}
            >
              {tr.name}
            </button>
          ))}
        </div>
      )}
    </span>
  );
}

/* ---- Small progress ring — the KPI tiles' only visual data accent beyond
 * plain numbers (2026-07-24, "the Overview tab feels plain" feedback). Pure
 * SVG, no charting library — this is small enough not to warrant pulling
 * AnalyticsPanel's recharts dependency into every page load. */
function ProgressRing({ value, total, tone, size = 34, strokeWidth = 4 }) {
  const pct = total > 0 ? Math.min(1, value / total) : 0;
  const r = (size - strokeWidth) / 2;
  const c = 2 * Math.PI * r;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ flexShrink: 0 }}>
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="var(--line)" strokeWidth={strokeWidth} />
      {pct > 0 && (
        <circle
          cx={size / 2} cy={size / 2} r={r} fill="none" stroke={`var(--st-${tone})`} strokeWidth={strokeWidth}
          strokeDasharray={c} strokeDashoffset={c * (1 - pct)} strokeLinecap="round"
          transform={`rotate(-90 ${size / 2} ${size / 2})`}
        />
      )}
    </svg>
  );
}

/* ---- KPI tile ----------------------------------------------------------- */
function Kpi({ tone, icon: Icon, label, value, suffix, foot, big, onClick, ringValue, ringTotal }) {
  const clickable = !!onClick;
  const showRing = ringValue != null && ringTotal > 0;
  return (
    <div
      className={"card" + (clickable ? " kpi-clickable" : "")}
      onClick={onClick}
      role={clickable ? "button" : undefined}
      tabIndex={clickable ? 0 : undefined}
      onKeyDown={clickable ? (e) => (e.key === "Enter" || e.key === " ") && (e.preventDefault(), onClick()) : undefined}
      style={{
        padding: 20, display: "flex", flexDirection: "column", gap: 10, cursor: clickable ? "pointer" : undefined,
        "--kpi-tone": `var(--st-${tone})`,
      }}
    >
      <div className="row between">
        <span className="page-eyebrow" style={{ color: `var(--st-${tone})` }}>{label}</span>
        {showRing ? (
          <div style={{ position: "relative", width: 34, height: 34 }}>
            <ProgressRing value={ringValue} total={ringTotal} tone={tone} />
            <Icon size={14} color={`var(--st-${tone})`} style={{ position: "absolute", inset: 0, margin: "auto" }} />
          </div>
        ) : (
          <Icon size={18} color={`var(--st-${tone})`} />
        )}
      </div>
      <div className="row" style={{ alignItems: "baseline", gap: 8 }}>
        <span className="mono"
          style={{ fontSize: big ? 44 : 40, fontWeight: 700, color: `var(--st-${tone})`, lineHeight: 1 }}>
          {value}
        </span>
        {suffix && <span className="muted" style={{ fontSize: 16 }}>{suffix}</span>}
      </div>
      {foot && <div className="muted" style={{ fontSize: 13 }}>{foot}</div>}
    </div>
  );
}

/* ---- Roster breakdown card -----------------------------------------------
 * Folds Arrived / Assigned / Unassigned into one card: a proportional stacked
 * bar (share of the roster in each status) plus 3 compact clickable stats —
 * the calmer counts don't need a full KPI tile each like Missing/Late do. */
function RosterCard({ t, k, onFilter }) {
  const segments = [
    { tone: "present", value: k.present },
    { tone: "assigned", value: k.assigned ?? 0 },
    { tone: "unassigned", value: k.unassigned },
  ];
  // Percentages are relative to the sum of the 3 segments actually drawn
  // here (not k.total) — Missing/Late already have their own tiles and
  // aren't represented in this bar, so using k.total left an unexplained
  // blank gap at the end instead of the bar reading as "the whole thing".
  const total = Math.max(segments.reduce((sum, s) => sum + s.value, 0), 1);

  return (
    <div className="card" style={{ padding: 20, display: "flex", flexDirection: "column" }}>
      <span className="page-eyebrow" style={{ color: "var(--ink-3)" }}>{t("Roster breakdown")}</span>
      <div className="roster-bar" style={{ marginTop: 12 }}>
        {segments.map((s) => s.value > 0 && (
          <span key={s.tone} style={{ width: `${(s.value / total) * 100}%`, background: `var(--st-${s.tone})` }} />
        ))}
      </div>
      <div className="roster-stats">
        <RosterStat tone="present" icon={UserCheck} label={t("Arrived")} value={k.present} onClick={() => onFilter("ARRIVED")} />
        <RosterStat tone="assigned" icon={Users} label={t("Assigned")} value={k.assigned ?? 0} onClick={() => onFilter("ASSIGNED")} />
        <RosterStat tone="unassigned" icon={HelpCircle} label={t("Unassigned")} value={k.unassigned} onClick={() => onFilter("UNASSIGNED")} />
      </div>
    </div>
  );
}

function RosterStat({ tone, icon: Icon, label, value, onClick }) {
  return (
    <button className="roster-stat" onClick={onClick} style={{ "--roster-tone": `var(--st-${tone})` }}>
      <span className="row" style={{ gap: 6, color: `var(--st-${tone})` }}>
        <Icon size={14} />
        <span className="muted" style={{ fontSize: 12.5, color: "var(--ink-2)" }}>{label}</span>
      </span>
      <span className="mono" style={{ fontSize: 24, fontWeight: 700, color: `var(--st-${tone})`, lineHeight: 1.2 }}>{value}</span>
    </button>
  );
}

/* ---- Coach display helpers ----------------------------------------------
 * Coaches added outside the original seed may have no city, or a long label
 * ("Coach 5" instead of "C5") — never render "null" or overflow the avatar.
 * ------------------------------------------------------------------------- */
function coachDisplayName(c) {
  return [c.name, c.city].filter(Boolean).join(" · ");
}

function coachShortLabel(c) {
  if (c.label && c.label.length <= 3) return c.label;
  const num = String(c.label || c.name || "").match(/\d+/);
  return num ? `C${num[0]}` : String(c.label || c.name || "?").slice(0, 2).toUpperCase();
}

/** Format a delegate's upload timestamp (createdAt) as e.g. "12 Jul, 14:30".
 *  Older rows created before the column existed still get the migration time,
 *  so this only shows "—" if the value is genuinely missing/unparseable. */
// Display-only 12h formatting for checkpoint scheduledTime (2026-07-30 —
// "do the same for these"). scheduledTime is a raw 24h "HH:MM" string from
// the checkpoints API; nothing here sorts or compares it, so this only
// prettifies what actually gets printed. Same one-line helper as
// TripCoachPage.jsx/MobileTripsPage.jsx — kept local per this codebase's
// existing per-file small-helper pattern rather than a shared import.
function fmt12h(hhmm) {
  if (!hhmm) return hhmm;
  const [h, m] = String(hhmm).split(":").map(Number);
  if (Number.isNaN(h) || Number.isNaN(m)) return hhmm;
  const period = h >= 12 ? "PM" : "AM";
  return `${h % 12 || 12}:${String(m).padStart(2, "0")} ${period}`;
}
// trip.departsIn ("04:53") is a COUNTDOWN duration, not a clock time — running
// it through fmt12h would print the nonsensical "4:53 AM" for "4 hours 53
// minutes from now". This reformats it as a duration instead ("4h 53m"),
// fixing the same "looks like raw 24h military time" complaint honestly.
// Only reached as a fallback now, for a trip with no departureTime/startDate
// set yet — see liveDepartsIn() below, which is preferred whenever the
// backend can compute a real departureAt.
function fmtDepartsIn(hhmm) {
  if (!hhmm) return hhmm;
  const [h, m] = String(hhmm).split(":").map(Number);
  if (Number.isNaN(h) || Number.isNaN(m)) return hhmm;
  if (h && m) return `${h}h ${m}m`;
  if (h) return `${h}h`;
  return `${m}m`;
}
// Genuine live countdown (2026-07-30 — "i see this one nvr change, is it
// static?" — it was: trip.departsIn was a hardcoded seed string that never
// moved). trip.departureAt is a real absolute instant computed server-side
// from startDate + totalDays + the new departureTime field (getTrip(),
// db/dashboard.js) — recomputing the diff against "right now" on every render
// is what makes this actually tick down, unlike the old static string. Called
// from render, not stored in state — it piggybacks on nowClock's existing 15s
// re-render tick rather than running its own second timer for one more field.
// Returns null once departure has passed, so the chip disappears instead of
// showing a stale "0h -3m".
function liveDepartsIn(departureAtIso) {
  if (!departureAtIso) return null;
  const diffMs = new Date(departureAtIso).getTime() - Date.now();
  if (!(diffMs > 0)) return null;
  const totalMin = Math.round(diffMs / 60000);
  const h = Math.floor(totalMin / 60), m = totalMin % 60;
  if (h && m) return `${h}h ${m}m`;
  if (h) return `${h}h`;
  return `${m}m`;
}

function fmtUploadDate(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d)) return "—";
  return d.toLocaleString([], { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" });
}

/** "Staff operations" active-sessions relative time, e.g. "15s ago" / "2m ago". */
function staffOpsTimeAgo(iso, t) {
  if (!iso) return "";
  const secs = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 1000));
  if (secs < 10) return t("just now");
  if (secs < 60) return `${secs}${t("s ago")}`;
  return `${Math.round(secs / 60)}${t("m ago")}`;
}

/* ---- Coach progress bar -------------------------------------------------
 * When onOpen is provided the whole row is clickable and navigates to that
 * trip's board on the Trips (Desmond) page.
 * ------------------------------------------------------------------------- */
// Composition bar (boarded/late/missing against capacity) — a SINGLE div
// painted with a hard-stop CSS gradient, not multiple flex children. One box
// means one height, guaranteed identical every time (no cross-browser flex-
// child-height edge cases), and the track's own border-radius/overflow:hidden
// naturally rounds both ends with no per-segment corner logic needed. Used by
// both the Coach status card (CoachBar below) and the Reverse headcount
// modal, so both show the same composition the same way (2026-07-24 —
// previously a single flat red-or-green fill in both places, so two coaches
// both "in trouble" looked identical whether one was mostly Late or mostly
// Missing).

// Same flat, solid-block flex-bar as RosterCard's "Roster breakdown" bar
// (2026-07-24 — "you can look at roster breakdown, that look much
// cleaner") — plain `<span>` children sized by width%, no gradient/gap/
// minimum-width tricks. Percentages are relative to the coach's total seat
// capacity (not just the sum of these 3 segments), so the un-rendered
// remainder is genuinely "still to board", shown via the container's own
// background rather than an explicit 4th segment.
function coachBarSegments(coach, { includeBoarded = true } = {}) {
  const cap = coach.capacity || Math.max(coach.total || 0, 1);
  const segs = [
    ...(includeBoarded ? [{ n: coach.boarded || 0, tone: "present" }] : []),
    { n: coach.late || 0, tone: "late" },
    { n: coach.missing || 0, tone: "missing" },
  ]
    .map((s) => ({ ...s, pct: Math.max(0, Math.round((s.n / cap) * 100)) }))
    .filter((s) => s.pct > 0);
  // Rounding each % independently can sum to just over 100 (e.g. 34+33+34) —
  // shave the excess off the last segment so it never overflows the bar.
  const totalPct = segs.reduce((sum, s) => sum + s.pct, 0);
  if (totalPct > 100) segs[segs.length - 1].pct = Math.max(0, segs[segs.length - 1].pct - (totalPct - 100));
  return segs;
}

function CoachBar({ coach, onOpen }) {
  const { t } = useLang();
  // Simplified two-state headline (per request): a coach is "Missing" if it
  // holds ANYONE not yet accounted for — LATE is folded in with MISSING, no
  // separate Late badge — and "Arrived" only when everyone assigned has
  // actually boarded. `attention` is that combined not-here count.
  const attention = (coach.missing || 0) + (coach.late || 0);
  const allArrived = coach.total > 0 && attention === 0 && coach.boarded === coach.total;
  const BAR_H = 8;
  const segs = coachBarSegments(coach);
  const clickable = !!onOpen;
  return (
    <div
      onClick={onOpen}
      role={clickable ? "button" : undefined}
      title={clickable ? t("Open in Trips board") : undefined}
      style={clickable ? { cursor: "pointer", borderRadius: "var(--r-sm)", padding: 6, margin: -6 } : undefined}
      className={clickable ? "coach-row" : undefined}
    >
      <div className="row between" style={{ marginBottom: 6 }}>
        <div className="row" style={{ gap: 10 }}>
          <span className="avatar" style={{ background: "var(--st-neutral-bg)", color: "var(--ink-2)" }}>
            {coachShortLabel(coach)}
          </span>
          <span style={{ fontWeight: 500, fontSize: 14 }}>{coachDisplayName(coach)}</span>
        </div>
        <div className="row" style={{ gap: 6 }}>
          {attention > 0 ? (
            <span className="badge badge-missing">{attention} {t("not boarded")}</span>
          ) : allArrived ? (
            <span className="badge badge-present">{t("Arrived")}</span>
          ) : coach.total > 0 ? (
            <span className="badge badge-neutral">{coach.total - coach.boarded} {t("to board")}</span>
          ) : (
            <span className="badge badge-neutral">{t("Empty")}</span>
          )}
          {clickable && <ChevronRight size={16} className="muted" />}
        </div>
      </div>
      <div className="roster-bar" style={{ height: BAR_H }}>
        {segs.map((s, i) => <span key={i} style={{ width: `${s.pct}%`, background: `var(--st-${s.tone})` }} />)}
      </div>
      <div className="muted mono" style={{ fontSize: 12, marginTop: 4 }}>
        {coach.boarded}/{coach.capacity} {t("boarded")}
        {coach.late > 0 && <> · <span style={{ color: "var(--st-late)" }}>{coach.late} {t("late")}</span></>}
        {coach.missing > 0 && <> · <span style={{ color: "var(--st-missing)" }}>{coach.missing} {t("missing")}</span></>}
      </div>
    </div>
  );
}

/** Activity text comes from the backend as plain English ("Lim added",
 *  "All delegates removed (3)"), since it's stored as-is in the log. Rebuild
 *  it with the translated verb rather than adding a whole new API shape. */
function translateActivityText(text, t) {
  const allMatch = text.match(/^All delegates removed \((\d+)\)$/);
  if (allMatch) return `${t("All delegates removed")} (${allMatch[1]})`;
  const verbMatch = text.match(/^(.*) (added|updated|removed)$/);
  if (verbMatch) return `${verbMatch[1]} ${t(verbMatch[2])}`;
  return text;
}

function activityColor(kind) {
  if (kind === "exception") return "var(--st-missing)";
  if (kind === "reassign") return "var(--st-unassigned)";
  // 2026-07-27 — escalations now log here too (see routes/escalations.js).
  if (kind === "escalation") return "var(--st-missing)";
  return "var(--st-present)";
}

// One labelled value in the delegate profile panel — skips rendering
// entirely when there's nothing to show, so an incomplete profile doesn't
// leave a grid of empty "—" rows (2026-07-24). `action` renders a small
// icon button (e.g. Call) beside the value instead of making the value
// itself a clickable link — a plain phone number that's secretly a tel:
// link reads as an odd, unlabeled focus outline (2026-07-24 feedback).
function ProfileField({ icon: Icon, label, value, action, mono }) {
  if (!value) return null;
  return (
    <div>
      <div className="muted" style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 12, marginBottom: 2 }}>
        {Icon && <Icon size={12} />} {label}
      </div>
      <div className="row" style={{ gap: 8, alignItems: "center" }}>
        <span className={mono ? "mono" : undefined} style={{ fontSize: 14, fontWeight: 500 }}>{value}</span>
        {action}
      </div>
    </div>
  );
}

/**
 * Room Management tab (2026-07-26) — hotel/room quick-edit across the whole
 * roster, e.g. an end-of-day pass reassigning rooms. Reuses the SAME
 * `delegates` list the Delegate tab already has (no separate fetch) — edits
 * are per-row, local until "Save" is clicked for that row, so switching away
 * mid-edit never half-saves anything.
 */
// Bumps a room number's trailing digits by `delta`, preserving any prefix
// and zero-padding (e.g. "12A" -> "13A", "05" -> "06") — room numbers are
// free text (some trips prefix a block letter), not a plain integer, so a
// naive Number(value)+1 would break on anything non-numeric.
function bumpRoomNumber(value, delta) {
  const str = String(value ?? "");
  const m = str.match(/^(.*?)(\d+)(\D*)$/);
  if (!m) return delta > 0 ? `${str}1` : str; // nothing to decrement from
  const [, prefix, digits, suffix] = m;
  const next = Math.max(0, parseInt(digits, 10) + delta);
  return prefix + String(next).padStart(digits.length, "0") + suffix;
}

function RoomManagementTab({ delegates, coaches, coachName, onSaved, t, lang, tripId }) {
  const [query, setQuery] = useState("");
  const [coachFilter, setCoachFilter] = useState("ALL"); // ALL | <coachId>
  const [sortMode, setSortMode] = useState("name"); // name | coach | room
  const [edits, setEdits] = useState({}); // { [delegateId]: { hotelName, roomNumber } }
  const [savingId, setSavingId] = useState(null);
  // AI room assignment (2026-07-27 — "add like an ai feature so either i can
  // type it out and it will update the delegate room status, but give user
  // the confirmation before update the changes") — "Suggest" only ever
  // merges into `edits` (the SAME pending-edit state a manual keystroke
  // produces), never writes directly. That reuses every existing dirty-row/
  // Save affordance for free, so the human still has to explicitly click
  // Save (or "Save all suggested" below) before anything is persisted —
  // matching the "give user confirmation before update" requirement exactly.
  const [aiRequest, setAiRequest] = useState("");
  const [aiBusy, setAiBusy] = useState(false);
  const [aiErr, setAiErr] = useState(null);
  const [aiSuggestedIds, setAiSuggestedIds] = useState(new Set());
  const [savingAll, setSavingAll] = useState(false);
  // Pagination (2026-07-27 — "make sure to add something in all delegate
  // section, so when there alot of delegate") — mirrors the main "All
  // delegates" table's own Rows-per-page/Prev/Next pattern, own local state
  // since this is a separate component instance.
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(10);

  // Bulk "everyone's in the same hotel" assignment (2026-07-26 — "it should
  // reflect to all delegate because they should stay in the same hotel").
  // Deliberately overwrites EVERY delegate's hotel unconditionally (a
  // window.confirm gates it, same pattern as "Delete all" elsewhere on this
  // page) — the per-row inputs right below stay there for the special-case
  // delegate who's actually in a different hotel, edited AFTER the bulk set.
  const [bulkHotel, setBulkHotel] = useState("");
  const [bulkSaving, setBulkSaving] = useState(false);

  // Unassigned delegates aren't confirmed for this trip's coach/itinerary yet
  // (2026-07-26 — "if they are not assigned. they should not be going to
  // hotel") — exclude them from Room Management entirely, not just the
  // filter dropdown, so they never get swept into the bulk hotel-for-all
  // either.
  const roomable = delegates.filter((d) => d.coachId);

  function fieldFor(d) {
    return edits[d.id] || { hotelName: d.hotel_name || "", roomNumber: d.room_number || "" };
  }
  function setField(d, key, value) {
    setEdits((prev) => ({ ...prev, [d.id]: { ...fieldFor(d), [key]: value } }));
  }
  async function save(d) {
    const { hotelName, roomNumber } = fieldFor(d);
    setSavingId(d.id);
    try {
      await apiPatch(`/delegates/${d.id}`, { hotelName: hotelName.trim(), roomNumber: roomNumber.trim() });
      setEdits((prev) => { const next = { ...prev }; delete next[d.id]; return next; });
      setAiSuggestedIds((prev) => { if (!prev.has(d.id)) return prev; const next = new Set(prev); next.delete(d.id); return next; });
      onSaved();
    } catch {
      /* leave the local edit in place so nothing typed is lost — the row's
         "Save" stays clickable to retry */
    } finally {
      setSavingId(null);
    }
  }

  async function askAi() {
    const request = aiRequest.trim();
    if (!request) return;
    setAiBusy(true);
    setAiErr(null);
    try {
      const res = await apiPost(`/trips/${tripId}/rooms/ai-suggest`, { request });
      const suggestions = res.suggestions || [];
      if (suggestions.length === 0) {
        setAiErr(t("Nothing to suggest — try naming a delegate, hotel, or room number."));
        return;
      }
      // The local model often handles only the FIRST person in a multi-name
      // request (2026-07-28) — say so rather than letting it look complete.
      if (res.partial) {
        setAiErr(`${t("Only")} ${suggestions.length} ${t("of")} ${res.mentioned} ${t("delegates you named were matched — review below, then ask again for the rest (one person per request works best).")}`);
      }
      setEdits((prev) => {
        const next = { ...prev };
        for (const s of suggestions) next[s.delegateId] = { hotelName: s.hotelName, roomNumber: s.roomNumber };
        return next;
      });
      setAiSuggestedIds(new Set(suggestions.map((s) => s.delegateId)));
      setAiRequest("");
    } catch (e) {
      setAiErr(e.message || t("Could not reach the AI right now."));
    } finally {
      setAiBusy(false);
    }
  }

  async function saveAllSuggested() {
    const ids = [...aiSuggestedIds].filter((id) => edits[id]);
    if (ids.length === 0) return;
    setSavingAll(true);
    try {
      const updates = ids.map((id) => ({ delegateId: id, ...edits[id] }));
      await apiPost(`/trips/${tripId}/rooms/ai-apply`, { updates });
      setEdits((prev) => {
        const next = { ...prev };
        for (const id of ids) delete next[id];
        return next;
      });
      setAiSuggestedIds(new Set());
      onSaved();
    } catch {
      /* leave the pending edits in place so nothing typed is lost */
    } finally {
      setSavingAll(false);
    }
  }

  // General "save every pending edit at once" (2026-07-27 — "give me button
  // to save all instead of saving one by one") — covers manual keystrokes AND
  // AI suggestions alike, since both live in the same `edits` state. Reuses
  // the rooms/ai-apply endpoint (despite the name it's just a bulk
  // hotel/room write that re-validates every delegateId against the real
  // roster server-side) so this is ONE request, not N.
  async function saveAllEdits() {
    const ids = Object.keys(edits);
    if (ids.length === 0) return;
    setSavingAll(true);
    try {
      const updates = ids.map((id) => ({ delegateId: id, ...edits[id] }));
      await apiPost(`/trips/${tripId}/rooms/ai-apply`, { updates });
      setEdits({});
      setAiSuggestedIds(new Set());
      onSaved();
    } catch {
      /* leave the pending edits in place so nothing typed is lost */
    } finally {
      setSavingAll(false);
    }
  }

  /* Which delegates the bulk hotel applies to (2026-07-28 — "make it so if i
   * filter coach 1 it will apply to coach 1 delegate; if i filter to all coach
   * then apply to all"). Follows the COACH filter only, deliberately not the
   * search box: this button sits above the search row and reads as a
   * coach-level action, and silently narrowing it to whatever someone happened
   * to type would be a nasty surprise on a write that touches everyone. The
   * button label always names the exact target so there's nothing to guess. */
  const bulkTargets = coachFilter === "ALL" ? roomable : roomable.filter((d) => d.coachId === coachFilter);
  const bulkScopeLabel = coachFilter === "ALL" ? null : coachName(coachFilter);

  async function applyHotelToAll() {
    const name = bulkHotel.trim();
    if (!name || bulkTargets.length === 0) return;
    const n = bulkTargets.length;
    const msg = lang === "zh"
      ? (bulkScopeLabel
          ? `将 ${bulkScopeLabel} 的 ${n} 位代表的酒店设为 "${name}"？个别房间号不受影响，之后仍可单独修改。`
          : `将全部 ${n} 位（已分配教练的）代表的酒店设为 "${name}"？个别房间号不受影响，之后仍可单独修改。`)
      : (bulkScopeLabel
          ? `Set the hotel to "${name}" for the ${n} delegate${n === 1 ? "" : "s"} on ${bulkScopeLabel}? Room numbers are untouched — you can still edit individual delegates afterwards for a special case.`
          : `Set the hotel to "${name}" for all ${n} coach-assigned delegates? Room numbers are untouched — you can still edit individual delegates afterwards for a special case.`);
    if (!window.confirm(msg)) return;
    setBulkSaving(true);
    try {
      await Promise.all(bulkTargets.map((d) => apiPatch(`/delegates/${d.id}`, { hotelName: name, roomNumber: d.room_number || "" })));
      setBulkHotel("");
      setEdits({});
      onSaved();
    } finally {
      setBulkSaving(false);
    }
  }

  const filtered = roomable
    .filter((d) => !query.trim() || d.name.toLowerCase().includes(query.trim().toLowerCase()))
    .filter((d) => coachFilter === "ALL" || d.coachId === coachFilter)
    .sort((a, b) => {
      if (sortMode === "coach") return coachName(a.coachId).localeCompare(coachName(b.coachId)) || a.name.localeCompare(b.name);
      if (sortMode === "room") return (a.room_number || "￿").localeCompare(b.room_number || "￿") || a.name.localeCompare(b.name);
      return a.name.localeCompare(b.name);
    });

  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const clampedPage = Math.min(page, pageCount - 1);
  useEffect(() => { if (clampedPage !== page) setPage(clampedPage); }, [clampedPage, page]);
  useEffect(() => { setPage(0); }, [query, coachFilter, sortMode, pageSize]);
  const rowsShown = filtered.slice(clampedPage * pageSize, (clampedPage + 1) * pageSize);

  return (
    <div style={{ marginTop: 20 }}>
      <p className="page-sub" style={{ margin: "0 0 14px" }}>
        {t("Assign or reassign hotel/room per delegate — handy for an end-of-day pass.")}
      </p>

      {/* ---- AI room assignment (2026-07-27) -------------------------------
       * Bounded + transparent, same pattern as the Excel export's AI-filter:
       * "Suggest" only ever populates the pending-edit state below (the SAME
       * dirty-row/Save affordance a manual keystroke produces) — nothing is
       * written until a human clicks Save (per row, or "Save all suggested"
       * here), and every suggested delegateId is re-validated server-side
       * against the real roster before either the suggest OR apply step. */}
      <div className="card" style={{ padding: 14, marginBottom: 16 }}>
        <div className="row" style={{ gap: 10, alignItems: "center", flexWrap: "wrap" }}>
          <Sparkles size={16} color="var(--scc-red)" style={{ flexShrink: 0 }} />
          <span style={{ fontSize: 13, fontWeight: 600, flexShrink: 0 }}>{t("Ask AI to assign rooms")}</span>
          {/* A textarea, not a one-line input (2026-07-28 — "can you let me put
              in textbox instead of current one"): real requests run long ("Chen
              Hao Ming and Lim Hua into Grand Hyatt, rooms 401 and 402") and a
              single line hid most of what you'd typed. Enter still submits so
              the quick case stays quick; Shift+Enter adds a newline for
              multi-part instructions. */}
          <textarea
            className="input"
            rows={3}
            style={{ flex: "1 1 100%", fontSize: 13, resize: "vertical", minHeight: 62, lineHeight: 1.5, fontFamily: "inherit" }}
            placeholder={t("e.g. Put all VIPs in Grand Hyatt room 501 — Shift+Enter for a new line")}
            value={aiRequest} onChange={(e) => setAiRequest(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); if (!aiBusy && aiRequest.trim()) askAi(); }
            }}
          />
          <button className="btn btn-primary" style={{ fontSize: 12.5, padding: "6px 12px" }}
            onClick={askAi} disabled={aiBusy || !aiRequest.trim()}>
            {aiBusy ? t("Thinking…") : t("Suggest")}
          </button>
        </div>
        <p className="muted" style={{ fontSize: 11.5, marginTop: 8 }}>
          {t("This only fills in the fields below — nothing saves until you review and click Save.")}
        </p>
        {aiErr && <div style={{ color: "var(--st-missing)", fontSize: 12.5, marginTop: 6 }}>{aiErr}</div>}
        {aiSuggestedIds.size > 0 && (
          <div className="row between" style={{ marginTop: 10, padding: "8px 12px", background: "var(--st-assigned-bg)", borderRadius: "var(--r-sm)", flexWrap: "wrap", gap: 8 }}>
            <span style={{ fontSize: 12.5 }}>
              {t("AI suggested changes for")} {aiSuggestedIds.size} {aiSuggestedIds.size === 1 ? t("delegate") : t("delegates")} — {t("review the highlighted rows below")}.
            </span>
            <button className="btn btn-ghost" style={{ fontSize: 12, padding: "4px 10px" }} onClick={saveAllSuggested} disabled={savingAll}>
              {savingAll ? t("Saving…") : t("Save all suggested")}
            </button>
          </div>
        )}
      </div>

      {/* ---- Bulk "everyone's in this hotel" ------------------------------ */}
      <div className="card" style={{ padding: 14, marginBottom: 16, display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
        <BedDouble size={16} color="var(--ink-3)" style={{ flexShrink: 0 }} />
        <span style={{ fontSize: 13, fontWeight: 600, flexShrink: 0 }}>
          {bulkScopeLabel ? t("Set hotel for this coach") : t("Set hotel for everyone")}
        </span>
        <input
          className="input" style={{ maxWidth: 260, fontSize: 13 }}
          placeholder={t("e.g. Grand Hyatt")}
          value={bulkHotel} onChange={(e) => setBulkHotel(e.target.value)}
        />
        <button className="btn btn-primary" style={{ fontSize: 12.5, padding: "6px 12px" }}
          onClick={applyHotelToAll} disabled={bulkSaving || !bulkHotel.trim() || bulkTargets.length === 0}>
          {bulkSaving
            ? t("Applying…")
            : bulkScopeLabel
              ? `${t("Apply to")} ${bulkScopeLabel} (${bulkTargets.length})`
              : `${t("Apply to all")} ${bulkTargets.length}`}
        </button>
        <span className="muted" style={{ fontSize: 11.5, width: "100%" }}>
          {bulkScopeLabel
            ? `${t("Follows the coach filter — only the")} ${bulkTargets.length} ${t("delegate(s) on")} ${bulkScopeLabel} ${t("will change. Switch the filter to \"All coaches\" to apply trip-wide. Room numbers are untouched, and the search box doesn't affect this.")}`
            : t("Room numbers are untouched — edit individual rows below for a delegate in a different hotel. Filter to one coach to apply to just that coach. Delegates without a coach aren't shown here — they aren't confirmed for a hotel yet.")}
        </span>
      </div>

      {/* ---- Search / filter / sort ---------------------------------------- */}
      <div className="row" style={{ gap: 10, marginBottom: 14, flexWrap: "wrap" }}>
        <div style={{ position: "relative", maxWidth: 260, flex: "1 1 200px" }}>
          <Search size={15} style={{ position: "absolute", left: 10, top: "50%", transform: "translateY(-50%)", color: "var(--ink-3)" }} />
          <input className="input" style={{ paddingLeft: 32 }} placeholder={t("Search name…")}
            value={query} onChange={(e) => setQuery(e.target.value)} />
        </div>
        <select className="select" style={{ maxWidth: 190 }} value={coachFilter} onChange={(e) => setCoachFilter(e.target.value)}>
          <option value="ALL">{t("All coaches")}</option>
          <optgroup label={t("Coaches")}>
            {coaches.map((c) => (
              <option key={c.id} value={c.id}>{coachDisplayName(c)}</option>
            ))}
          </optgroup>
        </select>
        <select className="select" style={{ maxWidth: 160 }} value={sortMode} onChange={(e) => setSortMode(e.target.value)}>
          <option value="name">{t("Sort by name")}</option>
          <option value="coach">{t("Sort by coach")}</option>
          <option value="room">{t("Sort by room")}</option>
        </select>
      </div>

      {/* ---- Save-all bar (2026-07-27 — "give me button to save all instead
       * of saving one by one") — appears whenever ANY row has a pending edit,
       * manual or AI-suggested; the per-row Save buttons stay for saving just
       * one delegate while still deciding on the rest. */}
      {Object.keys(edits).length > 0 && (
        <div className="row between" style={{ marginBottom: 14, padding: "10px 14px", background: "var(--st-assigned-bg)", borderRadius: "var(--r-sm)", flexWrap: "wrap", gap: 8 }}>
          <span style={{ fontSize: 13 }}>
            {Object.keys(edits).length} {Object.keys(edits).length === 1 ? t("unsaved change") : t("unsaved changes")}
          </span>
          <div className="row" style={{ gap: 8 }}>
            {/* Discard (2026-07-28 — "give me option to cancel changes"). Until
                now the only way out of a wrong AI suggestion or a mistyped row
                was to reload the page: the inputs are local pending state, so
                nothing reverted them. Clears every pending edit and the
                AI-suggested highlighting in one go; nothing was ever written, so
                there's nothing to undo server-side. */}
            <button className="btn btn-ghost" style={{ fontSize: 12.5, padding: "6px 12px" }}
              onClick={() => { setEdits({}); setAiSuggestedIds(new Set()); }} disabled={savingAll}>
              <X size={13} /> {t("Discard")}
            </button>
            <button className="btn btn-primary" style={{ fontSize: 12.5, padding: "6px 14px" }}
              onClick={saveAllEdits} disabled={savingAll}>
              {savingAll ? t("Saving…") : `${t("Save all")} (${Object.keys(edits).length})`}
            </button>
          </div>
        </div>
      )}

      <div className="card" style={{ overflow: "hidden" }}>
        <table className="table">
          <thead>
            <tr>
              <th>{t("Name")}</th>
              <th>{t("Coach")}</th>
              <th>{t("Hotel")}</th>
              <th>{t("Room number")}</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {rowsShown.map((d) => {
              const f = fieldFor(d);
              const dirty = edits[d.id] !== undefined;
              const aiSuggested = aiSuggestedIds.has(d.id);
              return (
                <tr key={d.id} style={aiSuggested ? { background: "var(--st-assigned-bg)" } : undefined}>
                  <td>{d.name}{aiSuggested && <Sparkles size={12} color="var(--scc-red)" style={{ marginLeft: 6, verticalAlign: "middle" }} />}</td>
                  <td className="muted">{coachName(d.coachId)}</td>
                  <td>
                    <input className="input" style={{ fontSize: 13 }} value={f.hotelName}
                      onChange={(e) => setField(d, "hotelName", e.target.value)} placeholder={t("Hotel")} />
                  </td>
                  <td>
                    {/* Increment/decrement stepper (2026-07-27 — "option to
                        do increment for the room number") — handy for
                        assigning consecutive rooms down a delegate list
                        without retyping the whole number each time. */}
                    <div className="row" style={{ gap: 4, alignItems: "center" }}>
                      <button
                        className="btn btn-ghost" style={{ padding: "4px 6px", flexShrink: 0 }}
                        aria-label={t("Decrease room number")}
                        onClick={() => setField(d, "roomNumber", bumpRoomNumber(f.roomNumber, -1))}
                      >
                        <Minus size={12} />
                      </button>
                      <input className="input" style={{ fontSize: 13, maxWidth: 90, textAlign: "center" }} value={f.roomNumber}
                        onChange={(e) => setField(d, "roomNumber", e.target.value)} placeholder={t("Room")} />
                      <button
                        className="btn btn-ghost" style={{ padding: "4px 6px", flexShrink: 0 }}
                        aria-label={t("Increase room number")}
                        onClick={() => setField(d, "roomNumber", bumpRoomNumber(f.roomNumber, 1))}
                      >
                        <Plus size={12} />
                      </button>
                    </div>
                  </td>
                  <td>
                    {dirty && (
                      <button className="btn btn-ghost" style={{ fontSize: 12.5, padding: "4px 10px" }}
                        onClick={() => save(d)} disabled={savingId === d.id}>
                        {savingId === d.id ? t("Saving…") : t("Save")}
                      </button>
                    )}
                  </td>
                </tr>
              );
            })}
            {filtered.length === 0 && (
              <tr><td colSpan={5} className="muted" style={{ textAlign: "center", padding: 20 }}>{t("No delegates match your search.")}</td></tr>
            )}
          </tbody>
        </table>
        {filtered.length > 0 && (
          <div className="row between" style={{ padding: "12px 20px", borderTop: "1px solid var(--line)", flexWrap: "wrap", gap: 10 }}>
            <span className="muted" style={{ fontSize: 12.5 }}>
              {t("Showing")} {clampedPage * pageSize + 1}–{Math.min((clampedPage + 1) * pageSize, filtered.length)} {t("of")} {filtered.length}
            </span>
            <div className="row" style={{ gap: 8, alignItems: "center" }}>
              <span className="muted" style={{ fontSize: 12.5 }}>{t("Rows per page")}</span>
              <select className="select" style={{ width: 76, padding: "4px 8px" }} value={pageSize}
                onChange={(e) => setPageSize(Number(e.target.value))}>
                {[10, 25, 50, 100].map((n) => <option key={n} value={n}>{n}</option>)}
              </select>
            </div>
            <div className="row" style={{ gap: 8, alignItems: "center" }}>
              <button className="btn btn-ghost" style={{ padding: "4px 10px" }} disabled={clampedPage === 0}
                onClick={() => setPage((p) => Math.max(0, p - 1))}>
                <ChevronLeft size={14} /> {t("Prev")}
              </button>
              <span className="muted" style={{ fontSize: 12.5 }}>{t("Page")} {clampedPage + 1} {t("of")} {pageCount}</span>
              <button className="btn btn-ghost" style={{ padding: "4px 10px" }} disabled={clampedPage >= pageCount - 1}
                onClick={() => setPage((p) => Math.min(pageCount - 1, p + 1))}>
                {t("Next")} <ChevronRight size={14} />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/** Checkpoint history — trip-wide "view past status of delegate" (2026-07-27
 *  — "currently i not able to see the past itinerary, i want to be able to
 *  view past status of delegate"). Previously only reachable one delegate at
 *  a time (their profile panel's DelegateTimeline), buried inside each
 *  individual record; this surfaces it as its own Dashboard tab instead. UI
 *  deliberately styled as a simple search + flat list (2026-07-27 — "i quite
 *  like [the Scanner's Manual tab's] simple list-style ui, just not the
 *  override functionality itself") — a plain searchable list of delegates,
 *  each expandable in place to show their real per-checkpoint history via
 *  the EXISTING `GET /delegates/:id/checkpoint-timeline` endpoint (already
 *  coach-scoped server-side, same as every other delegate read — nothing new
 *  needed there). Fetched lazily per-delegate on first expand, not all
 *  upfront, so opening this tab with a large roster doesn't fire N requests
 *  before anyone's even clicked anything. */
/**
 * Checkpoint history — every delegate's attendance across every itinerary stop,
 * as a CARD GRID (2026-07-28 — "instead of seeing one by one", modelled on a
 * live-headcount board the user shared).
 *
 * It replaced an expand-one-at-a-time list, which had two problems: you had to
 * click through the roster to answer "who's been missing today", and it
 * lazy-loaded one request PER delegate. Now a single
 * `GET /api/trips/:id/checkpoint-matrix` returns the whole grid, so every
 * delegate is scannable at once and it scales to a real roster.
 *
 * Each card carries one small chip per stop (colour = status), so a pattern like
 * "fine all week, missing since lunch" is visible without opening anything.
 * Clicking a card still expands the full stop-by-stop detail.
 */
const CPT_STATUS_LABEL = { ARRIVED: "Arrived", LATE: "Late", MISSING: "Missing" };

function CheckpointHistoryTab({ coaches, t, tripId }) {
  const [query, setQuery] = useState("");
  const [coachFilter, setCoachFilter] = useState("ALL");   // ALL | NONE | <coachId>
  const [attFilter, setAttFilter] = useState("ALL");       // ALL | CLEAN | ISSUES
  const [dayFilter, setDayFilter] = useState("ALL");       // ALL | <dayNumber>
  // Single-stop drill-down (2026-07-29 — "under the day filter, add filter to
  // see that specific itinerary, so i can see how many was late, arrived,
  // missing for that specific time"). Narrowing `visibleStops` to one stop is
  // all it takes: every count on this tab is already derived from that array
  // (see tally() below), so the summary strip, the chips and the attendance
  // filters all scope themselves to the chosen stop automatically.
  const [stopFilter, setStopFilter] = useState("ALL");     // ALL | <stopId>
  const [expandedId, setExpandedId] = useState(null);
  const [data, setData] = useState(null);                   // { stops, delegates, totalStops }
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let alive = true;
    setLoading(true);
    setError(null);
    apiGet(`/trips/${tripId}/checkpoint-matrix`)
      .then((r) => { if (alive) { setData(r); setLoading(false); } })
      .catch((e) => { if (alive) { setError(e.message || "Could not load checkpoint history."); setLoading(false); } });
    return () => { alive = false; };
  }, [tripId]);

  const stops = data?.stops || [];
  const rows = data?.delegates || [];

  // ---- Day handling (2026-07-28 — "can you sort by date instead? like day 1,
  // day 2, day 3"). The backend already returns stops in day/time order, but a
  // flat run of 20 chips gave no clue where one day ended and the next began.
  // So: a Day filter, and when showing every day the chips are GROUPED with a
  // small D1/D2/D3 label per group.
  const days = [...new Set(stops.map((s) => s.dayNumber))].sort((a, b) => a - b);
  // Day narrows first, then the optional single-stop pick narrows within it.
  const dayStops = dayFilter === "ALL" ? stops : stops.filter((s) => s.dayNumber === Number(dayFilter));
  const selectedStop = stopFilter === "ALL" ? null : dayStops.find((s) => s.id === stopFilter) || null;
  const visibleStops = selectedStop ? [selectedStop] : dayStops;

  // A stop chosen on Day 1 doesn't exist once you switch to Day 2, so the
  // selection is dropped whenever it falls outside the current day — otherwise
  // `visibleStops` would silently go empty and every count would read 0.
  useEffect(() => {
    if (stopFilter !== "ALL" && !dayStops.some((s) => s.id === stopFilter)) setStopFilter("ALL");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dayFilter, stops]);
  // Group the stops actually on screen, preserving day order.
  const stopGroups = days
    .map((day) => ({ day, items: visibleStops.filter((s) => s.dayNumber === day) }))
    .filter((g) => g.items.length > 0);

  // Counts are recomputed over the stops CURRENTLY SHOWN rather than reusing the
  // server's whole-trip totals — otherwise filtering to Day 2 would show Day 2's
  // chips next to trip-wide numbers, which is exactly the kind of quiet
  // mismatch that makes a dashboard untrustworthy.
  function tally(d) {
    let arrived = 0, late = 0, missing = 0, recorded = 0;
    for (const s of visibleStops) {
      const cell = d.cells[s.id];
      if (!cell) continue;
      recorded += 1;
      if (cell.status === "ARRIVED") arrived += 1;
      else if (cell.status === "LATE") late += 1;
      else if (cell.status === "MISSING") missing += 1;
    }
    return { arrived, late, missing, recorded };
  }
  const counted = rows.map((d) => ({ ...d, ...tally(d) }));

  const totals = {
    delegates: counted.length,
    clean: counted.filter((d) => d.missing === 0 && d.late === 0).length,
    issues: counted.filter((d) => d.missing > 0 || d.late > 0).length,
  };

  // With one stop selected, "how many arrived / were late / missing at THIS
  // time" is the whole question being asked, so the summary strip switches to
  // answering exactly that instead of trip-wide roll-ups. Computed over the
  // same full roster the other strip tiles use, so the four numbers always sum
  // to the delegate count. "No record" is the honest fourth bucket: a delegate
  // with no check-in row for this stop is neither present nor confirmed
  // absent, and folding them into Missing would overstate the problem.
  const stopTotals = selectedStop
    ? counted.reduce((acc, d) => {
      const status = d.cells[selectedStop.id]?.status;
      if (status === "ARRIVED") acc.arrived += 1;
      else if (status === "LATE") acc.late += 1;
      else if (status === "MISSING") acc.missing += 1;
      else acc.noRecord += 1;
      return acc;
    }, { arrived: 0, late: 0, missing: 0, noRecord: 0 })
    : null;

  const visible = counted
    .filter((d) => !query.trim() || d.name.toLowerCase().includes(query.trim().toLowerCase()))
    .filter((d) => {
      if (coachFilter === "ALL") return true;
      if (coachFilter === "NONE") return !d.coachId;
      return d.coachId === coachFilter;
    })
    .filter((d) => {
      if (attFilter === "CLEAN") return d.missing === 0 && d.late === 0;
      if (attFilter === "ISSUES") return d.missing > 0 || d.late > 0;
      return true;
    });

  const toneFor = (status) =>
    status === "ARRIVED" ? { bg: "var(--st-present-bg)", fg: "var(--st-present)" }
      : status === "LATE" ? { bg: "var(--st-late-bg)", fg: "var(--st-late)" }
        : status === "MISSING" ? { bg: "var(--st-missing-bg)", fg: "var(--st-missing)" }
          : { bg: "var(--surface-2)", fg: "var(--line)" }; // no record yet

  const ATT_FILTERS = [
    ["ALL", t("All"), totals.delegates],
    ["ISSUES", t("Late or missing"), totals.issues],
    ["CLEAN", t("Full attendance"), totals.clean],
  ];

  return (
    <div style={{ marginTop: 20 }}>
      <p className="page-sub" style={{ margin: "0 0 14px" }}>
        {t("Every delegate's status at every itinerary stop — click a card for the full timeline.")}
      </p>

      {/* ---- Summary strip ------------------------------------------------ */}
      {/* Two modes: trip/day roll-ups normally, or that ONE stop's
          arrived/late/missing split when a single stop is selected below. */}
      {selectedStop && (
        <div className="row" style={{ gap: 8, marginBottom: 8, flexWrap: "wrap", alignItems: "center" }}>
          <Clock size={14} color="var(--scc-red)" />
          <strong style={{ fontSize: 14 }}>{selectedStop.label}</strong>
          <span className="muted" style={{ fontSize: 12.5 }}>
            {t("Day")} {selectedStop.dayNumber}{selectedStop.scheduledTime ? ` · ${fmt12h(selectedStop.scheduledTime)}` : ""}
          </span>
        </div>
      )}
      <div className="card" style={{ padding: "14px 18px", marginBottom: 14, display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(140px, 1fr))", gap: 14 }}>
        {(stopTotals
          ? [
            [t("Arrived"), stopTotals.arrived, "var(--st-present)"],
            [t("Late"), stopTotals.late, "var(--st-late)"],
            [t("Missing"), stopTotals.missing, "var(--st-missing)"],
            [t("No record"), stopTotals.noRecord, "var(--ink-3)"],
          ]
          : [
            [t("Delegates"), totals.delegates, "var(--ink)"],
            // Reflects the day filter, so it agrees with the chips on the cards.
            [dayFilter === "ALL" ? t("Itinerary stops") : `${t("Stops on day")} ${dayFilter}`, visibleStops.length, "var(--ink)"],
            [t("Full attendance"), totals.clean, "var(--st-present)"],
            [t("Late or missing"), totals.issues, "var(--st-missing)"],
          ]
        ).map(([label, value, color]) => (
          <div key={label}>
            <div className="muted" style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: 0.4 }}>{label}</div>
            <div style={{ fontSize: 26, fontWeight: 700, color, lineHeight: 1.2 }}>{value}</div>
          </div>
        ))}
      </div>

      {/* ---- Search + filters -------------------------------------------- */}
      <div className="row" style={{ gap: 10, marginBottom: 14, flexWrap: "wrap" }}>
        <div style={{ position: "relative", maxWidth: 240, flex: "1 1 180px" }}>
          <Search size={15} style={{ position: "absolute", left: 10, top: "50%", transform: "translateY(-50%)", color: "var(--ink-3)" }} />
          <input className="input" style={{ paddingLeft: 32 }} placeholder={t("Search name…")}
            value={query} onChange={(e) => setQuery(e.target.value)} />
        </div>
        <select className="select" style={{ maxWidth: 190 }} value={coachFilter} onChange={(e) => setCoachFilter(e.target.value)}>
          <option value="ALL">{t("All coaches")}</option>
          <optgroup label={t("Coaches")}>
            {coaches.map((c) => (
              <option key={c.id} value={c.id}>{coachDisplayName(c)}</option>
            ))}
          </optgroup>
          <optgroup label={t("Other")}>
            <option value="NONE">{t("Unassigned")}</option>
          </optgroup>
        </select>
        <div className="row" style={{ gap: 6, flexWrap: "wrap" }}>
          {ATT_FILTERS.map(([key, label, n]) => (
            <button key={key} type="button" onClick={() => setAttFilter(key)}
              style={{
                fontSize: 12.5, fontWeight: 600, padding: "6px 12px", borderRadius: 999, cursor: "pointer",
                background: attFilter === key ? "var(--scc-red-tint)" : "var(--surface-2)",
                color: attFilter === key ? "var(--scc-red)" : "var(--ink-2)",
                border: `1px solid ${attFilter === key ? "var(--scc-red)" : "var(--line)"}`,
              }}>
              {label} <span style={{ opacity: 0.7 }}>{n}</span>
            </button>
          ))}
        </div>
      </div>

      {/* ---- Day filter --------------------------------------------------- */}
      {days.length > 1 && (
        <div className="row" style={{ gap: 6, marginBottom: 14, flexWrap: "wrap", alignItems: "center" }}>
          <span className="muted" style={{ fontSize: 11.5, textTransform: "uppercase", letterSpacing: 0.4, marginRight: 2 }}>
            {t("Day")}
          </span>
          {/* No per-day stop count here (2026-07-28 — "what is this number
              beside the day? i think remove it"): "Day 1 5" read as "Day 15".
              The count lives in the summary strip's "Stops on day N" tile,
              which updates with the selection anyway. */}
          {[["ALL", t("All days")], ...days.map((n) => [String(n), `${t("Day")} ${n}`])]
            .map(([key, label]) => (
              <button key={key} type="button" onClick={() => setDayFilter(key)}
                title={key === "ALL"
                  ? `${stops.length} ${t("stops")}`
                  : `${stops.filter((s) => s.dayNumber === Number(key)).length} ${t("stops")}`}
                style={{
                  fontSize: 12.5, fontWeight: 600, padding: "5px 11px", borderRadius: 999, cursor: "pointer",
                  background: dayFilter === key ? "var(--scc-red-tint)" : "var(--surface-2)",
                  color: dayFilter === key ? "var(--scc-red)" : "var(--ink-2)",
                  border: `1px solid ${dayFilter === key ? "var(--scc-red)" : "var(--line)"}`,
                }}>
                {label}
              </button>
            ))}
        </div>
      )}

      {/* ---- Itinerary stop filter (2026-07-29) ---------------------------
          "add filter to see that specific itinerary, so i can see how many was
          late, arrived, missing for that specific time". A <select> rather than
          another chip row: stop names are long ("Airport departure transfer")
          and there can be 20+ across a trip, so chips would wrap into a wall.
          Options carry the time, since two stops can share a name across days.
          Selecting one re-points the whole tab — summary strip, per-card chips
          and counts — at that single stop. */}
      {dayStops.length > 0 && (
        <div className="row" style={{ gap: 8, marginBottom: 14, flexWrap: "wrap", alignItems: "center" }}>
          <span className="muted" style={{ fontSize: 11.5, textTransform: "uppercase", letterSpacing: 0.4, marginRight: 2 }}>
            {t("Stop")}
          </span>
          <select
            className="select"
            style={{ maxWidth: 330 }}
            value={stopFilter}
            onChange={(e) => setStopFilter(e.target.value)}
          >
            <option value="ALL">
              {dayFilter === "ALL"
                ? `${t("All stops")} (${dayStops.length})`
                : `${t("All stops on day")} ${dayFilter} (${dayStops.length})`}
            </option>
            {dayStops.map((s) => (
              <option key={s.id} value={s.id}>
                {dayFilter === "ALL" ? `${t("Day")} ${s.dayNumber} · ` : ""}
                {s.scheduledTime ? `${fmt12h(s.scheduledTime)} · ` : ""}{s.label}
              </option>
            ))}
          </select>
          {selectedStop && (
            <button
              type="button"
              className="btn btn-ghost"
              style={{ padding: "5px 10px", fontSize: 12 }}
              onClick={() => setStopFilter("ALL")}
            >
              <X size={13} /> {t("Clear")}
            </button>
          )}
        </div>
      )}

      {loading && <div className="muted" style={{ fontSize: 13 }}>{t("Loading…")}</div>}
      {error && <div style={{ color: "var(--st-missing)", fontSize: 13 }}>{t(error)}</div>}

      {!loading && !error && stops.length === 0 && (
        <div className="card muted" style={{ padding: 24, textAlign: "center", fontSize: 13.5 }}>
          {t("No itinerary stops on this trip yet — nothing to show a history for.")}
        </div>
      )}

      {!loading && !error && stops.length > 0 && visible.length === 0 && (
        <div className="card muted" style={{ padding: 24, textAlign: "center", fontSize: 13.5 }}>
          {t("No delegates match these filters.")}
        </div>
      )}

      {/* ---- Card grid --------------------------------------------------- */}
      {!loading && !error && visible.length > 0 && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(290px, 1fr))", gap: 14 }}>
          {visible.map((d) => {
            const isOpen = expandedId === d.id;
            const hasIssue = d.missing > 0 || d.late > 0;
            return (
              <div key={d.id} className="card"
                style={{ padding: 0, overflow: "hidden", borderColor: hasIssue ? "var(--st-missing-bg)" : "var(--line)" }}>
                <button
                  onClick={() => setExpandedId(isOpen ? null : d.id)}
                  className="row between"
                  style={{ width: "100%", padding: "12px 14px 10px", background: "none", border: "none", cursor: "pointer", textAlign: "left", gap: 10 }}
                >
                  <div className="row" style={{ gap: 10, minWidth: 0 }}>
                    <DelegateAvatar delegate={d} />
                    <div style={{ minWidth: 0 }}>
                      <div className="row" style={{ gap: 5, minWidth: 0 }}>
                        <span style={{ fontWeight: 600, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{d.name}</span>
                        {d.vip && <Crown size={12} color="#e0a800" style={{ flexShrink: 0 }} />}
                      </div>
                      <div className="muted" style={{ fontSize: 11.5 }}>{d.coachLabel || t("Unassigned")}</div>
                    </div>
                  </div>
                  {isOpen ? <ChevronUp size={16} className="muted" /> : <ChevronDown size={16} className="muted" />}
                </button>

                {/* Chips grouped BY DAY, each group labelled D1/D2/… so you can
                    tell at a glance which day a run of red belongs to. When a
                    single day is selected the label is dropped (the filter above
                    already says which day you're looking at). */}
                <div style={{ display: "flex", flexWrap: "wrap", gap: 10, padding: "0 14px 10px" }}>
                  {stopGroups.map((g) => (
                    <div key={g.day} style={{ display: "flex", flexDirection: "column", gap: 3 }}>
                      {dayFilter === "ALL" && (
                        <span className="muted" style={{ fontSize: 9.5, fontWeight: 700, letterSpacing: 0.3 }}>
                          D{g.day}
                        </span>
                      )}
                      <div style={{ display: "flex", gap: 3 }}>
                        {g.items.map((s) => {
                          const cell = d.cells[s.id];
                          const tone = toneFor(cell?.status);
                          const label = cell ? t(CPT_STATUS_LABEL[cell.status] || cell.status) : t("No record");
                          return (
                            <span key={s.id}
                              title={`${t("Day")} ${s.dayNumber} · ${s.scheduledTime ? fmt12h(s.scheduledTime) : ""} ${s.label} — ${label}`}
                              style={{
                                width: 15, height: 15, borderRadius: 4, background: tone.bg,
                                border: `1px solid ${tone.fg}`, flexShrink: 0,
                              }} />
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>

                <div className="row" style={{ padding: "7px 14px", borderTop: "1px solid var(--line)", fontSize: 11.5, gap: 10, flexWrap: "wrap" }}>
                  <span style={{ color: "var(--st-present)", fontWeight: 600 }}>{d.arrived} {t("arrived")}</span>
                  <span style={{ color: "var(--st-late)", fontWeight: 600 }}>{d.late} {t("late")}</span>
                  <span style={{ color: "var(--st-missing)", fontWeight: 600 }}>{d.missing} {t("missing")}</span>
                  <span className="muted" style={{ marginLeft: "auto" }}>{d.recorded}/{visibleStops.length}</span>
                </div>

                {isOpen && (
                  <div style={{ padding: "10px 14px 14px", borderTop: "1px solid var(--line)", background: "var(--surface-2)", display: "flex", flexDirection: "column", gap: 7, maxHeight: 320, overflowY: "auto" }}>
                    {/* Only the stops in view, so the detail matches the chips
                        above it when a day is selected. */}
                    {visibleStops.map((s) => {
                      const cell = d.cells[s.id];
                      return (
                        <div key={s.id} className="row between" style={{ gap: 10, fontSize: 12.5 }}>
                          <div className="row" style={{ gap: 7, minWidth: 0 }}>
                            <Clock size={12} color="var(--ink-3)" style={{ flexShrink: 0 }} />
                            <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                              {t("Day")} {s.dayNumber} · {s.label}{s.scheduledTime ? ` · ${fmt12h(s.scheduledTime)}` : ""}
                            </span>
                          </div>
                          {cell
                            ? <StatusBadge state={cell.status} />
                            : <span className="muted" style={{ fontSize: 11.5, flexShrink: 0 }}>{t("No record")}</span>}
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* ---- Local styles ------------------------------------------------------- */
const S = {
  dot: { width: 10, height: 10, borderRadius: 999, background: "var(--st-present)", display: "inline-block", flexShrink: 0 },
  /* Header fact chips (2026-07-29) — day / local time / delegate count / the
     live stop. Replaces the single "·"-joined sentence, which forced you to
     read the whole string to find one number. Deliberately quieter than
     .badge (plain border, --ink-2 text) so four of them in a row read as
     metadata, not as four status alerts. */
  metaChip: {
    display: "inline-flex", alignItems: "center", gap: 5,
    fontSize: 12.5, color: "var(--ink-2)",
    padding: "4px 9px", borderRadius: 999,
    border: "1px solid var(--line)", background: "var(--surface-2)",
    whiteSpace: "nowrap", minWidth: 0,
  },
  twoCol: { display: "grid", gridTemplateColumns: "1.3fr 1fr", gap: 16, marginTop: 20 },
  track: { height: 8, borderRadius: 999, background: "var(--line)", overflow: "hidden" },
  fill: { height: "100%", borderRadius: 999, transition: "width 0.4s ease" },
  iconBtn: { background: "none", border: "none", color: "var(--ink-3)", display: "flex", padding: 4, borderRadius: 6 },
  overlay: { position: "fixed", inset: 0, background: "rgba(16,24,40,0.45)", display: "grid", placeItems: "center", padding: 20, zIndex: 50 },
  modal: { width: "min(440px, 100%)", maxHeight: "calc(100vh - 48px)", overflowY: "auto", padding: 24, background: "var(--surface)" },
  iconBadge: { width: 32, height: 32, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 },
};
